window.__ARXIV_DATA__ = {"papers":[{"id":"2610.12470v1","title":"Dex-One2Many: Learning Dexterous Manipulation from a Single Human Demonstration","abstract":"While learning dexterous manipulation from a single human video offers a promising alternative to costly robot demonstrations, many recent methods predominantly imitate demonstrated motions. Such strict motion matching often limits generalization to initial object poses, goal poses, and grasps not shown in the video. Alternatively, discovering a policy via reinforcement learning (RL) allows for broad generalization, but without prior guidance, it struggles with high-dimensional exploration in complex, multi-stage tasks. To address these coupled generalization and exploration challenges, we present Dex-One2Many, a real-to-sim-to-real framework that learns a generalizable dexterous manipulation policy from a single human video. Our key insight is to abstract the video into sequential scene graphs that guide RL, enabling efficient exploration while preserving broad generalizability. The graphs serve as generative constraints for sampling diverse reset states and provide dense rewards for each stage. Because the graphs constrain relations rather than exact poses, these reset states cover object poses and grasps beyond the video, while initializing each stage from them with dense rewards keeps exploration short and guided. Trained entirely in simulation, Dex-One2Many transfers zero-shot to a real multi-fingered hand. Across five tool-use and manipulation tasks, Dex-One2Many exceeds baselines by 6.5% in seen configurations, while its robust generalization widens this gap to 71% in unseen scenarios.","authors":["Jusuk Lee","Sungha Kim","Yeonsoo Park","Jonguk Cheon","Yoonkyo Jung","Yongjun You","H. Jin Kim","Jia-Bin Huang","Furong Huang","Youngseok Jang","Seungjae Lee"],"published":"2026-10-08T17:59:58Z","updated":"2026-10-08T17:59:58Z","abstract_url":"https://arxiv.org/abs/2610.12470v1","html_url":"https://arxiv.org/html/2610.12470v1","pdf_url":"https://arxiv.org/pdf/2610.12470v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":117436,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：While learning dexterous manipulation from a single human video offers a promising alternative to costly robot demonstrations, many recent methods predominantly imitate demonstrated motions. Such strict motion matching often limits generalization to initial o...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:13+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12469v1","title":"Rubric-CEPR: Self-Evolving Image Editing via Reward-Verified Self-Distillation","abstract":"Instruction-guided image editors have become highly capable, yet improving them further still depends on human-edited training pairs or external reward models. Such supervision is costly to obtain and can reward plausible failures: a realistic output may leave the requested change undone or alter content that should be preserved. In this work, we strive to improve a pretrained image editor using only its own generations, without human-edited targets or an external training-time reward model. To this end, we propose a self-evolving framework, named Rubric-CEPR, that verifies the editor's own samples with its internal representations through a rubric-augmented Contrastive Edit-Preservation Reward (CEPR). A Planner proposes structured edit instructions from unlabeled images, the Editor samples multiple candidate edits, and a frozen Critic scores each candidate with decomposed rubric checks for edit realization, removal of the old state, and content preservation, using features already exposed by the editor. Non-compensatory gates reject infeasible candidates, and the best verified candidate is distilled into the editor through lightweight adapter training. On Qwen-Image-Edit, Rubric-CEPR improves ImgEdit from 4.36 to 4.60 (+5.5%), with a +24.9% gain on object isolation, and transfers to GEdit-Bench and Complex-Edit. The same procedure also improves Step1X-Edit by +7.8% on ImgEdit. We hope our approach will serve as a solid baseline for image editors that improve themselves from their own verified samples. Our code is publicly available at $\\href{https://riteshthawkar.github.io/Rubric-CEPR/}{\\text{this URL}}$","authors":["Ritesh Thawkar","Shubham Patle","Shravan Venkatraman","Rao Muhammad Anwer"],"published":"2026-10-08T17:59:58Z","updated":"2026-10-08T17:59:58Z","abstract_url":"https://arxiv.org/abs/2610.12469v1","html_url":"https://arxiv.org/html/2610.12469v1","pdf_url":"https://arxiv.org/pdf/2610.12469v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":88183,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Instruction-guided image editors have become highly capable, yet improving them further still depends on human-edited training pairs or external reward models. Such supervision is costly to obtain and can reward plausible failures: a realistic output may leav...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:13+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12468v1","title":"DreamTrue: Action-Faithful Robot World Model with Counterfactual Post-Training","abstract":"We present DreamTrue, a multi-view, cross-embodiment robot world model for action-faithful and physically plausible video prediction. Training such a model on existing robot datasets faces two obstacles: imprecise calibration can impair action following, while limited coverage of unsuccessful interactions can bias predictions toward successful outcomes. To improve action following across embodiments, we render action trajectories into image-space conditions and introduce offline geometric calibration to align these conditions with the target videos. To broaden interaction coverage, we introduce counterfactual post-training, modifying recorded action trajectories and generating future videos under a wider range of actions and contact configurations. To provide feedback on these predictions without paired ground-truth futures, we construct a human-annotated video dataset covering robot, object, and interaction defects and use it to train an embodied video reward model. Its scores guide reinforcement-learning post-training toward more physically plausible interaction outcomes. On AgiBot, DreamTrue attains state-of-the-art action following, while reducing the human-assessed interaction defect rate from from 48.12% to 6.25%. Notably, our model ranks first in the world model track of the AgiBot World Challenge 2026. The project page can be found at https://brave-eai.github.io/DreamTrue.","authors":["Junyan Li","Ruizhi Li","Yu Liu","Xiangshuo Liu","Mingchao Sun","Hongyu Pan","Mu Xu","Lue Fan","Zhaoxiang Zhang"],"published":"2026-10-08T17:59:51Z","updated":"2026-10-08T17:59:51Z","abstract_url":"https://arxiv.org/abs/2610.12468v1","html_url":"https://arxiv.org/html/2610.12468v1","pdf_url":"https://arxiv.org/pdf/2610.12468v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":77791,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：We present DreamTrue, a multi-view, cross-embodiment robot world model for action-faithful and physically plausible video prediction. Training such a model on existing robot datasets faces two obstacles: imprecise calibration can impair action following, whil...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:13+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12464v1","title":"What 30,000 Hours of Ego-centric Video Does Not Teach","abstract":"World models offer a promising alternative to physics-based simulators, yet remain far from practical deployment. We ask how far scaling ego-centric human video takes them, using a dataset of 30,000 hours spanning over 1,000 scene types and 14,000 contributors. Rather than relying on opaque downstream metrics, we directly evaluate agent and object-interaction fidelity on a challenging out-of-distribution benchmark. Increasing training data by 100x improves both, but unevenly: the agent is modeled well, while object fidelity remains far lower and improves slowly. We show that the agent gains need not come from data, and a careful visual conditioning design saturates fidelity with a fraction of it, which lets us measure object fidelity on its own and discover its saturation point. We then introduce a supervision scheme that shifts capacity from scene appearance toward object dynamics, improving object fidelity though a substantial gap remains. Finally, our conclusions transfer to downstream humanoid modeling. Overall, our results suggest that scaling ego-centric data brings agent modeling close to its limit while leaving its effects on the world far behind, and that closing this gap will depend on how models are trained, not only on how much data they see.","authors":["Jiahua Dong","Anurag Bagchi","Yash Jangir","Muhammad Zubair Irshad","Sergey Zakharov","Martial Hebert","Homanga Bharadhwaj","Yu-Xiong Wang","Vitor Campagnolo Guizilini","Pavel Tokmakov"],"published":"2026-10-08T17:59:49Z","updated":"2026-10-08T17:59:49Z","abstract_url":"https://arxiv.org/abs/2610.12464v1","html_url":"https://arxiv.org/html/2610.12464v1","pdf_url":"https://arxiv.org/pdf/2610.12464v1.pdf","matched_keywords":["video","agent"],"source_used":"html","source_text_chars":85483,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, agent 相关；摘要显示其主要贡献为：World models offer a promising alternative to physics-based simulators, yet remain far from practical deployment. We ask how far scaling ego-centric human video takes them, using a dataset of 30,000 hours spanning over 1,000 scene types and 14,000 contributor...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:13+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12461v1","title":"OuroWorld: Bringing Any 3D World Alive as Diverse, Endlessly Looping 3D Cinemagraphs","abstract":"Recent 3D world models generate photorealistic, explorable scenes that remain frozen in time. OuroWorld is a mask-free framework that turns any static 3D Gaussian Splatting scene into a 3D cinemagraph: a dynamic scene with vivid, diverse motion looping seamlessly from any viewpoint. A vision-language model infers plausible dynamics and guides a video model to synthesize a reference video, which we lift and complete into multi-view videos. To learn from this imperfect supervision, we propose Inconsistency-Robust Periodic 4DGS: a Fourier-series deformation field guarantees looping by construction, while a Grounded Drift Field anchored at the reference view absorbs cross-view inconsistency. Unlike prior Eulerian methods limited to fluid-like motion, we capture general deformation, object motion, and illumination change. We introduce a ground-truth-free evaluation covering vividness, naturalness, loop seam coherence, and scene quality. On 39 reconstructed and generated scenes, OuroWorld outperforms all baselines and wins 70.8%-99.0% of user-study comparisons. Project page: https://ouroworld.userwei.com","authors":["You-Zhe Xie","Ting-Wei Chou","Yu-Hsuan Li","Kaipeng Zhang","Zhixiang Wang","Yu-Lun Liu"],"published":"2026-10-08T17:59:46Z","updated":"2026-10-08T17:59:46Z","abstract_url":"https://arxiv.org/abs/2610.12461v1","html_url":"https://arxiv.org/html/2610.12461v1","pdf_url":"https://arxiv.org/pdf/2610.12461v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":96188,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：Recent 3D world models generate photorealistic, explorable scenes that remain frozen in time. OuroWorld is a mask-free framework that turns any static 3D Gaussian Splatting scene into a 3D cinemagraph: a dynamic scene with vivid, diverse motion looping seamle...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:13+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12459v1","title":"WorldGuide: Goal-Directed Video World Model for Procedural Task Execution","abstract":"Video generators and video-based world models can synthesize plausible visual trajectories, but long-horizon procedural tasks require generation to adapt to what has actually been produced. A model must determine the next action from its generated state, execute that action, and recognize when the task is complete. Open-loop generation cannot adapt to execution outcomes, while existing closed-loop systems often rely on pretrained executors or indirect verification. This leaves a gap between deciding an action and successfully realizing it. We formulate procedural video generation as \\emph{closed-loop task execution in visual world space} and introduce \\textbf{WorldGuide}. Given only an initial image and a task goal, WorldGuide predicts an atomic action, generates its corresponding video clip, and uses the generated result to select the next action or terminate. The Planner and Executor are trained on the same step-level procedural demonstrations: the Planner learns to predict the next atomic action or task completion from visual progress, while the Executor is directly trained to realize the predicted actions. Hierarchical visual memory maintains state across long-horizon execution with bounded history token cost. Due to the lack of step-level action-video supervision for joint planner-executor training, we introduce \\textbf{WorldGuide Bench}: approximately 59K step-annotated videos across 245 tasks and 27 procedural categories. WorldGuide achieves a 33.33\\% Task Success on \\textbf{WorldGuide-Bench}, compared with 29.90\\% for the strong recent video model MiniMax-H3, even though MiniMax-H3 receives reference action plans, and achieves 47.69\\% on \\textbf{VideoCraft-Bench} compared with 32.73\\% for MiniMax-H3 under goal-only conditioning. These results demonstrate the importance of coupling planning with learned execution for goal-directed procedural video generation.","authors":["Ankan Deria","Komal Kumar","Hisham Cholakkal","Fahad Shahbaz Khan","Salman Khan"],"published":"2026-10-08T17:59:31Z","updated":"2026-10-08T17:59:31Z","abstract_url":"https://arxiv.org/abs/2610.12459v1","html_url":"https://arxiv.org/html/2610.12459v1","pdf_url":"https://arxiv.org/pdf/2610.12459v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":104055,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Video generators and video-based world models can synthesize plausible visual trajectories, but long-horizon procedural tasks require generation to adapt to what has actually been produced. A model must determine the next action from its generated state, exec...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:13+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12458v1","title":"OmniCapBench: A Deep-Structured Evaluation Framework for Fine-Grained Audio-Visual Captioning","abstract":"Multimodal large language models (MLLMs) are rapidly evolving toward continuous audio--visual reasoning, creating an urgent need for evaluations that expose their capability limits. Audio--visual captioning is an ideal diagnostic task, yet current benchmarks face a coupled trade-off: whole-caption scores provide coverage without localization, local probes provide localization without coverage, and unconstrained LLM judges introduce instability. We introduce OmniCapBench (Omni-Video Caption Benchmark), a benchmark that reframes audio--visual caption evaluation as a deep-structured diagnostic framework. OmniCapBench shifts the prediction target from free-form text to sets of atomic, verifiable evaluation units across three tracks: entity references, visual shots, and audio events, enabling reliable scoring with deterministic constraint checks and localized LLM-based semantic comparisons. With 786 densely annotated videos, OmniCapBench effectively distinguishes MLLM perception errors, including temporal grounding failures, identity drift, cross-modal misalignment, and hallucinated descriptions. Evaluating frontier MLLMs reveals strong local perception but weak long-horizon audio--visual reasoning, particularly in identity drift and cross-modal misalignment, providing a fine-grained roadmap for omnimodal development.","authors":["Zhongyu Yang","Jiale Tao","Ruitao Chen","Zuhao Yang","Yingfang Yuan","Xueliang Zhao","Auden","Kai Wang","Shuai Shao","Biao Wang","Steve Yves","Qinglin Lu"],"published":"2026-10-08T17:59:21Z","updated":"2026-10-08T17:59:21Z","abstract_url":"https://arxiv.org/abs/2610.12458v1","html_url":"https://arxiv.org/html/2610.12458v1","pdf_url":"https://arxiv.org/pdf/2610.12458v1.pdf","matched_keywords":["video","multimodal"],"source_used":"html","source_text_chars":162422,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, multimodal 相关；摘要显示其主要贡献为：Multimodal large language models (MLLMs) are rapidly evolving toward continuous audio--visual reasoning, creating an urgent need for evaluations that expose their capability limits. Audio--visual captioning is an ideal diagnostic task, yet current benchmarks...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:13+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12455v1","title":"Hybrid Cinematography: Previsualizing and Managing Hallucination Risk in Generative Video Reshooting","abstract":"On a film set, the camera move is committed during a take. Generative video reshooting lets filmmakers change it afterward, but may require hallucinating unrecorded content, a gap sometimes discovered only after leaving the set. We present Hybrid Cinematography, a workflow that bridges physical capture and generative reshooting to manage hallucination risk while filmmakers can still act on it. Using an editable 3D shot plan and a proxy of the take, our previsualization evaluates hallucination risk in real time. Seeing where the take lacks support, filmmakers can iteratively adjust the plan, explore moves that balance capture and generation, shoot guided pickups, or knowingly accept hallucination. We demonstrate the workflow through a mobile augmented reality application for on-set planning, capture, and review, and an offline pipeline for existing video. A study with experienced filmmakers reveals how previsualizing risk informs camera decisions and exposes tensions between creative intent and generative hallucination.","authors":["Nhan","Tran","Neal Wadhwa","Abe Davis","Stefan Stojanov"],"published":"2026-10-08T17:59:11Z","updated":"2026-10-08T17:59:11Z","abstract_url":"https://arxiv.org/abs/2610.12455v1","html_url":"https://arxiv.org/html/2610.12455v1","pdf_url":"https://arxiv.org/pdf/2610.12455v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":93360,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：On a film set, the camera move is committed during a take. Generative video reshooting lets filmmakers change it afterward, but may require hallucinating unrecorded content, a gap sometimes discovered only after leaving the set. We present Hybrid Cinematograp...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12452v1","title":"BrickBench: Evaluating Agentic Brick Design","abstract":"We propose BrickBench, a benchmark for agentic text-conditioned LEGO-set design. Given a prompt, an agent is tasked with producing an assembly that not only satisfies semantic and design criteria, but that can also be physically built. To do so, it must select parts from a discrete library and reason jointly about local and global constraints. We score validity, alignment, and design across three settings that vary in scale and part availability. We provide BrickAgent, an environment for coding agents to construct, inspect, and validate their designs. We find that leading agents largely satisfy verifiable physical and semantic requirements, but fall short of human designs. We release our benchmark and environment at http://www.brickben.ch","authors":["Peter Kulits","Yiqing Xu","R. Kenny Jones","Cordelia Schmid","Jiajun Wu"],"published":"2026-10-08T17:58:56Z","updated":"2026-10-08T17:58:56Z","abstract_url":"https://arxiv.org/abs/2610.12452v1","html_url":"https://arxiv.org/html/2610.12452v1","pdf_url":"https://arxiv.org/pdf/2610.12452v1.pdf","matched_keywords":["agent"],"source_used":"html","source_text_chars":58401,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent 相关；摘要显示其主要贡献为：We propose BrickBench, a benchmark for agentic text-conditioned LEGO-set design. Given a prompt, an agent is tasked with producing an assembly that not only satisfies semantic and design criteria, but that can also be physically built. To do so, it must selec...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12451v1","title":"VersaCamVLA: Camera-Configurable VLA Policies for Robotic Manipulation","abstract":"Vision-Language-Action (VLA) models have emerged as powerful foundations for robotic manipulation, but their reliance on fixed camera configurations during training makes them brittle to changes in camera count or pose during deployment. To overcome these limitations, we propose VersaCamVLA, a camera-configurable framework that decouples camera-set representation from action learning. VersaCamVLA learns a unified scene-token interface that maps an arbitrary, variable set of posed RGB views into fixed-size latent scene tokens. This is achieved via multi-signal target-view prediction and Wrist-Augmented Pose Sampling (WAPS), which leverages natural wrist-camera motion for free pose diversity. At deployment, a lightweight spatial encoder injects these compact scene tokens into a pretrained base VLA as a supplementary visual condition, requiring no explicit 3D sensing or novel-view rendering. Experiments on RoboTwin, LIBERO, and a real-robot platform demonstrate that VersaCamVLA consistently outperforms prior VLA methods and direct multi-view baselines, maintaining robust performance across varying camera counts and unseen camera poses.","authors":["Boyao Han","Chen Shi","Jingjing Qian","ZhuoTan Tian","Li Jiang"],"published":"2026-10-08T17:58:47Z","updated":"2026-10-08T17:58:47Z","abstract_url":"https://arxiv.org/abs/2610.12451v1","html_url":"https://arxiv.org/html/2610.12451v1","pdf_url":"https://arxiv.org/pdf/2610.12451v1.pdf","matched_keywords":["3d","representation"],"source_used":"html","source_text_chars":79426,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation 相关；摘要显示其主要贡献为：Vision-Language-Action (VLA) models have emerged as powerful foundations for robotic manipulation, but their reliance on fixed camera configurations during training makes them brittle to changes in camera count or pose during deployment. To overcome these lim...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12442v1","title":"LEGO: A Lifting-Free Approach for Exocentric-to-Egocentric Video Generation","abstract":"Generating an egocentric video from a single exocentric recording is a challenging case of novel view synthesis, as the two cameras share little overlap and much of the target view is unobserved. Current state-of-the-art methods reconstruct the scene explicitly by estimating depth, lifting the video into a point cloud, and re-rendering it from the egocentric camera to condition a video diffusion model. This deterministic mapping assigns each pixel to a single reprojected location, which preserves texture but translates depth errors into misplaced content. We ask what a video diffusion model should receive as its condition and propose a lifting-free answer: a learned view synthesizer, an LVSM-style transformer fine-tuned to render the egocentric view directly without depth, point clouds, or reprojection, resolving cross-view correspondence internally. In contrast, its probabilistic mapping averages each region over candidate source locations according to a learned correspondence distribution, preserving structure while fine texture is averaged away. We argue that this trade-off suits a diffusion generator, whose denoising training excels at restoring detail, so an effective condition should prioritize structural alignment over sharpness. This distribution's concentration also yields a per-region confidence, used both to mask low-confidence regions and to guide the generator toward high-confidence areas during early layout-forming denoising steps. Our approach consistently outperforms the state-of-the-art explicit pipeline and generalizes to other datasets without retraining. The synthesizer thus supplies view structure, and the diffusion model its detail.","authors":["Suhwan Cho","Yonwoo Choi","Soongjin Kim","Jicheol Park","Taegyu Lim"],"published":"2026-10-08T17:58:03Z","updated":"2026-10-08T17:58:03Z","abstract_url":"https://arxiv.org/abs/2610.12442v1","html_url":"https://arxiv.org/html/2610.12442v1","pdf_url":"https://arxiv.org/pdf/2610.12442v1.pdf","matched_keywords":["video","diffusion"],"source_used":"html","source_text_chars":74874,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, diffusion 相关；摘要显示其主要贡献为：Generating an egocentric video from a single exocentric recording is a challenging case of novel view synthesis, as the two cameras share little overlap and much of the target view is unobserved. Current state-of-the-art methods reconstruct the scene explicit...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12427v1","title":"FastBench: Can Streaming VLMs Perceive High-Dynamic Real-World Streams?","abstract":"Streaming Video Large Language Models (VLMs) enable continuous video understanding, yet existing benchmarks focus on low-dynamic scenarios. Under bounded context budgets, models must balance temporal history, spatial resolution, and temporal granularity; sparse sampling at 1--2 FPS misses fast events. We introduce FastBench to evaluate high-dynamic perception in real-world video streams. Its trajectory-grounded pipeline combines QA generation from high-FPS clips, filtering of questions answerable at 2 FPS, answer verification using SAM3 and CoTracker3 trajectories, and three rounds of human inspection. FastBench contains 306 QA pairs across eight domains, six capabilities, and forward, instant, and backward temporal scopes, with human-annotated evidence intervals. We also present ProactiveFrame, a training-free baseline that adjusts incoming frame rates through text tokens. A dual-tier sliding window retains recent high-FPS observations while downsampling older ones into sparse history. Experiments reveal substantial limitations: the strongest model, Gemini-3.5-Flash, scores only 50.7%. Denser sampling improves Qwen3-VL-8B from 32.9% at 2 FPS to 44.6% at 24 FPS, but gains saturate as history is compressed. ProactiveFrame outperforms sparse uniform sampling by 5.4 and 1.5 percentage points, yet remains well below oracle-guided focusing, showing that current VLMs struggle to determine from the stream alone when finer temporal perception is needed. FastBench provides a testbed for high-dynamic streaming video understanding. Code and data: https://github.com/Ashone3/FastBench.","authors":["Yuxuan Hu","Weikang Shi","Yang Bo","Xudong Lu","Xintong Guo","Shuhan Li","Yuyang He","Huankang Guan","Peiwen Sun","Yunqiao Yang","Wenbo Li","Rui Liu","Hongsheng Li"],"published":"2026-10-08T17:55:20Z","updated":"2026-10-08T17:55:20Z","abstract_url":"https://arxiv.org/abs/2610.12427v1","html_url":"https://arxiv.org/html/2610.12427v1","pdf_url":"https://arxiv.org/pdf/2610.12427v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":58579,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Streaming Video Large Language Models (VLMs) enable continuous video understanding, yet existing benchmarks focus on low-dynamic scenarios. Under bounded context budgets, models must balance temporal history, spatial resolution, and temporal granularity; spar...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12423v1","title":"Pumpire: Unified Benchmark for Metric Distance Estimation","abstract":"We present Pumpire, a unified benchmark for evaluating metric point-pair distance estimation capability of both image- and video-level 3D foundation models, with or without depth priors. In contrast to previous approaches that normally evaluate depth and camera intrinsics separately or evaluate point-clouds with geometric similarity metrics, which cannot directly reflect models' point-to-point distance estimation capability, Pumpire directly assesses point-to-point distances from the reconstructed geometry. To this end, we collect a large-scale and diverse dataset (pumpire-6k) comprising 100 real-world scenes, each annotated with physically measured point-pair distances and containing 64 frames, for a total of 6,400 frames. Building on this dataset, we establish a holistic evaluation protocol that covers both image- and video-level 3D foundation models and enables direct assessment of point-pair distance errors and cross-setting comparison. We conduct extensive experiments across 29 baseline configurations of representative 3D foundation models and provide a comprehensive analysis of the results. By offering this benchmark, we target the more fundamental ability to perceive and estimate physical scale in the reconstructed 3D space, which prior evaluation protocols have largely overlooked. The project page can be found at https://pumpire.github.io/","authors":["Siyu Chen","Zehan Wang","Jiayang Xu","Yihan Wu","Jialei Wang","Junming Chen","Ziang Zhang","Yutong Ying","Zhou Zhao"],"published":"2026-10-08T17:55:11Z","updated":"2026-10-08T17:55:11Z","abstract_url":"https://arxiv.org/abs/2610.12423v1","html_url":"https://arxiv.org/html/2610.12423v1","pdf_url":"https://arxiv.org/pdf/2610.12423v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":67052,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：We present Pumpire, a unified benchmark for evaluating metric point-pair distance estimation capability of both image- and video-level 3D foundation models, with or without depth priors. In contrast to previous approaches that normally evaluate depth and came...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12421v1","title":"Beyond Spatio-Temporal Priors: A Generalizable Approach for Dense Correspondence Matching","abstract":"Dense correspondence matching has historically been bounded by simplifying spatio-temporal priors, such as smooth motion and rigid geometry. While effective for classical tasks, these assumptions break down in image editing and reference-guided generation (IEG), where transformations can preserve visual identity while breaking physical continuity. To establish identity-preserving correspondence across such transformations, we introduce FreeMatching, a generalizable framework combining generative and semantic foundation representations with heterogeneous supervision from classical datasets, tracked videos, and synthetic scenes. Teacher-guided iterative refinement further improves correspondence in IEG without dense correspondence annotations. Experimentally, a single FreeMatching model substantially improves correspondence quality on challenging IEG image pairs while retaining competitive performance on classical benchmarks. Furthermore, we demonstrate its utility as a quantitative metric for evaluating identity preservation, with scores that correlate with human judgment. The code is available at https://github.com/luping-liu/FreeMatching.","authors":["Luping Liu","Bingyi Kang","Yifan Wang","Dong Xu"],"published":"2026-10-08T17:53:04Z","updated":"2026-10-08T17:53:04Z","abstract_url":"https://arxiv.org/abs/2610.12421v1","html_url":"https://arxiv.org/html/2610.12421v1","pdf_url":"https://arxiv.org/pdf/2610.12421v1.pdf","matched_keywords":["video","representation"],"source_used":"html","source_text_chars":80464,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, representation 相关；摘要显示其主要贡献为：Dense correspondence matching has historically been bounded by simplifying spatio-temporal priors, such as smooth motion and rigid geometry. While effective for classical tasks, these assumptions break down in image editing and reference-guided generation (IE...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12419v1","title":"OneSearch-VL: Unified Multimodal Deep Research Agent for Image and Video","abstract":"Single-image, multi-image, and video deep research require different visual operations but share a workflow of visual grounding, external retrieval, and fact composition. A key challenge is to preserve the dependencies linking localized visual anchors, entity relations, source-supported facts, and answer-producing operations. We introduce OneSearch-VL, a unified agent centered on the Visually Grounded Evidence Graph (VGEG), which encodes these dependencies as a shared task-level reference for data construction, process supervision, and operation-level evaluation. Our VGEG-based data engine constructs and verifies multi-image and video questions and filters expert trajectories. Using these data, we assemble OneSearch-VL-SFT-110K and OneSearch-VL-RL-10K for SFT and RL, respectively. We further derive the Evidence-aware Visual-Grounded Rubric reward (EVGR) from VGEG annotations to supervise evidence traceability and visual grounding during RL. For fine-grained evaluation, we construct OneSearch-MI-Bench and OneSearch-Video-Bench, organizing questions by the research operations encoded in their VGEGs. Experiments show that OneSearch-VL-8B improves over Qwen3-VL-8B with tool access by 20.2 and 17.6 percentage points on the two new benchmarks, respectively, while also achieving substantial gains across 7 image benchmarks and VideoDR. Project repository: https://github.com/appletea233/OneSearch-VL","authors":["Hongyu Li","Manyuan Zhang","Kaituo Feng","Shu Chen","Dian Zheng","Hao Li","Hao Yu","Zhangquan Chen","Zoey Guo","Ray Zhang","Shaofei Huang","Tianrui Hui","Linjiang Huang","Si Liu"],"published":"2026-10-08T17:52:46Z","updated":"2026-10-08T17:52:46Z","abstract_url":"https://arxiv.org/abs/2610.12419v1","html_url":"https://arxiv.org/html/2610.12419v1","pdf_url":"https://arxiv.org/pdf/2610.12419v1.pdf","matched_keywords":["video","retrieval","agent","multimodal"],"source_used":"html","source_text_chars":94953,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, retrieval, agent, multimodal 相关；摘要显示其主要贡献为：Single-image, multi-image, and video deep research require different visual operations but share a workflow of visual grounding, external retrieval, and fact composition. A key challenge is to preserve the dependencies linking localized visual anchors, entity...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12417v1","title":"WOVEN: Weaving Visual World Modeling into Multimodal LLMs","abstract":"Multimodal large language models (MLLMs) struggle with spatial, embodied, physical, and temporal reasoning. We hypothesize that these failures reflect a shared deficit in visual transition reasoning, and test whether this capability can serve as a shared training primitive, one that different models can learn from different supervision sources and reuse across different tasks, with a systematic training recipe. Existing benchmarks document these deficits separately but do not support controlled comparisons across scenes, actions, and reasoning operations. We therefore introduce WOVEN, a training source and benchmark for visual transition reasoning that organizes transition supervision by scene, action, and reasoning type, using diverse, realistic rollouts from video-pretrained generative models: 36,076 examples across 20 scene types, 5 action types, and 8 reasoning types. We first evaluate 38 frontier MLLMs (e.g., GPT-5.4 and Qwen3-VL-235B-A22B) and find a substantial and systematic deficit: even the strongest models fall far below humans, and the failures recur across model families and persist with scale. We then train MLLMs at multiple scales on WOVEN and find that they learn a shared capability that transfers broadly: training subsets of only about 2,000 items each collectively improve 22 of 26 external benchmarks by up to 27.3 percentage points, and WOVEN data can replace 30-50% of a task's own training data with comparable accuracy. Controlled comparisons further yield a training recipe for visual world modeling, validated prospectively on held-out benchmarks: select supervision by the reasoning operation it teaches rather than by the actions, scenes, or domains it shows, and prefer larger changes to the visual state for robustness. Our work establishes visual transition reasoning as a reusable foundation for systematic visual world-model training in MLLMs.","authors":["Zheyu Fan","Yue Zhang","Mingkai Deng","Kangrui Wang","Qineng Wang","Canyu Chen","Jie Hao","Xing Fan","Chenlei Guo","Eric P. Xing","Mohit Bansal","Manling Li"],"published":"2026-10-08T17:52:03Z","updated":"2026-10-08T17:52:03Z","abstract_url":"https://arxiv.org/abs/2610.12417v1","html_url":"https://arxiv.org/html/2610.12417v1","pdf_url":"https://arxiv.org/pdf/2610.12417v1.pdf","matched_keywords":["video","multimodal"],"source_used":"html","source_text_chars":322988,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, multimodal 相关；摘要显示其主要贡献为：Multimodal large language models (MLLMs) struggle with spatial, embodied, physical, and temporal reasoning. We hypothesize that these failures reflect a shared deficit in visual transition reasoning, and test whether this capability can serve as a shared trai...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12416v1","title":"MAMHOI: Factorizing Scene-Aware Human-Object Interaction through Affordances","abstract":"Generating realistic human-object interactions (HOI) in complex 3D scenes requires two complementary capabilities: reasoning about interaction feasibility in the environment and synthesizing realistic human-object motion. However, supervision for these capabilities is rarely available jointly at scale. Human-scene datasets provide rich information about environment-aware motion, while human-object datasets capture detailed interaction dynamics, yet paired human-object-scene data remain scarce. We present MAMHOI, an affordance-mediated factorization for scene-aware human-object interaction generation. MAMHOI factorizes scene-aware HOI generation through an explicit motion-affordance interface between scene understanding and motion synthesis: a scene-conditioned model first predicts where and how an interaction can be feasibly executed, and an affordance-conditioned HOI model then generates the corresponding human-object motion. This factorization allows scene understanding and interaction dynamics to be learned from complementary sources of supervision without requiring paired human-object-scene data. Experiments in complex indoor environments show that MAMHOI reduces object--scene penetration while better preserving human--object interaction quality, yielding more realistic and physically feasible scene-aware interactions. Project page: https://leimingyuan.github.io/MAMHOI-project-page/","authors":["Mingyuan Lei","Yoonchang Sung","Tat-Jen Cham"],"published":"2026-10-08T17:52:02Z","updated":"2026-10-08T17:52:02Z","abstract_url":"https://arxiv.org/abs/2610.12416v1","html_url":"https://arxiv.org/html/2610.12416v1","pdf_url":"https://arxiv.org/pdf/2610.12416v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":85427,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Generating realistic human-object interactions (HOI) in complex 3D scenes requires two complementary capabilities: reasoning about interaction feasibility in the environment and synthesizing realistic human-object motion. However, supervision for these capabi...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12412v1","title":"WorldCast: Distributed Multiplayer World Models","abstract":"Multiplayer world models must generate independently controlled views with consistent representations of both players and their shared environment. Most existing approaches coordinate multiple players through joint multi-view generation, whose cost grows with each additional player. We present WorldCast, a distributed multiplayer world model in which each player runs a local client comprising a video generator and a state model. Using recorded player positions and map geometry during training, the state model estimates the player's position from generated video and control inputs. Clients exchange player states and project them into camera-aligned player state fields that guide where and how other players are rendered. Shared scene state enables clients to reuse one another's generated observations to maintain consistent scene appearance across views. Experiments on Counter-Strike 2 demonstrate WorldCast's consistency, real-time performance, and distributed scalability. The camera-aligned player state field improves player rendering rates by over an order of magnitude over joint-generation methods, while shared scene state improves visual consistency over whole rounds. Each client runs in real time and exchanges only player and scene states, enabling scalable multiplayer generation without a centralized computational bottleneck. Image quality remains stable over hour-long rollouts.","authors":["Ziyang Ye","Junchao Huang","Evelyn Zhang","Zhihao Xie","Ruicheng Zhang","Boyao Han","Litao Ban","Ziye Wang","Xinting Hu","Shaoshuai Shi","Zhuotao Tian","Li Jiang"],"published":"2026-10-08T17:49:44Z","updated":"2026-10-08T17:49:44Z","abstract_url":"https://arxiv.org/abs/2610.12412v1","html_url":"https://arxiv.org/html/2610.12412v1","pdf_url":"https://arxiv.org/pdf/2610.12412v1.pdf","matched_keywords":["video","representation"],"source_used":"html","source_text_chars":110593,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, representation 相关；摘要显示其主要贡献为：Multiplayer world models must generate independently controlled views with consistent representations of both players and their shared environment. Most existing approaches coordinate multiple players through joint multi-view generation, whose cost grows with...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12407v1","title":"LeWAM: A JEPA World Action Model with Diffusion-Steering-Based MPC","abstract":"World action models (WAMs) predict actions and future observations, typically from a reconstruction-based representation that carries noisy, redundant information which can complicate downstream predictions. We introduce LeWAM, a bidirectional transformer for forward, backward, inverse dynamics and policy prediction, on a decoder-free JEPA latent trained end-to-end through all four modes. We see the following benefits: 1) Alignment: linear probes read robot and object state from LeWAM's latent better than from a regular Le World Model (a forward-only JEPA world model), while the latent ignores visual distractors as well as LeWM does and far better than a reconstruction-based WAM. 2) Acting: Closed-loop evaluations of LeWAM match a regular flow-matching policy trained on the same encoder at matched size, while also providing a world model. 3) Planning: Sampling raw actions when planning with WAMs lets MPC exploit dynamics-model inaccuracies; planning in the noise space of the policy head instead improves the closed-loop performance of these WAMs.","authors":["Shashank Hegde","Alexander Popov","Elie Aljalbout","Nikolai Smolyanskiy"],"published":"2026-10-08T17:46:03Z","updated":"2026-10-08T17:46:03Z","abstract_url":"https://arxiv.org/abs/2610.12407v1","html_url":"https://arxiv.org/html/2610.12407v1","pdf_url":"https://arxiv.org/pdf/2610.12407v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"html","source_text_chars":46700,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, diffusion 相关；摘要显示其主要贡献为：World action models (WAMs) predict actions and future observations, typically from a reconstruction-based representation that carries noisy, redundant information which can complicate downstream predictions. We introduce LeWAM, a bidirectional transformer for...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:15+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12403v1","title":"ViSkill: Reinforcing VLM Agents with Evolving Visual-Native Skills","abstract":"Skill-augmented agents improve sample efficiency by distilling successful trajectories into reusable strategies. Yet most existing approaches remain text-centric, linearizing spatial layouts and action-state correspondences into language that loses critical geometric structure. Recent efforts have begun incorporating visual evidence, but construct and update skills separately from policy optimization, leaving their mutual improvement underexplored. We propose ViSkill, a visual-native skill learning framework that encodes successful interactions as composite visual skill cards directly accessible to VLM agents. Retrieved skills guide both inference and reward shaping, while successful trajectories are distilled back into the library, forming a closed feedback loop in which skill accumulation and policy improvement reinforce each other. An optional cold-start mechanism further accelerates early-stage learning. Evaluated on Sokoban, FrozenLake, and PrimitiveSkill, ViSkill achieves an overall success rate of 0.89, rising to 0.91 with cold-start initialization, outperforming all evaluated proprietary and open-source baselines while converging faster than standard PPO. Our code is available at https://github.com/ZJU-REAL/ViSkill.","authors":["Hongxing Li","Dingming Li","Yixin Li","Yong Du","Wenqi Zhang","Weiming Lu","Jun Xiao","Yueting Zhuang","Yongliang Shen"],"published":"2026-10-08T17:44:19Z","updated":"2026-10-08T17:44:19Z","abstract_url":"https://arxiv.org/abs/2610.12403v1","html_url":"https://arxiv.org/html/2610.12403v1","pdf_url":"https://arxiv.org/pdf/2610.12403v1.pdf","matched_keywords":["agent"],"source_used":"html","source_text_chars":75081,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent 相关；摘要显示其主要贡献为：Skill-augmented agents improve sample efficiency by distilling successful trajectories into reusable strategies. Yet most existing approaches remain text-centric, linearizing spatial layouts and action-state correspondences into language that loses critical g...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:15+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12402v1","title":"SpaceCast-Bench: Evaluating Predictive Spatial Reasoning in Vision-Language Models","abstract":"Existing spatial reasoning benchmarks mainly test spatial perception: reading off relations already visible in the input. Yet real-world spatial intelligence demands predictive spatial reasoning: constructing a scene from observations, anticipating how an intervention changes it, and reasoning about the unseen outcome. We introduce SpaceCast-Bench, the first benchmark to directly and diagnostically evaluate this capability. Built around an observe-transform-infer framework, its 3,862 questions from 182 real-world scenes span 16 task types at three levels: static perception, local prediction, and global prediction, progressively requiring scene understanding, spatial state updating, and relational inference over unobserved outcomes. Evaluating 21 models exposes a stark gap: the strongest model reaches only 58.0% against 87.2% human performance, while spatially specialized models remain near random chance. Controlled analyses further reveal that bridge views are critical for integrating distributed observations, and that explicit 3D evidence benefits models more reliably than generated outcome images or videos. Fine-tuning on our programmatically generated data lifts Qwen3-VL-4B from 34.0% to 65.7% with macro-average gains across six out-of-domain benchmarks.","authors":["Hongxing Li","Jinyue Su","Dingming Li","Wenqi Zhang","Weiming Lu","Jun Xiao","Yueting Zhuang","Yongliang Shen"],"published":"2026-10-08T17:44:17Z","updated":"2026-10-08T17:44:17Z","abstract_url":"https://arxiv.org/abs/2610.12402v1","html_url":"https://arxiv.org/html/2610.12402v1","pdf_url":"https://arxiv.org/pdf/2610.12402v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12399v1","title":"SpaceFlow: Locally Controllable 3D Generation","abstract":"Current 3D generation methods lack explicit local control: geometric adherence is often defined by a global control strength, and appearance cannot be specified locally. We present SpaceFlow, a training-free pipeline for locally controllable 3D generation from text descriptions and a collection of geometric primitives. Each primitive serves as a proxy for an object part and is assigned a local control level, enabling users to specify whether regions should strictly follow the input shape or allow generative completion. During structure generation, we enforce these spatial constraints within the generative flow process. For appearance synthesis, the generated structure is segmented and matched to the primitives. Each generated part is conditioned only on its assigned text or image cue, thereby limiting cross-part leakage. Regional geometry metrics demonstrate that SpaceFlow preserves the specified geometry in high-control regions and enables plausible shape variation in low-control areas. A user study further indicates that the resulting balance between geometric fidelity and generative freedom remains competitive in overall quality. When evaluating appearance on fixed geometry, text-conditioned routing achieves state-of-the-art prompt faithfulness and color/material accuracy. Qualitative results additionally show localized routing of image cues. The project page is available at SpaceFlow3D.github.io.","authors":["Neil De La Fuente","Joan Lafuente","Mukhammadali Sayfiddinov","Felicia Scharitzer","Marc Pollefeys","Ata Celen","Sayan Deb Sarkar","Elisabetta Fedele"],"published":"2026-10-08T17:42:39Z","updated":"2026-10-08T17:42:39Z","abstract_url":"https://arxiv.org/abs/2610.12399v1","html_url":"https://arxiv.org/html/2610.12399v1","pdf_url":"https://arxiv.org/pdf/2610.12399v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12388v1","title":"GenIA: Generative Reconstruction with Test-Time Input Alignment","abstract":"Reconstructing complete 3D object assets from monocular or sparse multi-view observations remains challenging. Generative 3D foundation models can complete object geometry beyond the observed views, but their predictions may not faithfully reproduce the observed geometry, appearance, or pose. We introduce GenIA, a framework for test-time input-aligned generation that grounds SAM3D's generative prior in geometric and photometric observations without retraining the foundation model. We improve object pose by deriving translation and scale from geometry while retaining the learned rotation prior, and align appearance through visibility-biased attention, cross-observation fusion, and differentiable rendering guidance during denoising. An optional post-denoising refinement further adapts the appearance latent, lightweight decoder adapters, and object placement to the observations. Our framework also supports externally supplied geometry; when given temporal shapes of dynamic objects, it recovers a shared, input-aligned canonical appearance and stable world-space placement. Across synthetic and real benchmarks, GenIA improves pose prediction and object reconstruction from monocular, multi-view, and dynamic inputs, outperforming recent optimization-based, per-frame image-to-3D, and video-to-4D methods. Our project page is available at https://facebookresearch.github.io/GenIA.","authors":["Stefano Esposito","Naama Pearl","Polina Karpikova","Samuel Rota Bulò","Lorenzo Porzi","Peter Kontschieder","Andreas Geiger","Jonathon Luiten"],"published":"2026-10-08T17:38:56Z","updated":"2026-10-08T17:38:56Z","abstract_url":"https://arxiv.org/abs/2610.12388v1","html_url":"https://arxiv.org/html/2610.12388v1","pdf_url":"https://arxiv.org/pdf/2610.12388v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12382v1","title":"WorldAlign: Decoupled 4D Reward for World-Consistent Video Generation","abstract":"Faithful visual world simulation requires generated videos to maintain 4D world consistency, encompassing both static and dynamic consistency. Static consistency requires coherent 3D structure in static environments across viewpoints, while dynamic consistency requires plausible subject motion and consistent appearance over time. Geometry-aware post-training offers a promising way to improve world consistency. However, existing methods often rely on a static-scene assumption. Even those that accommodate dynamic scenes struggle to provide reliable static-consistency feedback, while dynamic consistency is often overlooked or inadequately assessed. To address these limitations, we introduce WorldAlign, a decoupled 4D reward framework that semantically separates static regions and dynamic subjects and provides feedback by aligning each with a world prior suited to its assumptions. For static regions, WorldAlign aligns static geometry with a geometric world prior through semantically guided masked reprojection, enabling more reliable static-consistency evaluation; an auxiliary camera-motion reward discourages nearly static solutions. For dynamic subjects, WorldAlign uses a strong vision-language model (VLM) as a dynamic world prior and constructs a VLM-as-a-judge reward based on sample-specific checklists that assess dynamicity, physical plausibility, shape, and texture consistency. This decoupled design enables more effective online post-training without requiring human preference annotations. Across two pretrained image-to-video generators, Wan2.1 and Wan2.2, WorldAlign jointly improves static and dynamic consistency over existing methods without suppressing overall or subject motion. These results support decoupled world-prior alignment for more faithful visual world simulation. Project page: https://worldalign.github.io/.","authors":["Jing He","Kaixin Ding","Xingye Tian","Guibao Shen","Wenhang Ge","Xin Tao","Pengfei Wan","Ying-Cong Chen"],"published":"2026-10-08T17:35:19Z","updated":"2026-10-08T17:35:19Z","abstract_url":"https://arxiv.org/abs/2610.12382v1","html_url":"https://arxiv.org/html/2610.12382v1","pdf_url":"https://arxiv.org/pdf/2610.12382v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12374v1","title":"AgentGarten: Code Worlds for Evolving Agents","abstract":"Interactive virtual worlds allow agents to learn through exploration and interaction. What agents can learn is bounded by the environments they practice in, which must be faithful, with consistent state, rules, and dynamics, and realistic, with observations that follow the real-world visual distributions. Achieving both across diverse worlds remains a bottleneck. We introduce AgentGarten, a framework that couples simulators and game engines with a shared neural renderer to build real-time interactive environments. Its simulation backends maintain persistent world state and execute program-defined interaction rules, while the renderer generates visual observations from structured conditions exported through a common interface. To build the neural renderer, we adapt a pretrained video model to geometry conditions, distill it with our proposed Adversarial Forcing, and optimize inference for real-time interaction. Adversarial Forcing makes history prefilling differentiable through exact replay, so that losses on later predictions update how the renderer encodes prior observations, and adds real-data adversarial supervision to improve its visual quality. In AgentGarten, agents perceive the world through visual observations, interact with it in real time, and improve by distilling each round of experience into playbooks that subsequent agents inherit and refine. Our empirical study demonstrates a substantial gain in learning efficiency, with agents learning from just 4 rounds compared with millions for a conventional reinforcement learning counterpart. As new worlds can be written as code and rendered through the same interface, environments can scale in both number and difficulty alongside their agents, a step toward agents that keep evolving through interactive experience.","authors":["Jiawei Chi","Shangchen Miao","Zhiyuan Shi","Kailu Wu","Hanyang Wang","Weiliang Chen","Qiyu Dai","Jinshan Ren","Jun Gao","Mingsheng Long","Yueqi Duan","Jiangran Lyu","Jialong Wu","Fangfu Liu"],"published":"2026-10-08T17:32:00Z","updated":"2026-10-08T17:32:00Z","abstract_url":"https://arxiv.org/abs/2610.12374v1","html_url":"https://arxiv.org/html/2610.12374v1","pdf_url":"https://arxiv.org/pdf/2610.12374v1.pdf","matched_keywords":["video","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12369v1","title":"Embodied Turing Machines: Stateful Code for Robot Recursive Self-Improvement","abstract":"Most robot policies keep a model in the control loop: a VLA maps observations to actions, and an Agent Harness, such as Agent-as-Policy or Harness VLA queries a VLM for decision making at run time. We propose a different view: the embodied world is an Embodied Turing Machine, whose tape is the robot and environment state and rules are the policy. If this state can be represented accurately, the decision making can be written entirely in code. We therefore propose Code-Only-as-Policy (COAP): code measures and tracks the robot, environment, and task state from camera images and proprioception, and makes every decision from it. The same code applies across episodes, and different tasks share one library without a VLM or VLA in the loop. Compared with VLAs and Agent Harnesses, we analyze three advantages of COAP: (i) Explicit State: the state can be stored in code; (ii) Execution: code makes decision making controllable, recovers from failures flexibly, and runs fast and cheaply online; (iii) Extensibility: new tasks reuse, inherit, or extend the shared library, so capabilities can accumulate over tasks. These advantages make COAP a suitable medium for recursive self-improvement (RSI): coding agents develop the library in a closed loop, and each change is explicit and controllable. On RoboDojo's 42 bimanual tasks, the resulting library reaches a success rate of 70.24% without a model at test time. The upper bound of COAP lies in how accurately the state is represented for decision making and how robust the code logic is. We thus propose COAP as a new paradigm for embodied tasks; since it applies across episodes, it can also serve as an efficient data engine for VLAs and Agent Harnesses.","authors":["Kairui Hu","Siyuan Hu","Fangzhou Hong","Zhaoxi Chen","Ziwei Liu"],"published":"2026-10-08T17:29:08Z","updated":"2026-10-08T17:29:08Z","abstract_url":"https://arxiv.org/abs/2610.12369v1","html_url":"https://arxiv.org/html/2610.12369v1","pdf_url":"https://arxiv.org/pdf/2610.12369v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12355v1","title":"Distilling Routed 3D Privilege for Spatial Reasoning in Vision-Language Models","abstract":"Spatial reasoning remains a persistent weakness of vision-language models (VLMs), because RGB inputs do not directly provide geometric evidence. Existing remedies either inject 3D into the model at inference, paying architecture and latency costs, or train with outcome rewards that supervise only the final answer. Spatial errors originate in perception: a misjudged depth or direction can be corrected only by the scene's true geometry, which the 3D-scanned sources of spatial training corpora already provide. We propose GPD (Geometry-Privileged Distillation), which makes geometric evidence the privilege in on-policy self-distillation (OPSD). For each question, depth, semantic, and bird's-eye-view (BEV) cues are rendered as compact text and routed to the teacher alongside the reference answer; a privileged KL, applied only to incorrect trajectories, augments GRPO, and the deployed model remains RGB-only. On the 4B backbone, GPD achieves 57.1 on VSI-Bench and 37.6 average across MindCube, SPARBench, MMSI-Bench, and ViewSpatial, outperforming both GRPO and answer-privileged OPSD across spatial reasoning benchmarks. Ablations confirm the complementarity of 3D and answer privilege, the advantage of question-conditioned routing over full-context injection, and the benefit of restricting distillation to incorrect trajectories.","authors":["Hongxing Li","Yixin Li","Dingming Li","Zixuan Wang","Yuchen Yan","Wenqi Zhang","Weiming Lu","Yongliang Shen"],"published":"2026-10-08T17:22:24Z","updated":"2026-10-08T17:22:24Z","abstract_url":"https://arxiv.org/abs/2610.12355v1","html_url":"https://arxiv.org/html/2610.12355v1","pdf_url":"https://arxiv.org/pdf/2610.12355v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12343v1","title":"Reasoning-Informed Visual Editing","abstract":"Large Multi-modality Models (LMMs) have made significant progress in visual understanding and generation, but still face challenges in visual editing, particularly in following complex instructions, preserving appearance consistency, and supporting flexible input formats. To study this gap, we introduce RISEBench, the first benchmark for evaluating Reasoning-Informed viSual Editing (RISE), and extend it to RISEBench++, a more comprehensive and fine-grained benchmark for this emerging task. RISEBench++ extends the taxonomy into a hierarchical scheme spanning six reasoning dimensions: Temporal, Causal, Spatial, Logical, and Counterfactual Reasoning, together with Hybrid Reasoning integrating multiple reasoning types across multi-turn edits. These dimensions are further decomposed into 12 subcategories and 65 fine-grained task types. We expand input formats to include multi-image conditioning and scale the benchmark to 1000 human-annotated test cases, released in English and Chinese. We also improve our evaluation framework, assessing Instruction Reasoning, Appearance Consistency, and Visual Plausibility with human judges and an LMM-as-a-judge approach for more reliable and calibrated judgements. Beyond benchmarking, we introduce RISE-Agent, a training-free agentic framework integrating reasoning-driven planning, tool-augmented execution, and verifier-guided refinement, outperforming most strong existing approaches across diverse RISE tasks. We evaluate 58 visual editing approaches, including 34 open-source models, 19 closed-source models, and 5 agentic methods. The results reveal substantial challenges in reasoning-based visual editing, with even the strongest evaluated approach, GPT-Image-2.5 Sunburst, achieving only 56.6% accuracy. RISEBench++ highlights the limitations of contemporary editing models, provides insights, and indicates future directions for reasoning-aware visual editing.","authors":["Xue Yang","Peiyuan Zhang","Yilun Zhu","Qihao Yang","Mingxin Liu","Xiangyu Zhao","Ziqian Fan","Zhaokai Wang","Yan Li","Yifan Yang","Xu Yang","Xiaosong Jia","Yue Zhou","Zhihang Zhong","Junchi Yan"],"published":"2026-10-08T17:15:58Z","updated":"2026-10-08T17:15:58Z","abstract_url":"https://arxiv.org/abs/2610.12343v1","html_url":"https://arxiv.org/html/2610.12343v1","pdf_url":"https://arxiv.org/pdf/2610.12343v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12316v1","title":"Controllable Exaggeration for Generative Motion Models via Training-Time Adaptation and Inference-Time Guidance","abstract":"Recent motion generative models have demonstrated strong capabilities in synthesizing physically plausible character motion, but often overlook established animation principles used by professional animators to ground and design their animation work. Understanding and incorporating these principles into motion generative pipelines is essential for producing motions that serve not only physically grounded applications but also the needs of the character animation community. This enables the creation of characters that not only move in physically plausible ways but also feel alive, expressive, and engaging. To close this gap, we focus on the Exaggeration principle of animation and investigate how it can be incorporated into modern motion generative pipelines to produce more expressive character motions. To this end, we introduce a framework that operates at two stages of existing motion generative pipelines. The first stage introduces exaggeration during training, where we perform supervised fine-tuning of pre-trained text-to-motion models on our curated exaggeration dataset. The second stage operates at inference time, where we: (i) introduce a mathematical formulation of exaggeration based on dynamic movement primitives (DMPs); and (ii) leverage this formulation as an exaggeration guidance signal to guide existing diffusion and flow-matching text-to-motion generation models toward exaggerated motion without additional training. Through qualitative and quantitative evaluations against three strong motion generation models, we show that our methods generate more exaggerated and expressive motions while preserving neutral reference motion intent and physical plausibility.","authors":["Amirhossein Zamani","Arianna Rampini","Bruno Roy"],"published":"2026-10-08T17:00:57Z","updated":"2026-10-08T17:00:57Z","abstract_url":"https://arxiv.org/abs/2610.12316v1","html_url":"https://arxiv.org/html/2610.12316v1","pdf_url":"https://arxiv.org/pdf/2610.12316v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12310v1","title":"Is In-Domain Training Enough for Fine-Grained Industrial Anomaly Understanding?","abstract":"A single multimodal large language model (MLLM) struggles to excel simultaneously at detection, localization, description, and reasoning in multimodal industrial anomaly understanding (MM-IAU). We show that in-domain training does not close this gap. On MMAD, a widely adopted MM-IAU benchmark, trained specialists reach at most 75.5% accuracy in defect localization, against 92.3% for human experts, and even detect anomalies less accurately than their untrained base model. Meanwhile, different MLLMs offer complementary strengths but share this weakness in fine-grained perception, so combining them alone cannot remove it. We therefore propose SiGMA, a spatially grounded multi-agent framework that divides labor between heterogeneous MLLM agents and a dedicated visual defect expert. A multimodal searcher supplies industrial knowledge and normal references, the defect expert turns query-reference comparison into calibrated anomaly evidence, and a label-free reliability controller weighs each source by task-wise competence and query-level evidence quality. SiGMA reaches 85.2% average accuracy on MMAD, 4.0% above the strongest trained specialist and Gemini-2.5-Pro and within 1.5% of human experts. Even with three agents of at most 9B parameters, it reaches 84.4%, and new MLLMs join without retraining.","authors":["Xingwu Zhang","Duanyang Du","Huiling Zhu","Jiayue Dai","Yixiao Liu","Guozhi Liu","Zhihan Zhang","Zijun Long"],"published":"2026-10-08T16:59:29Z","updated":"2026-10-08T16:59:29Z","abstract_url":"https://arxiv.org/abs/2610.12310v1","html_url":"https://arxiv.org/html/2610.12310v1","pdf_url":"https://arxiv.org/pdf/2610.12310v1.pdf","matched_keywords":["agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12307v1","title":"BudgetPix: Compute-Adaptive Tokenization for Pixel-Space Image Diffusion","abstract":"Most image generation models rely on uniform tokenization, allocating the exact same computational budget to equally-sized image patches. This static paradigm cannot adapt to different resource constraints at inference time, and yields suboptimal quality-cost tradeoff by devoting the same effort to both plain backgrounds and intricate details. We propose BudgetPix, an adaptive tokenization framework that dynamically allocates compute based on visual complexity and spatial layout, enabling flexible computational budgeting at inference time. BudgetPix comprises three key components: (1) an adaptive encoder that maps a fixed-size image to a variable-length token sequence using an entropy-guided quadtree alongside a multi-scale patch embedder; (2) a scale-aware decoder reconstructs fixed-resolution images from multi-scale token sets; and (3) a flexible training and sampling schedule that enables pixel-space denoisers to operate across variable token counts. BudgetPix seamlessly integrates with existing pixel-space diffusion architectures, enabling a single checkpoint to be operated at a wide range of compute budgets. Evaluated on text-to-image generation, BudgetPix matches the fidelity of MiniT2I-L at $512^2$ and PixelDiT at $1024^2$ using just 25% of the original compute budget. In class-conditional generation using a MeanFlow backbone, BudgetPix requires merely 60% of the full compute budget to produce images with near-zero quality degradation, observing a marginal 0.8-point increase in FID. Comprehensive assessments by human and VLM judges confirm that BudgetPix establishes a significantly improved quality-efficiency tradeoff over prior budget-adaptive baselines. More details are available at our project page: https://karaozgur.com/BudgetPix","authors":["Ozgur Kara","Yujia Chen","Daniel Watson","David Forsyth","James Matthew Rehg","Wen-Sheng Chu","Du Tran"],"published":"2026-10-08T16:54:40Z","updated":"2026-10-08T16:54:40Z","abstract_url":"https://arxiv.org/abs/2610.12307v1","html_url":"https://arxiv.org/html/2610.12307v1","pdf_url":"https://arxiv.org/pdf/2610.12307v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12305v1","title":"From What to Which: Decoding Modifier Grounding in Frozen MLLMs","abstract":"As Multimodal Large Language Models (MLLMs) can describe increasingly complex visual scenes, token-level grounding becomes crucial. Yet, when an MLLM generates \"the yellow banana on the left\", established grounding approaches focus on what is in the image (\"banana\"), overlooking tokens that help describe which instance is meant (\"yellow\", \"left\"). In this work, we ask whether frozen MLLM representations contain decodable grounding information about the referred instance across generated tokens, extending to modifiers such as attributes, spatial expressions, and relational/action terms. To address this question, we introduce OTTER, a lightweight supervised probe over frozen MLLM representations that uses Optimal Transport (OT) to align generated tokens with visual regions and produce compact grounding maps. Our results show that (i) instance-discriminative visual information can be decoded from modifier tokens, with the clearest evidence for spatial terms, but (ii) is not confined to them, as contextualized object nouns also carry referential information; (iii) the recovered grounding remains informative under context perturbations, while selected regions remain relevant to generation; and (iv) the learned OT-based grounding extends beyond the controlled setting to free generation and cross-dataset transfer.","authors":["Barbara Toniella Corradini","Caterina Gallegati","Ludovica Genovese","Vittorio Murino"],"published":"2026-10-08T16:53:59Z","updated":"2026-10-08T16:53:59Z","abstract_url":"https://arxiv.org/abs/2610.12305v1","html_url":"https://arxiv.org/html/2610.12305v1","pdf_url":"https://arxiv.org/pdf/2610.12305v1.pdf","matched_keywords":["representation","instance","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12299v1","title":"Multi-Agent Egocentric World Model with Fine-Grained Embodied Interaction","abstract":"Egocentric world models predict first-person observations conditioned on an agent's actions, but most focus on a single agent. Real embodied settings often involve multiple agents that act and interact within a shared environment. Existing multi-agent world models rely on coarse actions like locomotion, camera control, or discrete commands, leaving fine-grained embodied interactions underexplored. We formulate multi-agent egocentric world modeling as synchronized ego-stream generation for multiple agents interacting through fine-grained actions in a shared world. This requires cross-view action consistency, shared-environment consistency, and consistent propagation of interaction-induced state updates. We propose Multi-agent Egocentric World Model (ME-World), which jointly denoises multiple ego streams in a shared token sequence, conditions each stream on all agents' target-view poses, and grounds generation with shared environment memory. We train and evaluate on real and synthetic multi-agent data and introduce shared-world consistency metrics for environment, update, and identity consistency. Experiments show ME-World improves shared-world consistency, action control, identity preservation, and video quality over existing methods.","authors":["Dahyun Chung","Siyoon Jin","Hyunwook Choi","Honggyu An","Junyoung Seo","Hyunsung Kim","Seung Wook Kim","Seungryong Kim"],"published":"2026-10-08T16:50:04Z","updated":"2026-10-08T16:50:04Z","abstract_url":"https://arxiv.org/abs/2610.12299v1","html_url":"https://arxiv.org/html/2610.12299v1","pdf_url":"https://arxiv.org/pdf/2610.12299v1.pdf","matched_keywords":["video","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12282v1","title":"Slot3R: Set-Associative Spatial Memory for Streaming 3D Reconstruction","abstract":"Streaming 3D reconstruction must preserve evidence from each frame while processing an expanding scene online. Spatial memory is a natural fit because it organizes history by reconstructed 3D location. Yet Point3R uses spatial proximity both to associate a new observation with an existing memory entry and to decide whether to fuse it, conflating co-location with state identity. Because pointers summarize image patches, nearby pointers may encode distinct surfaces, viewpoints, or visibility conditions; averaging them can destroy complementary evidence before later frames disambiguate it. We argue that location should determine address, not whether observations must merge. Slot3R realizes this principle as a training-free, set-associative retrofit that lets multiple states coexist at a shared address while keeping the pretrained Point3R backbone frozen. A bounded sparse readout further decouples persistent storage from per-frame decoder access. At 300-500 sampled frames, Slot3R reduces Point3R's point-cloud accuracy error (Acc) by 57.1%-63.1% on 7Scenes and 64.0%-72.0% on NeuralRGBD, lowers Sim(3)-aligned absolute trajectory error (ATE) on all three pose benchmarks, and remains competitive on video-depth estimation. It completes all evaluated settings from 600 to 1000 sampled frames at about 19 FPS under the same protocol, whereas Point3R and InfiniteVGGT run out of memory at 800 frames and beyond.","authors":["Xiyuan Zhang","Yanming Yang","Kaiyuan Xu","Ruibo Li","Chi Zhang"],"published":"2026-10-08T16:39:39Z","updated":"2026-10-08T16:39:39Z","abstract_url":"https://arxiv.org/abs/2610.12282v1","html_url":"https://arxiv.org/html/2610.12282v1","pdf_url":"https://arxiv.org/pdf/2610.12282v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12266v1","title":"DVD: Dynamic Vector Decoding for Efficient MLLM-based Perception","abstract":"Multimodal large language models have made remarkable progress in bridging vision and language, facilitating various perception tasks essential for human-machine interaction, robotics, and autonomous driving. However, existing MLLM-based perception methods predominantly rely on text-based coordinate representation, which suffers from excessive token overhead, or fixed-range quantization, which suffers from range and precision constraints, especially for 3D domains with unbounded spatial range and high localization accuracy requirements. To address these challenges, we propose a dynamic vector decoding method named DVD, which unifies the representation of 2D and 3D perception tasks. Specifically, we first transform diverse perceptual representation (i.e., 2D bounding boxes, 2D masks, and 3D bounding boxes) into 1D vector sequences, which are then mapped to compact discrete tokens in the high-dimensional space. Then, a lightweight de-tokenizer enables seamless integration with MLLMs by decoding output tokens back to original 2D and 3D perceptual representations. Extensive experiments on 2D and 3D perception benchmarks including RefCOCO series, SUN-RGBD, KITTI, Hypersim, nuScenes demonstrate that DVD achieves superior performance in 2D and 3D tasks and reduces significantly the token overhead and inference latency. DVD provides an efficient and general framework for integrating perception capabilities into MLLMs, overcoming the inherent limitations of existing methods.","authors":["Jinghua Hou","Zhe Liu","Hengshuang Zhao"],"published":"2026-10-08T16:32:28Z","updated":"2026-10-08T16:32:28Z","abstract_url":"https://arxiv.org/abs/2610.12266v1","html_url":"https://arxiv.org/html/2610.12266v1","pdf_url":"https://arxiv.org/pdf/2610.12266v1.pdf","matched_keywords":["3d","representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12256v1","title":"Syn-Omni: Structured Specialization and Progressive Collaboration for Omnimodal Embeddings","abstract":"Omnimodal embeddings naturally involve both shared representations and modality-specific features across heterogeneous inputs. However, existing omnimodal embedding methods often rely on a single shared parameter space over mixed-modality data, limiting structural separation between universal and modality-specific representations. To address this, we propose Syn-Omni, a unified framework for structured omnimodal adaptation with modality specialization and controlled cross-modal collaboration. Specifically, we introduce Orthogonal Modality-Expert LoRA (OME-LoRA), which decomposes adaptation into a shared LoRA path for universal semantics and modality-expert LoRA paths for modality-aware specialization. Furthermore, Progressive Synergy Routing (PSR) enables experts to first establish modality-specific priors, then gradually interact with other modality-experts for cross-modal synergy. Evaluated across 81 diverse tasks spanning image, video, audio, and audiovisual modalities, Syn-Omni consistently outperforms omnimodal baselines, demonstrating the effectiveness of structured specialization and cross-modal progressive collaboration.","authors":["Youngtaek Oh","Qiyu Wu","Hiromi Wakaki","Junmo Kim","Yuki Mitsufuji"],"published":"2026-10-08T16:26:03Z","updated":"2026-10-08T16:26:03Z","abstract_url":"https://arxiv.org/abs/2610.12256v1","html_url":"https://arxiv.org/html/2610.12256v1","pdf_url":"https://arxiv.org/pdf/2610.12256v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12248v1","title":"EgoVoice: Proactive Spoken Assistance from Egocentric Multimodal Streams","abstract":"Wearable augmented reality (AR) assistants are moving toward continuous real-world interaction, where they perceive the user's activity through first-person video and audio and provide timely spoken guidance without being explicitly asked. While proactive video assistants, spoken dialog systems, and egocentric task understanding have each advanced rapidly, existing systems do not address the joint problem of deciding when to speak and what to say from continuous first-person streams. We introduce EgoVoice, a framework for training and evaluating proactive egocentric spoken assistants. From HoloAssist video recordings of real human instructors, we construct clean audio streams through source separation and speech resynthesis, and convert each video session into a format where the model must decide at each moment whether to remain silent or provide spoken guidance. We fine-tune an omni-modal LLM with our data, and further improve its proactive intervention behavior with direct preference optimization. Experiments across closed and open-source models show that existing systems rarely produce well-timed, meaningful proactive interventions, while EgoVoice yields clear improvements in intervention timing, content relevance, and human preference over the zero-shot backbone.","authors":["Heeseung Kim"],"published":"2026-10-08T16:24:12Z","updated":"2026-10-08T16:24:12Z","abstract_url":"https://arxiv.org/abs/2610.12248v1","html_url":"https://arxiv.org/html/2610.12248v1","pdf_url":"https://arxiv.org/pdf/2610.12248v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12230v1","title":"From Prompting to Composing: A Spatial Canvas Interface for Poster Generation","abstract":"Text prompting is an indirect interface for poster generation, requiring users to encode inherently two-dimensional composition intent into a one-dimensional sequence of words. We introduce a Spatial Canvas Interface that enables users to directly compose generation intent in space through four complementary binding types: semantic, identity, text, and pixel, together with Text Specifications for individual elements and global appearance. Based on this interface, we develop Compo, a poster generation model adapted from a pretrained image editing model to understand Spatial Canvas inputs and Text Specifications. Compo supports both direct inference, where users explicitly construct the canvas, and agentic mode, where a high-level request is automatically translated into a planned Spatial Canvas. To train Compo, we develop a scalable pipeline that automatically constructs supervision data for different binding types and their combinations, enabling efficient adaptation without training a specialized poster generator from scratch. We further introduce a benchmark that evaluates adherence to individual binding types and their joint composition. Experiments show that Compo achieves stronger compositional controllability than both general-purpose image generation models and dedicated poster generation systems while maintaining high visual quality. By decoupling intent specification from visual generation, our work shifts poster generation from prompting toward composing.","authors":["Yitong Wang","Fangyun Wei","Jinjing Zhao","Sirui Zhang","Hongyang Zhang","Dong Chen","Bo Dai","Yan Lu"],"published":"2026-10-08T16:16:06Z","updated":"2026-10-08T16:16:06Z","abstract_url":"https://arxiv.org/abs/2610.12230v1","html_url":"https://arxiv.org/html/2610.12230v1","pdf_url":"https://arxiv.org/pdf/2610.12230v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12189v1","title":"Just Weather Scoring: Efficient End-to-end Nowcasting with Distributional Diffusion","abstract":"Generative diffusion models are well-suited for probabilistic precipitation nowcasting, but existing approaches often rely on separately trained compression or deterministic forecasting components and remain costly at inference due to iterative denoising. We introduce Just Weather Scoring (JWS), a single-stage, end-to-end diffusion model which addresses both issues by forecasting directly in radar space and enabling few-step generation. Radar-space modeling greatly simplifies training and inference and eliminates uncertainty arising from lossy compression. JWS combines Masked Asynchronous Diffusion, a timestep-sampling scheme that preserves clean context while adapting diffusion training to high-dimensional spatio-temporal data, with a simple scoring-rule objective that aligns training with probabilistic forecasting and unlocks few-step generation. On the SEVIR and MeteoNet benchmarks, JWS achieves state-of-the-art probabilistic forecasting performance at reduced training and inference cost. Even our smallest model remains competitive using substantially fewer parameters and more than 17x faster inference.","authors":["Jannik Wiese","Johannes Schusterbauer","Tommaso Martorella","Björn Ommer"],"published":"2026-10-08T15:50:43Z","updated":"2026-10-08T15:50:43Z","abstract_url":"https://arxiv.org/abs/2610.12189v1","html_url":"https://arxiv.org/html/2610.12189v1","pdf_url":"https://arxiv.org/pdf/2610.12189v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12156v1","title":"Connected Self Forcing: Beyond Local Learning in Video Autoregression","abstract":"To stream long videos while maintaining visual quality and temporal consistency, Self Forcing mitigates exposure bias through self-rollout training on self-generated histories with key-value (KV) caching. To keep memory manageable, it detaches historical caches, preserving forward dependencies between chunks but severing the backward gradient paths. We introduce Connected Self Forcing, a training framework that reconnects gradient paths across autoregressive chunks, allowing feedback from later predictions to guide how earlier context is generated. These connections go beyond historical KV-writing: gradients pass through generated latents into the computations that produced them, linking the generation of earlier context to its use in later predictions. To make this connected training memory-efficient, we develop shortcut gradient replay, which recovers cross-chunk gradients without retaining the full rollout computation graph. Integrated with distribution matching distillation, Connected Self Forcing trains historical chunks according to both their direct supervision and their contribution to subsequent generation. Experiments on autoregressive video generation show improvements in long-horizon visual quality and temporal consistency, without changing the inference procedure.","authors":["Dongbin Zhang","Chaoda Zheng","Kangjie Chen","Xiangyu Li","Shijia Chen","Jinhao Deng","Yuqi Zhang","Guangfeng Jiang","Hongbin Lin","Choo Sin Wai","Minqi Wang","Puyi Wang","Jingye Zhang","Yu Zhang","Xianming Liu","Boyang Wang"],"published":"2026-10-08T15:36:56Z","updated":"2026-10-08T15:36:56Z","abstract_url":"https://arxiv.org/abs/2610.12156v1","html_url":"https://arxiv.org/html/2610.12156v1","pdf_url":"https://arxiv.org/pdf/2610.12156v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12147v1","title":"Healthy Counterfactual Generation via Diffusion Inpainting for Mammography Classification","abstract":"False negatives remain a critical limitation of computer-aided diagnosis (CAD) systems for breast cancer screening due to delayed detection and treatment. To address this issue, we propose a counterfactual data augmentation strategy that generates healthy mammograms by \"erasing\" lesions from anomalous images, thereby enriching the training distribution. We train a Denoising Diffusion Probabilistic Model on BI-RADS 1 (healthy) mammograms and use a RePaint-based sampling strategy to inpaint realistic normal tissue within annotated lesion bounding boxes. The resulting healthy counterfactuals replace annotated lesion regions with realistic healthy tissue while preserving patient-specific anatomical structure, as supported by similarity metrics between real and generated images. Image realism was further assessed by radiologists and found to be consistent with the original dataset quality. We evaluate counterfactual augmentation across four representative classifier architectures: a convolutional neural network (ConvNeXt), a vision transformer (ViT), a vision-language model pre-trained on mammogram-report pairs (Mammo-CLIP) and a multi-scale attention-based multiple-instance learning framework (FPN-MIL). Experiments conducted on the VinDr-Mammo dataset show improvements in sensitivity across all architectures, particularly at 80\\% fixed specificity, contributing towards more reliable CAD systems for breast cancer. Code is available at: https://github.com/ines03garcia/diffusion-based-counterfactual-generation.","authors":["Inês Cruchinho Garcia","Mariana Mourão","Francisco Maria Calisto","Carlos Santiago","Jacinto Nascimento"],"published":"2026-10-08T15:31:56Z","updated":"2026-10-08T15:31:56Z","abstract_url":"https://arxiv.org/abs/2610.12147v1","html_url":"https://arxiv.org/html/2610.12147v1","pdf_url":"https://arxiv.org/pdf/2610.12147v1.pdf","matched_keywords":["instance","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12127v1","title":"LVS: Local View Synthesis from Relative Camera Pose by Reusing Previous Views","abstract":"Interactive scene exploration requires frequent view updates, although small camera motions preserve much of the visible content. Conventional 3D Gaussian Splatting nevertheless renders each target view, leaving this image overlap unexploited. Reusing rendered images offers an alternative. Geometric warping alone cannot recover newly exposed content and remains sensitive to depth errors. We propose a per-scene framework that replaces repeated scene rendering for nearby views with relative-pose-guided RGB-D image reuse. Geometric warping uses depth and relative pose to transport source content, while a lightweight multiscale network predicts RGB residuals to correct artifacts and infer missing appearance. Cached source features further reduce repeated computation. On GS-render, residual refinement improves PSNR by 0.72~dB over pure warping; evaluations on captured and rendered scenes demonstrate low query latency. This separation of scene rendering from local view updates supports responsive scene exploration, with potential applications in augmented and virtual reality.","authors":["Qizhou Huo","Xuan Sun","Yongfei Guo","Zhipeng Wang","Yuanhao Gong"],"published":"2026-10-08T15:19:58Z","updated":"2026-10-08T15:19:58Z","abstract_url":"https://arxiv.org/abs/2610.12127v1","html_url":"https://arxiv.org/html/2610.12127v1","pdf_url":"https://arxiv.org/pdf/2610.12127v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12126v1","title":"SuperNav: An Agentic Navigation System for Any Task in Any Scene","abstract":"General-purpose service robots need navigation systems that can handle diverse human requests in unfamiliar environments, combining task generality with scene generality. Some existing methods fine-tune multimodal large language models (MLLMs) to predict navigation actions, making their behavior dependent on the coverage of navigation training data and potentially limiting generalization to new requests and environments. Our key insight is to let the MLLM focus on interpreting requests, understanding scenes, and making decisions while preserving its general-purpose capabilities and delegating motion execution to navigation tools. To realize this idea, we introduce SuperNav, which equips a pretrained MLLM with a specialized agent harness without navigation-specific fine-tuning of the MLLM. Our harness supports these decisions with Navigation Skills, agent-oriented Tools for physical interaction, and task-progress and context management. A unified visual-point interface connects decision-making to motion by allowing the model to specify destinations directly in images and revise its decisions from execution feedback. Together, these components support sustained navigation across different task requirements and environments. SuperNav outperforms four evaluated baselines on instance-level, multi-object, and demand-driven tasks. Category-level evaluation on HM3D and deployment on a real quadruped robot further demonstrate its applicability across environments. Project Page: https://zju3dv.github.io/SuperNav/","authors":["Jinkai Zhang","Jingyi Xu","Yuanhong Yu","Jiarui Guo","Ruizhen Hu","Hujun Bao","Xiaowei Zhou","Sida Peng"],"published":"2026-10-08T15:19:40Z","updated":"2026-10-08T15:19:40Z","abstract_url":"https://arxiv.org/abs/2610.12126v1","html_url":"https://arxiv.org/html/2610.12126v1","pdf_url":"https://arxiv.org/pdf/2610.12126v1.pdf","matched_keywords":["3d","agent","instance","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12107v1","title":"ContourVLA: A Closed-Loop Perception-Action Contour Policy for Generalized Referring Expression Segmentation","abstract":"Generalized referring expression segmentation (GRES) requires dynamically balancing high-level semantics for identifying a variable number of language-specified referents with fine-grained visual evidence for precise boundary delineation. This requirement challenges existing cascaded vision-language architectures, which typically rely on static feature interfaces and single-pass mask prediction, limiting adaptive perception and geometric correction. We introduce ContourVLA, a vision-language-action policy that recasts GRES as a closed-loop visuomotor process, in which editable contours serve as explicit policy states that condition multimodal perception and are updated by geometric action chunks. Evolution-Aware Semantic Scheduling (EASS) couples contour-guided bidirectional boundary sampling with state-conditioned routing of multilevel multimodal features, adapting perception to each contour state. Following supervised initialization, Dustbin-Augmented Entropic Credit Transport GRPO (DECT-GRPO) jointly optimizes discrete grounding and continuous contour actions with instance-level credits. Its rollout rewards and credits are derived from soft prediction-target correspondences that account for false positives and missed targets. ContourVLA improves gIoU over the strongest evaluated baselines by 8.7, 2.8, and 2.7 points on gRefCOCO val, testA, and testB, respectively, and achieves the highest mIoU across all eight RefCOCO, RefCOCO+, and RefCOCOg splits.","authors":["Ruicheng Zhang","Kaiwen Shen","Jiaqi Hou","Shuhan Yang","Junchao Huang","Kewei Zhang","Jun Zhou","Li Jiang","Shen Zhao"],"published":"2026-10-08T15:06:00Z","updated":"2026-10-08T15:06:00Z","abstract_url":"https://arxiv.org/abs/2610.12107v1","html_url":"https://arxiv.org/html/2610.12107v1","pdf_url":"https://arxiv.org/pdf/2610.12107v1.pdf","matched_keywords":["instance","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12104v1","title":"VINCIE-NExT: Unlocking Video Editing from Images via In-Context Modeling","abstract":"Building a capable video editor remains significantly harder than a video generator: editing requires (source, instruction, edited) triplets that are prohibitively expensive to annotate and difficult to synthesize at scale, whereas image editing has already reached maturity with millions of such pairs readily available. In this work, we introduce VINCIE-NExT, a unified framework that transfers editing capability from images to videos through in-context visual demonstrations, alleviating the need for large-scale paired video editing data. VINCIE-NExT decomposes video editing into a structured chain of composable sub-tasks (Video -> Image -> Image -> Video), routing editing intent through the image domain and enabling scalable joint training from heterogeneous image and video corpora under a unified diffusion objective. An image editing pair, synthesized by the model or supplied by the user, is prepended as an in-context visual demonstration that serves as a spatial appearance blueprint for every output frame. To ground appearance edits across the interleaved context, we introduce a novel position encoding that links image demonstrations and video frames in a shared spatial coordinate system, enabling pixel-faithful propagation of appearance changes to every output frame. Chain-of-Editing further provides principled test-time scaling: by executing the sub-task chain as progressive diffusion stages, editing quality can be improved by investing additional compute without retraining. Comprehensive experiments on OpenVE-Bench demonstrate the state-of-the-art performance across diverse editing categories, with ablations confirming the effectiveness of each component.","authors":["Leigang Qu","Feng Cheng","Ziyan Yang","Bangbang Yang","Zhaoyang Huang","Wei Chow","Yicong Li","Wenjie Wang","Tat-Seng Chua","Yan Zeng"],"published":"2026-10-08T15:03:48Z","updated":"2026-10-08T15:03:48Z","abstract_url":"https://arxiv.org/abs/2610.12104v1","html_url":"https://arxiv.org/html/2610.12104v1","pdf_url":"https://arxiv.org/pdf/2610.12104v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12095v1","title":"DVLA-RL++: Dual-Level Vision-Language Alignment with Reinforcement Learning Gating for Few-Shot Learning","abstract":"Few-shot learning aims to recognize novel categories from limited labeled examples. Recent studies incorporate textual semantics to compensate for limited visual observations and improve class representations. However, high image-text agreement may reflect both intrinsic object properties and incidental context, making support prototypes susceptible to contextual contamination. To address this problem, we propose DVLA-RL++, which extends DVLA-RL with complementary semantic purification (CSP) and counterfactual reinforcement-learning gating (CRG). Specifically, CSP generates intrinsic and nuisance descriptions from labeled supports and compares their agreement with each support token. An ambiguity-dependent rejection margin guides sparse evidence allocation, while an intrinsic semantic anchor fills the unassigned mass to provide a fallback when visual evidence is unreliable. CRG learns layer-wise semantic fusion strengths using a reward that balances recognition performance and nuisance exposure. An independently executed reference trajectory on the same episode provides a paired learning signal. Theoretical analysis relates retained evidence and anchor quality to prototype stability and establishes conditions for unbiased on-policy gradient estimation. Experiments on standard, fine-grained, and cross-domain benchmarks show state-of-the-art accuracy, with an average gain of 1.4% over DVLA-RL. The project page is available at https://peacelwh.github.io/TPAMI27-DVLA-RLpp/.","authors":["Wenhao Li","Xianjing Meng","Qiangchang Wang","Zhongyi Han","Yilong Yin","Liqiang Nie"],"published":"2026-10-08T15:01:47Z","updated":"2026-10-08T15:01:47Z","abstract_url":"https://arxiv.org/abs/2610.12095v1","html_url":"https://arxiv.org/html/2610.12095v1","pdf_url":"https://arxiv.org/pdf/2610.12095v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12081v1","title":"Perception Test 2026: Challenge Summary and Extension to City-scale Audio-Visual Reasoning","abstract":"Continuing the Perception Test challenge series, we organised the fourth edition as a workshop at the European Conference on Computer Vision (ECCV) 2026 in Malmö, Sweden. This edition focused on spatial intelligence and featured four different tracks: unified multiple-choice videoQA and grounded videoQA from the original Perception Test benchmark, alongside two new tracks based on city-scale walking-tour videos (KilometerAudio and KilometerVision). In this report, we describe the new benchmarks used for the city-scale tracks and summarise the winning solutions across all tracks, including a generalist model that competed across all tracks with satisfactory performance. The winning solutions in the newly added city-scale tracks demonstrated that complex spatial and multimodal reasoning can be solved by expensive agentic pipelines, but remains difficult for multimodal models used standalone.","authors":["Fedor Kitashov","João Carreira","Shiry Ginosar","Dima Damen","Andrew Zisserman","Viorica Pătrăucean"],"published":"2026-10-08T14:54:26Z","updated":"2026-10-08T14:54:26Z","abstract_url":"https://arxiv.org/abs/2610.12081v1","html_url":"https://arxiv.org/html/2610.12081v1","pdf_url":"https://arxiv.org/pdf/2610.12081v1.pdf","matched_keywords":["video","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12073v1","title":"A Minimal Optical-Flow Representation for Vision-Based Tactile Rotation Classification in Robotic Manipulation Across Gravity Domains","abstract":"Vision-based tactile sensors provide rich contact information, but processing high-resolution images can be costly for resource-constrained platforms such as space robots. This work investigates whether a compact representation of tactile motion can classify object rotation across different gravity conditions. Dense optical flow from a simulated GelSight Mini is aggregated over a 7x9 grid into 126 features and used to classify the direction of load-induced rotation under Earth, Mars, Moon, and orbital gravity. Gravity causes a small but significant shift in these features, accounting for 1.6% of their variance (R2 = 0.016). Despite its small magnitude, this shift affects models trained only on Earth data: XGBoost accuracy decreases from 94.4% on Earth to 75.9% in orbit. In contrast, a single model trained across all four gravity domains achieves 96.3% overall accuracy and 95.1%-97.0% across individual domains, without using gravity as an input. The representation can also be reduced to 40 features while retaining 95.7% accuracy, with XGBoost requiring only 0.14 ms per inference. These findings show that Earth-gravity performance alone is insufficient to establish the transferability of tactile perception for space robotic manipulation, highlighting the need to account for gravity-induced domain shifts during training and validation.","authors":["Oscar Martinez-Bernal","Mario Cavero-Vidal","Francesco Grella","Carol Martinez"],"published":"2026-10-08T14:50:08Z","updated":"2026-10-08T14:50:08Z","abstract_url":"https://arxiv.org/abs/2610.12073v1","html_url":"https://arxiv.org/html/2610.12073v1","pdf_url":"https://arxiv.org/pdf/2610.12073v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12069v1","title":"LIVIN: Benchmarking Spatial and Embodied Intelligence in Digital Twins of Lived-In Homes","abstract":"Realistic household simulation must capture not only diverse environments but also the lived-in object arrangements and spatial constraints that shape robot motion and interaction. Existing resources often trade off scale, real-world correspondence, and interaction readiness, leaving a gap in faithful, interactive replicas of how real homes are actually arranged. To this end, we introduce LIVIN, a benchmark for spatial and embodied intelligence built on digital twins of 30 diverse lived-in homes. These replicas preserve observed room layouts, furniture configurations, and everyday belongings. To construct them, we design a human-in-the-loop workflow comprising instance recognition, architectural reconstruction, and object generation and placement, with intermediate results reviewed and corrected by humans against the source observations at each stage. We evaluate four tasks in LIVIN: 3D detection, 3D reconstruction, navigation, and loco-manipulation. Our evaluations show that current methods remain challenged by the dense object arrangements, occlusions, limited free space, and constrained interaction regions found in realistic lived-in homes. We hope LIVIN will help advance embodied AI in real-world homes, from spatial understanding to robotic interaction, and ultimately bring embodied intelligence into everyday home environments.","authors":["Peijun Xu","Chuansen Nie","Yiyang He","Yinuo Bai","Jingyang Liu","Kuixiang Shao","Yuyang Jiao","Kuanhao Xia","Jiayi Zhu","Zitian Yang","Yanqi Zhang","Tianye Tan","Shuwei Di","Junyi Xu","Jingyi Yu","Jiayuan Gu"],"published":"2026-10-08T14:47:30Z","updated":"2026-10-08T14:47:30Z","abstract_url":"https://arxiv.org/abs/2610.12069v1","html_url":"https://arxiv.org/html/2610.12069v1","pdf_url":"https://arxiv.org/pdf/2610.12069v1.pdf","matched_keywords":["3d","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12060v1","title":"Look Back, Think Ahead: Visual Memory on Demand for Efficient Multimodal Reasoning","abstract":"Processing long visual token sequences from high-resolution images makes multi-step reasoning computationally expensive for multimodal Large Language Models (MLLMs). Existing one-shot pruning and aggregation methods compress visual tokens into a fixed context before decoding. However, visual evidence needs can shift as reasoning unfolds, making it difficult for a fixed compressed context to retain all the details needed across stages. To address this challenge, we propose ViMoD, a lightweight framework that maintains a compact visual context while preserving access to original fine-grained evidence as reasoning needs evolve. Deformable Aggregation of Region-wise Tokens (DART) learns content-adaptive groups and aggregation capacities, constructing compact Coarse representations linked to recoverable original Fine tokens. Temporal Routing for Adaptive Contextual Evidence (TRACE) integrates decoding history to anticipate upcoming evidence needs and select, retain, or replace active Fine-token groups. Selected Fine tokens augment the persistent Coarse context in the frozen backbone, enabling stage-specific evidence access without continuously attending to all visual tokens. On Qwen3-VL-4B, ViMoD outperforms all evaluated baselines on all eight reasoning benchmarks at a 20% target visual token budget, improving the mean normalized score by 39.0% over the strongest evaluated one-shot baseline. These gains are achieved with only 0.0546% additional trainable parameters relative to the frozen backbone.","authors":["Yicheng Xue","Han Wu","Jufeng Yang","Minjing Dong","Xinghao Chen","Hanting Chen","Jianyuan Guo"],"published":"2026-10-08T14:42:57Z","updated":"2026-10-08T14:42:57Z","abstract_url":"https://arxiv.org/abs/2610.12060v1","html_url":"https://arxiv.org/html/2610.12060v1","pdf_url":"https://arxiv.org/pdf/2610.12060v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11993v1","title":"DataVista: Diagnosing Multimodal LLMs on Data Video Understanding","abstract":"Data video is a media form that integrates data visualization with video narrative, widely adopted in news reporting and business analysis. Compared with general video understanding, data video understanding places greater emphasis on accurately reading data from animated charts, integrating evidence across charts and time, and understanding how narrative organization and visual design communicate information. Yet existing benchmarks target either general videos or static charts, and data video understanding has not been systematically evaluated. We present DataVista, the first benchmark for data video understanding, containing 961 real-world data videos and 6,775 evaluation questions organized under a three-level progressive capability framework (data perception, temporal reasoning, narrative understanding) with 10 fine-grained question types across five topic domains. Systematic evaluation of 19 mainstream MLLMs shows that the best-performing model, Gemini-3.1-Pro, achieves 70.0% overall accuracy, still far below human expert performance, with models performing worst on Causal Reasoning and Narrative Structure. Increasing frame counts and adding subtitles mainly benefit data perception and temporal reasoning, with limited gains in narrative understanding. Further analysis of model responses identifies typical failure modes in chart reading, evidence judgment, and instruction understanding. The benchmark is available at https://github.com/HKUSTDial/DataVista.","authors":["Yupeng Xie","Zhenyang Wang","Jiayi Zhu","Yinghao Tang","Zhouan Shen","Yiyu Chen","Yuyu Luo"],"published":"2026-10-08T14:02:35Z","updated":"2026-10-08T14:02:35Z","abstract_url":"https://arxiv.org/abs/2610.11993v1","html_url":"https://arxiv.org/html/2610.11993v1","pdf_url":"https://arxiv.org/pdf/2610.11993v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11986v1","title":"FearCaut-Qwen: Affective Steering in a Vision-Language Model Shifts the Decision Criterion for Hazard Assessment","abstract":"Vision-language models (VLMs) show great potential for damage assessment after a disaster, but a recurring deficiency is that they are reluctant to declare a hazard; that is, recall is low even when overall accuracy appears adequate. This study examines that deficiency by using signal detection theory to decompose the decision behavior into perceptual capability and decision-criterion placement. We then propose a novel method for correcting the over-conservative decision policy, inspired by the finding that fear makes humans risk-averse, and ask whether an affective representation associated with fear can be causally manipulated to similarly alter a VLM's decision tendency. Using mechanistic interpretability, we localize a causally implicated affective circuit in the model and use activation steering to manipulate it while observing the effect on downstream prediction. The method is tested on a two-stage SeisMLLM pipeline built on Qwen2.5-VL-7B-Instruct, which flags only 27.0% of genuinely unsafe buildings on the SeisMLLM-1K test split and never issues a false Red, an SDT criterion of c = +1.354, despite adequate evidence quality (d' = 1.521). An affective direction is localized on emotion-rich natural scenes, causally validated by sparse-neuron knockout and distributed steering on held-out emotion data, and then injected into the building task. Fear-direction injection raises Red recall to 75.7% (p<0.001), and subtracting the same direction suppresses Red predictions entirely, whereas norm-matched random and matched happiness directions show no significant effect. The mechanism is a shift in criterion (c=-1.515) while discrimination is not improved (d'=-0.493). These results show that VLM decisions can be adjusted at inference time without retraining and demonstrate how mechanistic interpretability can be used to diagnose and control VLM decision behaviors in engineering applications.","authors":["Xiaoshan Zhou"],"published":"2026-10-08T13:57:46Z","updated":"2026-10-08T13:57:46Z","abstract_url":"https://arxiv.org/abs/2610.11986v1","html_url":"https://arxiv.org/html/2610.11986v1","pdf_url":"https://arxiv.org/pdf/2610.11986v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11967v1","title":"Learning Which Correspondences to Trust: Confidence-Weighted Event-Camera Localization in LiDAR Maps","abstract":"Localizing an event camera against a pre-built LiDAR map can be cast as dense optical-flow estimation between a rendered depth view and an event image, followed by a Perspective-n-Point (PnP) solver over the induced 3D-2D correspondences. Existing pipelines rely on geometric consensus during pose estimation, but do not explicitly model the reliability or pose informativeness, i.e., how strongly a correspondence constrains the camera pose, of individual correspondences. We show that the natural way to learn it -- using the per-correspondence error to constrain the learning of confidence -- suffers from a depth-dependent bias: small pixel errors reside predominantly at large depths and do not lead to high pose informativeness. Instead, in our method (CELL), we learn a per-correspondence confidence end-to-end through the pose, using a differentiable probabilistic PnP whose log-partition term encourages weight configurations that yield a better-constrained pose distribution. The learned confidence is used in three ways: (i) it reweights the flow supervision in a decoupled training scheme that keeps pose gradients out of the flow/edge backbone; (ii) it drives a probabilistic correspondence selection at test time; and (iii) together with the network's edge-probability it weights a final edge-matching refinement. We further design a partial-completion depth representation that adds signal without hallucinating across large gaps. On M3ED and DSEC our full system improves over the LEAR baseline on the majority of the evaluated sequences: it reduces the median translation error by up to 26.9% and the median rotation error by up to 15.8%.","authors":["Panagiotis Kiousis","Kuangyi Chen","Jun Zhang","Friedrich Fraundorfer"],"published":"2026-10-08T13:45:54Z","updated":"2026-10-08T13:45:54Z","abstract_url":"https://arxiv.org/abs/2610.11967v1","html_url":"https://arxiv.org/html/2610.11967v1","pdf_url":"https://arxiv.org/pdf/2610.11967v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11942v1","title":"Right Screen, Wrong Transition: World Models as Verifiers for GUI Agents","abstract":"A login screen that appears after a tap on Sign in is expected; the same screen after a tap on View order is an attack. For GUI agents, safety is therefore a property of the transition rather than of the screen, and a monitor that inspects only screens can be defeated by reusing a legitimate one. Judging a transition requires an expectation of what should have followed the action. Existing GUI world models provide one, but they output it as text, code, or images, so checking it against the observed screen requires a second model to judge the two. We argue that a world model meant for verification should instead predict in the space in which observations are encoded, and present LGWM, a decoder-free, action-conditioned world model that predicts the representation of the next screen directly, trained without semantic annotation on 1.85M real GUI transitions. Verification reduces to a vector comparison, and the same signal reveals whether a mismatch is harmful. We evaluate on RSWT-BENCH, a diagnostic where each credential screen appears under both a legitimate and a hijacked transition, so detectors that see only the screen are at chance by construction. The training-free score reaches 0.987 AUC at 17 ms per decision, on par with the strongest closed-source VLMs and about ten AUC points above generative GUI world models at over three orders of magnitude lower latency. The residual direction reaches 0.953 AUC at separating harmful from benign violations, where prompted VLMs are near chance. Further analyses show that the prediction is a usable future state rather than an anomaly score. World models have mostly served as simulators or planners; our results point to a third role, verification, for which predicting in representation space is the natural design.","authors":["Jiaming Zhang","Xuan Wang","Fuyao Zhang","Yang Cao","Lingjuan Lyu","Wei Yang Bryan Lim"],"published":"2026-10-08T13:33:23Z","updated":"2026-10-08T13:33:23Z","abstract_url":"https://arxiv.org/abs/2610.11942v1","html_url":"https://arxiv.org/html/2610.11942v1","pdf_url":"https://arxiv.org/pdf/2610.11942v1.pdf","matched_keywords":["agent","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11924v1","title":"Revisiting Identity and Spectra Dispersion in Media-Bridged Time Series Forecasting: Linking Multivariate Signals and Narrative Flows","abstract":"Media-bridged time series forecasting is expanding to encompass traditional \"multivariate\" and emerging \"multimodal\" (e.g., through textual assistance). Existing Time Series Forecasting (TSF) models still rely on paradigm-specific relation, fusion, and temporal modules, hindering a common forecasting backbone across numerical and pre-aligned narrative-flow settings. To explore this, we propose the Multimedia Identity-Aware Prism Network (MIDAPN), a unified spatiotemporal forecasting backbone based on media-general graph adaptation and automatic temporal learning: (1) Following media pre-alignment, our Multimedia Identity-Aware Graph (MIDAG) revisits identity through static essence, dynamic behavior, and latent commonality, inducing affinities that extend variable-specific dependencies across media. Contextual Identity Modulation (CIM) further refines discriminative aggregation. (2) We develop Spectral Prism Convolution (SPConv) to automatically perform hierarchical temporal analysis, balancing coarse trends and fine-grained details. Meanwhile, its Adaptive Search Guidance configures a scale-efficient architecture for temporal-dimension reconstruction. These decoupled yet synergistic components jointly address media identity disentanglement and temporal-scale mismatch. Comprehensive evaluations involving 16 SOTA TSF models across 13 \"multivariate\" and 12 \"multimodal\" datasets, alongside targeted long-context comparisons against 14 time series foundation models and fused pretrained language models, demonstrate MIDAPN's consistent superiority and broad shared backbone compatibility. The code is available at \\href{https://github.com/leijieruilq/MIDAPN/tree/main}{https://github.com/MIDAPN}.","authors":["Jierui Lei","Wenjian Zhang","Qingyi Yang","Yuyang Hong","Fangzheng Chen","Zhengbo Zhang","Haina Tang","Shiming Xiang"],"published":"2026-10-08T13:20:49Z","updated":"2026-10-08T13:20:49Z","abstract_url":"https://arxiv.org/abs/2610.11924v1","html_url":"https://arxiv.org/html/2610.11924v1","pdf_url":"https://arxiv.org/pdf/2610.11924v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11907v1","title":"Beyond Visual Enhancement: Adaptive Multi-Context Steering to Mitigate LVLM Hallucinations","abstract":"Hallucination remains a significant challenge in Large Vision-Language Models (LVLMs). Existing training-free methods generally mitigate hallucinations through contrastive decoding or visual enhancement, often increasing the relative influence of visual evidence during generation. This raises a fundamental question: Can LVLMs dynamically regulate the contributions of different context sources to suppress hallucinations? In this work, we investigate and quantify how LVLMs coordinate multiple context sources during decoding and examine how this intrinsic behavior can guide hallucination mitigation. We find that LVLMs exhibit an intrinsic vision-attending tendency that can guide adaptive visual steering, while textual contexts can also contribute to hallucination mitigation. Motivated by these findings, we propose AIMS (Adaptive Information Multi-source Steering), a lightweight training-free framework that adaptively coordinates visual, prefilled textual, and generated contexts during decoding. Specifically, AIMS constructs compact prototypes for the three context domains and estimates their affinities with the current query to determine head-wise steering weights. The resulting multi-source steering direction is applied to the query representation, enabling adaptive context integration without additional model training or auxiliary forward passes. Extensive experiments across multiple LVLMs and decoding strategies demonstrate that AIMS effectively mitigates object hallucination while maintaining competitive general-purpose multimodal capabilities.","authors":["Shuran Ma","JiaLe Li","Yuxin Dong","Shan Zheng","Qingyun Jiang","Xiang Chen","Qi Zhu","Deyi Ji","Yifan Yang","Jianfeng Pan","Yu Tian","Xue Yang"],"published":"2026-10-08T13:08:44Z","updated":"2026-10-08T13:08:44Z","abstract_url":"https://arxiv.org/abs/2610.11907v1","html_url":"https://arxiv.org/html/2610.11907v1","pdf_url":"https://arxiv.org/pdf/2610.11907v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11857v1","title":"Pose-Free Feed-Forward 3D Inpainting via Learnable Mask Attention and Support Token Refinement","abstract":"3D scene inpainting aims to recover missing or occluded regions in edited 3D scenes, while ensuring geometric and textural consistency. Existing approaches, however, typically require accurately calibrated camera poses, which restricts their applicability in casual, in-the-wild scenarios and introduces additional preprocessing overhead. To overcome this limitation, we present FreeInpaint, a novel feed-forward framework that generates complete and 3D-consistent scenes directly from unposed multi-view images with masked regions. At its core, FreeInpaint extends a 3D foundation model to propagate masked regions from a reference view to other unposed views, bridging 3D reconstruction and scene inpainting while preserving the model's native ability to recover camera poses and scene geometry. Our method addresses two key challenges in adapting feed-forward 3D foundation models to masked inputs. First, masked regions can corrupt cross-view correspondence reasoning, degrading pose estimation and geometry recovery. To address this, we introduce a Learnable Mask Attention mechanism that preserves the spatial anchoring of reliable observations while allowing masked regions to progressively absorb useful context in deeper layers. Second, under severe occlusions, a single forward pass often lacks sufficient appearance evidence for high-fidelity completion. Therefore, we propose a Support Token Refinement strategy, which injects diffusion-generated support evidence as confidence-weighted auxiliary tokens to refine under-observed regions while preserving the original spatial anchor. Extensive experiments across diverse datasets demonstrate that FreeInpaint achieves superior inpainting quality, eliminating the reliance on pre-computed camera poses while keeping a fast inference speed. The project page is https://rorisis.github.io/FreeInpaint/.","authors":["Jingyi Pan","Dan Xu","Qiong Luo"],"published":"2026-10-08T12:38:48Z","updated":"2026-10-08T12:38:48Z","abstract_url":"https://arxiv.org/abs/2610.11857v1","html_url":"https://arxiv.org/html/2610.11857v1","pdf_url":"https://arxiv.org/pdf/2610.11857v1.pdf","matched_keywords":["3d","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11850v1","title":"VEDJE: Video-Efficient Discriminative Joint Encoder for Scalable Video-Text Retrieval","abstract":"Finding the right video often requires distinguishing similar scenes in which different events occur. Joint matching improves retrieval, but processing rich video representations for each query is costly. VEDJE compresses features within sampled frames while keeping their representations separate in a reusable cache. Feature-change prediction supplies an auxiliary training signal that improves retrieval from the compressed cache without adding work at query time. On MSR-VTT, MSVD, DiDeMo, and ActivityNet, VEDJE improves R@1 over matched first-stage retrievers in both retrieval directions. On MSR-VTT, it reaches 59.8 text-to-video R@1 with a fine-tuned VideoCLIP-XL first stage. In the VideoPrism configuration, shrinking the per-video cache fourfold to 12 KiB preserves text-to-video recall within 0.2 points. These results show that accurate video search can operate on compact evidence, encoded once and reused as new queries arrive.","authors":["Shahaf Wagner","Gabriele Serussi","Dan Ben Ami","Tomer Galanti","Chaim Baskin"],"published":"2026-10-08T12:37:12Z","updated":"2026-10-08T12:37:12Z","abstract_url":"https://arxiv.org/abs/2610.11850v1","html_url":"https://arxiv.org/html/2610.11850v1","pdf_url":"https://arxiv.org/pdf/2610.11850v1.pdf","matched_keywords":["video","retrieval","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11846v1","title":"Open-Vocabulary Audio-Visual Event Localization via Complex-Valued Fusion","abstract":"Open-Vocabulary Audio-Visual Event Localization (OV-AVEL) labels each video segment with an event class, including classes that were never seen during training. The dominant pipeline uses a frozen multimodal foundation model (e.g. ImageBind) to embed the visual frame, the audio mel-spectrogram, and each candidate class name into a shared space, then computes two cosine similarities for each segment against each class: visual-text and audio-text. Existing methods then collapse this pair into a single scalar score with a fixed rule (geometric mean, weighted average) before taking the argmax. Instead, we compute complex-valued similarities and learn their fusion using a complex-valued neural network (CVNN). Each modality's standard representation becomes the real part of our pipeline, and a paired companion stream supplies the imaginary part. We use imaginary part of iHSV for visual modality and CycleGAN-translated phase spectrogram for audio modality as these companion streams. This results in two complex similarities, which are then fused. While the vision and audio encoders remain frozen, only the temporal-attention blocks and the fusion CVNN are trained. The four-stream complex architecture sets a new state of the art on both OV-AVEL benchmarks. On the open (unseen-class) split of OV-AVEBench we reach 66.5/59.1/54.1% Acc/Seg-F1/Event-F1 (+1.6/+4.1/+6.6 over the previously reported fine-tuned baseline), with consistent gains for seen classes as well. We also modify AVE dataset for this task and observe that our architecture reaches 60.7/51.9/50.4% Acc/Seg-F1/Event-F1, achieving state-of-the-art OV-AVEL results on it as well. We also propose a two-stream alternative, which also sees great improvements over the baseline.","authors":["Anirudh Praveen","Koteswar Rao Jerripothula","Pratik Joshi","Aveen Dayal","Neela Sawant"],"published":"2026-10-08T12:34:24Z","updated":"2026-10-08T12:34:24Z","abstract_url":"https://arxiv.org/abs/2610.11846v1","html_url":"https://arxiv.org/html/2610.11846v1","pdf_url":"https://arxiv.org/pdf/2610.11846v1.pdf","matched_keywords":["video","representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11826v1","title":"From Suppression to Repair: Mitigating Object Hallucination in Large Vision-Language Models via Localized Distribution Alignment","abstract":"Object hallucination remains a major obstacle for large vision-language models (LVLMs) to generate reliable content. An intuitive mitigation strategy is to suppress hallucination-related components in hidden representations. However, these components may also contain useful information, and suppressing them can weaken the model's multimodal capabilities. In this paper, we propose ResOT, a training-free method that repairs representations at inference time through localized distribution alignment. Specifically, ResOT projects dominant hallucinated directions away from the faithful subspace, forming a low-dimensional residual subspace for intervention. Within this subspace, ResOT uses Gaussian optimal transport (OT) to align the hallucinated distribution with the faithful one. The resulting map defines repair targets with minimal changes to the original representations. At inference, ResOT adaptively controls how far each token state moves toward its OT target. Experiments on three representative LVLMs show that ResOT substantially reduces object hallucination while improving image caption quality and multimodal performance across multiple benchmarks. Code will be released.","authors":["Chen Zhao","Xingping Dong","Jiachun Shi","Liang Peng","Chong Wang","Zhen Lei","Ran He","Bo Du"],"published":"2026-10-08T12:25:50Z","updated":"2026-10-08T12:25:50Z","abstract_url":"https://arxiv.org/abs/2610.11826v1","html_url":"https://arxiv.org/html/2610.11826v1","pdf_url":"https://arxiv.org/pdf/2610.11826v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11810v1","title":"Seek-and-View Reasoning for Multi-View Spatial Understanding","abstract":"Existing approaches to multi-view spatial reasoning operate largely on sparse input views. Vision-language models (VLMs) are thus restricted to understand a scene and infer spatial relations within these fixed views, leading to fragile cross-view alignment and geometry-to-language bottleneck. To address these issues, we formulate a novel Seek-and-View reasoning approach to find implicit cross-view spatial evidence by locating a question-relevant view to support the spatial reasoning. To realize this approach, we propose Vantage, a training-free model-agnostic reasoning framework that pairs a VLM with a 3D foundation model: a viewpoint-grounded reasoning stage for question analysis and view planning, followed by a geometry-grounded evidence augmentation stage to effectively synthesize and incorporate visual evidence into the final reasoning. Comprehensive experiments on six VLMs demonstrate consistent improvements on five benchmarks without fine-tuning. Overall, by revealing spatial evidence through view-grounded reasoning, Vantage can largely reduce reliance on language-based cross-view alignment and improve multi-view spatial understanding. Our code is available at https://github.com/q1xiangchen/Vantage.","authors":["Qixiang Chen","Cheng Zhang","Fucai Ke","Chi-Wing Fu","Jianfei Cai","Jingwen Ye"],"published":"2026-10-08T12:18:01Z","updated":"2026-10-08T12:18:01Z","abstract_url":"https://arxiv.org/abs/2610.11810v1","html_url":"https://arxiv.org/html/2610.11810v1","pdf_url":"https://arxiv.org/pdf/2610.11810v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11794v1","title":"Memento 3: Model-Based Recursive Self-Improvement through Reflective Rulebooks","abstract":"Learning to act in unfamiliar environments requires agents to infer how the world works and revise that understanding as new evidence arrives. Yet limited observations can support multiple world models that explain past interactions but predict different outcomes in unseen states. We introduce Memento 3, building on the Memento series to enable frozen LLM agents to continually learn explicit world models through external memory. The agent maintains a natural-language rulebook as persistent semantic memory, recording revisable hypotheses about environment dynamics while leaving unknown aspects underspecified. It compiles this rulebook into executable code for prediction and planning. Through a continual loop of observation, reflection, rule revision, compilation, and verification, the agent uses prediction errors to refine both the rulebook and its code. Updated code is accepted only when the LLM judges it faithful to the rulebook and cell-exact replay reproduces the observed transitions. We investigate this process as a model-based route to recursive self-improvement (RSI): the agent autonomously explores the environment, revises its world model, and uses verified updates to guide subsequent interaction and learning, while the underlying LLM remains fixed. A population extension maintains multiple world models in parallel, sharing interaction evidence and using their predictions to guide exploration. On ARC-AGI-3, the single-model agent clears every level of all 25 public games, achieves a mean Relative Human Action Efficiency (RHAE) of 100.0, and uses 44% of the human action count. In an Atari Pong case study, a learned feedback controller wins 21:0 in each of three evaluated episodes with different openings, without further LLM calls.","authors":["Haoyu Zhao","Zhengxu Yu","Zhiyuan He","Meng Fang","Rasul Tutunov","Haitham Bou-Ammar","Weilin Luo","Jun Wang"],"published":"2026-10-08T12:06:54Z","updated":"2026-10-08T12:06:54Z","abstract_url":"https://arxiv.org/abs/2610.11794v1","html_url":"https://arxiv.org/html/2610.11794v1","pdf_url":"https://arxiv.org/pdf/2610.11794v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11791v1","title":"Phase-aware video generation for physics-grounded dynamics and interactions","abstract":"Generating physically plausible videos for solid-gas dynamics is challenging as different phases exhibit distinct dynamics yet remain coupled through physical interactions. We present PAVG, a Phase-Aware Video Generator for solid-gas dynamics and interactions. It employs a dual-branch architecture to explicitly model the distinct dynamics of solids and gases, while spatiotemporal cross-attention captures their physical interactions. This design enables PAVG to preserve phasespecific motion characteristics while producing physically consistent responses across phases. To facilitate this task, we further construct a simulation corpus comprising over 700K physical trajectories across diverse solid, gas, and solid-gas interaction scenarios. Extensive evaluations demonstrate that our PAVG produces videos with improved motion adherence, physical plausibility, and visual quality compared with existing approaches.","authors":["Jingfeng Ou","Kun Wang","Rui Zhao","Jingwei Guan","Limin Wang","Chao Dong","Xingyu Zeng"],"published":"2026-10-08T12:04:46Z","updated":"2026-10-08T12:04:46Z","abstract_url":"https://arxiv.org/abs/2610.11791v1","html_url":"https://arxiv.org/html/2610.11791v1","pdf_url":"https://arxiv.org/pdf/2610.11791v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11781v1","title":"Skill-V: Verifiable Self-Evolving Skill Library for Interactive Agents","abstract":"Interactive agents can turn experience into reusable skills, yet existing self-evolving skill libraries primarily improve by accumulating new knowledge. Failures may lead to new skills, while previously stored skills are less often revisited as new evidence arrives. However, growth alone does not ensure reliability, as a retrieved skill may be inapplicable under the current task conditions, and an existing skill may encode a mis-specified operational boundary. Reliable skill evolution therefore requires not only adding knowledge, but also testing and revising what is already stored. We introduce Skill-V, a verifiable self-evolving skill library. To make stored knowledge testable, we propose representing skills as versioned, falsifiable contracts that link semantic intent to observable behavioral criteria. We use environment outcomes to drive library evolution. Specifically, task failures motivate skill addition, while disagreements between contract evaluations and task outcomes guide revisions to existing skill boundaries. To validate these revisions, we require them to preserve protected semantic constraints and satisfy non-regression criteria for rubric-outcome metrics on historical replay evidence. Finally, we employ an applicability-aware filter to exclude candidates judged confidently inapplicable to the current task. Across ALFWorld and WebShop, Skill-V achieves success rates of 95.3% and 85.9%, respectively, while maintaining a more compact skill library than growth-oriented baselines. Applicability-aware filtering reduces incorrect skill invocations, and outcome-grounded revisions correct mis-specified skill boundaries without degrading performance on previously observed evidence. These results show that reliable skill evolution requires more than accumulating experience: the library must learn which knowledge to retain, when to revise it, and when it should be applied.","authors":["Jie Ma","Zhipeng Qian","Yufei Ma","Zihan Liang","Jiayi Ji","Qingpeng Cai","Ben Chen","Peng Jiang","Xiaoshuai Sun"],"published":"2026-10-08T11:59:42Z","updated":"2026-10-08T11:59:42Z","abstract_url":"https://arxiv.org/abs/2610.11781v1","html_url":"https://arxiv.org/html/2610.11781v1","pdf_url":"https://arxiv.org/pdf/2610.11781v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11770v1","title":"From Video Clips to Creation Trajectory: Sora100K for AI-Native Video Creation","abstract":"AI-Native video creation is shifting from isolated video clips toward iterative video creation workflows. However, existing datasets remain largely video clips, representing video generation and editing as separate tasks rather than connected stages of a video creation workflow. In this paper, we introduce Sora100K, a dataset that represents the AI-Native video creation workflow as a structured video creation trajectory. Specifically, we first identify video creation trajectories and decompose them into three subsets according to their structural roles: text-to-video generation records as roots, single-turn video editing records as editing edges, and multi-turn video editing records as complete trajectories. Then, we use a VLM to assign semantic annotations for generation roots and editing-operation annotations for editing edges. A strict construction pipeline further reconstructs source-to-edit lineage, editing order, and intermediate video states while ensuring data quality. Finally, we perform lightweight adaptation on LTX-2 models to assess the supervision value of Sora100K. The results show improvements in visual quality, multi-shot generation, and cross-shot consistency, while successive-turn evaluation reveals that following multi-turn editing instructions remains challenging. Sora100K establishes a new data foundation for AI-Native video creation beyond isolated video clips and toward structured video creation trajectory. The dataset and supplementary materials are publicly available at https://huggingface.co/datasets/ysicong/Sora100K.","authors":["Sicong Yang","Ruihuan Yang","Jian Lu","Jianfei Yuan","Xiaodong Cun","Xiuli Bi"],"published":"2026-10-08T11:52:10Z","updated":"2026-10-08T11:52:10Z","abstract_url":"https://arxiv.org/abs/2610.11770v1","html_url":"https://arxiv.org/html/2610.11770v1","pdf_url":"https://arxiv.org/pdf/2610.11770v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11756v1","title":"Memory Forcing: Attendable Mid-Horizon History for Streaming Video Generation","abstract":"Autoregressive video diffusion enables causal video streaming without a bidirectional pass over the full clip, but existing few-step systems usually retain only the opening and most recent frames in a fixed-size KV cache. Once an event leaves this window, later frames can no longer attend to it, a failure we term mid-horizon forgetting. We present Memory Forcing, a few-step streaming method that preserves this missing history without increasing the cache size. Its Archive \\& Working Banks partition the cache into sink, archive, and working regions, retaining diverse intermediate events alongside recent motion under fixed memory. Because absolute temporal indices drift outside the training range, Bank-aware RoPE reassigns indices at attention time so each bank remains distinguishable. At 1.3B, Memory Forcing leads on longer clips, shows the smallest drop from 5s to 60s among methods reporting all four lengths, and preserves subjects and scenes through leave-and-return. The same design scales to Wan2.2 5B, producing more physically plausible, realistic, and dynamic videos and, to our knowledge, the first public 5B model on this forcing line.","authors":["Jiaming Zhang","Xinyu Wang","Huafeng Shi","Gangshan Wu","Limin Wang"],"published":"2026-10-08T11:42:57Z","updated":"2026-10-08T11:42:57Z","abstract_url":"https://arxiv.org/abs/2610.11756v1","html_url":"https://arxiv.org/html/2610.11756v1","pdf_url":"https://arxiv.org/pdf/2610.11756v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11751v1","title":"Dino Forcing Flow Models: Do not denoise what you can predict","abstract":"Co-denoising pretrained representations such as DINO can substantially improve the training speed and quality of flow matching models, but it introduces a second denoising trajectory and requires carefully designed schedules. We propose a simpler alternative: predict the pretrained representation directly, then condition the model on its own prediction. This removes the need for a second ODE and any representation-specific denoising schedules, while retaining the benefits of representation guidance. Our approach converges substantially faster and achieves better generation quality as measured by FID score. On ImageNet, it outperforms the state of the art in latent space at 2x fewer epochs than prior methods; in pixel space, it improves FID over comparable prior methods by more than 20%. These results support a simple principle: do not denoise what you can predict. Our code is openly available at https://github.com/arijit-hub/dino_forcing.","authors":["Arijit Ghosh","Lucas Degeorge","Paul Couairon","Alexei A Efros","Vicky Kalogeiton","David Picard"],"published":"2026-10-08T11:41:13Z","updated":"2026-10-08T11:41:13Z","abstract_url":"https://arxiv.org/abs/2610.11751v1","html_url":"https://arxiv.org/html/2610.11751v1","pdf_url":"https://arxiv.org/pdf/2610.11751v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11746v1","title":"Streaming-Aware Diffusion for Real-Time Video Super-Resolution via Cross-Step Attention","abstract":"Real-time video super-resolution requires high spatio-temporal fidelity under strict latency constraints, challenging diffusion models due to their iterative sampling cost and limited temporal coordination. We propose a streaming-aware framework that adapts pretrained single-image latent diffusion models for efficient video super-resolution (VSR) by exploiting the sequential structure of video streams. Our Cross-Step Attention mechanism reuses intermediate denoising features across adjacent frames and diffusion steps, enabling temporal information exchange without explicit temporal modeling. We further introduce Trajectory-Coupled Diffusion Scheduling, which aligns adjacent diffusion states and provides cleaner intermediate representations for cross-step conditioning, improving temporal coherence. These components are integrated into a streaming inference pipeline that incrementally propagates latent states across frames, reducing the effective computational complexity from $O(N \\cdot S)$ to $O(N + S)$ for $N$ frames and $S$ diffusion steps. Experiments on REDS4 and YouHQ40-Test demonstrate improved perceptual quality and temporal realism while maintaining frame-wise stability. Our method achieves over 40 FPS at $512 \\times 512$ resolution after cold start, enabling real-time VSR without explicit temporal modeling.","authors":["Harris Partaourides","Sotirios Chatzis"],"published":"2026-10-08T11:35:09Z","updated":"2026-10-08T11:35:09Z","abstract_url":"https://arxiv.org/abs/2610.11746v1","html_url":"https://arxiv.org/html/2610.11746v1","pdf_url":"https://arxiv.org/pdf/2610.11746v1.pdf","matched_keywords":["video","representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11736v1","title":"Towards Unified Evaluation of Prompt Enhancers for Video Generation","abstract":"Modern video generators can realize increasingly complex visual narratives, positioning the prompt enhancer (PE) as a critical bridge from concise user instructions and multimodal references to structured cinematic plans. However, existing PE evaluation relies on rendered videos, imposing substantial computational and human costs, slowing PE training and iteration, and conflating PE quality with downstream generator behavior. To address this gap, we introduce PEBench, the first unified benchmark for direct PE evaluation across text-to-video, image-to-video, and reference-to-video prompt enhancement. It comprises 1,100 expert-verified cases and 1,005 visual assets, spanning 35 fine-grained tasks with diverse temporal, cinematic, audiovisual, and multi-reference requirements. In addition, we develop PEBench evaluation, an evidence-grounded framework that combines modality-aware fact extraction with rubric-based assessment across 24 criteria. Our systematic evaluation of representative open- and closed-source PE methods reveals an emerging shift from fine-grained descriptive expansion toward intent-preserving cinematic planning, while the caption-reconstruction and forward-refinement methods show complementary strengths in cinematic coverage and semantic fidelity or internal coherence, respectively. Human validation shows that PEBench scores align closely with expert judgments of enhanced prompts and downstream videos from Wan3.0 and MiniMax-H3, indicating that prompt-level evaluation reliably reflects downstream utility.","authors":["Yawen Shao","Yubo Zhu","Ziyun Dai","Zixun Fang","Kai Zhu","Zeyinzi Jiang","Yufeng Ai","Siyang Sun","Haolan Xue","Yu Shang","Yuxiang Bao","Zoubin Bi","Jingming Luo","Jie Xiao","Chaojie Mao","Zhehan Kan","Hongchen Luo","Yu Liu","Sheng Zhong","Wei Tong","Xueyang Fu","Yang Cao","Wei Zhai","Zheng-Jun Zha"],"published":"2026-10-08T11:31:13Z","updated":"2026-10-08T11:31:13Z","abstract_url":"https://arxiv.org/abs/2610.11736v1","html_url":"https://arxiv.org/html/2610.11736v1","pdf_url":"https://arxiv.org/pdf/2610.11736v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11685v1","title":"HI3D 3.0 (Twinkle3D): Object-specific 3D Asset Generation with High Resolution","abstract":"Image-to-3D generation has become increasingly capable of producing objects that closely resemble the input image, and an outstanding challenge is to reproduce the depicted object itself, including the specific geometry that defines it. Inscriptions, brand marks, and repeated structures are frequently distorted or lost, despite being critical to object identity. We present Hi3D 3.0, an image-to-3D generation system targeting object-specific fidelity, with Twinkle3D as its geometry model for generating watertight triangle meshes at $2048^{3}$ resolution. Twinkle3D advances high-fidelity geometry generation along four dimensions. First, while O-Voxel/FaithC offers high representational precision, it often suffers from poor surface quality and non-watertight geometry. We address both issues while retaining its $2048^{3}$-level precision. Second, we scale diffusion generation to sequences of up to 300K geometric tokens through a redesigned DiT architecture and large-scale distributed training optimizations, reducing training time per step from approximately ten minutes to ten seconds. Third, subsequent refinement cannot fully compensate for errors introduced during initial generation; we therefore strengthen both global shape and local detail in the initial generation stage, and the resulting single-stage model surpasses prior two-stage pipelines with $512^{3}$ refinement. Finally, we introduce a fine-grained image-3D cross-modal interaction mechanism that strengthens correspondence between visual evidence and geometric tokens, improving the recovery of object-specific structures. We evaluate geometric fidelity using alignment metrics derived from silhouettes and normal fields. Hi3D 3.0 outperforms four commercial systems across all reported metrics, recovering 82.1% of inscribed characters at 98.2% precision, compared with 21.7% recall for the strongest competitor.","authors":["Ziying Li","Shengchu Zhao","Huiang He","Yiyang Chen","Jianwen Huang","Bailin Li","Changhao Li","Jianhui Li","Jie Li","Ruiyang Liu","Yibo Luo","Tengjiao Sun","Pei Tang","Shiwen Wang","Jiaqi Wu","Kang Wu","Kaiqiao Yang","Zherui Yang","Hu Zhang","Xuezhi Zhao","Xinhe Zheng","Yukun Li","Heliang Zheng","Rongfei Jia"],"published":"2026-10-08T10:57:06Z","updated":"2026-10-08T10:57:06Z","abstract_url":"https://arxiv.org/abs/2610.11685v1","html_url":"https://arxiv.org/html/2610.11685v1","pdf_url":"https://arxiv.org/pdf/2610.11685v1.pdf","matched_keywords":["3d","representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11674v1","title":"VESSI - VLM-Enhanced Support for Surveillance and Investigations","abstract":"Automated video surveillance analysis has become a critical component of intelligence infrastructures and Law Enforcement agencies. Traditional systems lack the semantic module for comprehensive situational awareness and forensic tasks, limiting their ability to interpret events meaningfully or support post-incident investigations. This slows operational insight and increases the burden on human analysts. Recent advances in Vision-Language Models (VLMs) offer promising pathways to bridge this gap. To address this, we propose VLM-Enhanced Support for Surveillance and Investigations (VESSI), a VLM-based framework designed to enhance automated video surveillance analysis through prompt-driven interrogation of video sequences where salient visual features are converted into textual descriptions. We test our framework with four state-of-the-art models. Since most datasets for this task are unlabeled, we also propose the Composite Model Utility Score (CMUS) to assess VLM performance. Experimental results show that our solution substantially improves the analysis capabilities of human operators and enhances the flexibility of automated surveillance systems. In our evaluation, the most reliable model flagged potentially relevant activity in more than 66% of the videos while reducing review time by more than 85%, offering a practical balance between selectivity and efficiency. The model ordering produced by the reference-free CMUS evaluation was reproduced by the normal-video CMUS evaluation and matched the false-positive-rate ordering obtained from 5,909 manually referenced frames. This agreement supports the operational use of the score within the evaluated setting.","authors":["Saverio Cavasin","Pietro Tedeschi","Mattia Tamiazzo","Alessandro Brighente","Simone Milani","Mauro Conti"],"published":"2026-10-08T10:50:17Z","updated":"2026-10-08T10:50:17Z","abstract_url":"https://arxiv.org/abs/2610.11674v1","html_url":"https://arxiv.org/html/2610.11674v1","pdf_url":"https://arxiv.org/pdf/2610.11674v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11666v1","title":"Autoregressive Retriever: Improving Query Understanding from Item Feedback for Universal Multimodal Retrieval","abstract":"Universal multimodal retrieval typically encodes a query once and ranks independently indexed items by embedding similarity. This design supports efficient search, but leaves the query representation unchanged even when retrieved items could help clarify the information need. We introduce the AutoRegressive Retriever (ARR), a multimodal retrieval model that learns both to select informative items and to use their content to refine subsequent retrieval. ARR alternates between retrieving an item and updating the query embedding, then uses the final embedding to rank the collection. Supervised fine-tuning teaches the encoder to use feedback through stepwise contrastive supervision. Reinforcement learning treats feedback items as actions and optimizes their selection using the final reciprocal rank of a relevant item. A query-side adapter enables this optimization against a fixed item index. ARR demonstrates strong retrieval performance on both in-domain and zero-shot benchmarks, outperforming the compared baselines on average. Further analyses show that feedback improves retrieval at inference time and that training with feedback also improves the initial query embedding, before any item is observed.","authors":["Jianfei Zhao","Yifan Wang","Feng Zhang","Xin Sun","Chong Feng","Zhixing Tan","Yang Luo","Boyuan Pan","Xu Kai","Yao Hu"],"published":"2026-10-08T10:39:17Z","updated":"2026-10-08T10:39:17Z","abstract_url":"https://arxiv.org/abs/2610.11666v1","html_url":"https://arxiv.org/html/2610.11666v1","pdf_url":"https://arxiv.org/pdf/2610.11666v1.pdf","matched_keywords":["retrieval","representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11656v1","title":"DisFace3DNet: Explainable Facial Attractiveness Prediction via 3D Component Disentanglement","abstract":"Facial attractiveness prediction usually assigns one overall rating, leaving the roles of shape, appearance, and viewing conditions implicit. We propose DisFace3DNet, which uses 3D component disentanglement to learn seven component reference scores from overall ratings with auxiliary weak semantic supervision, without human-labeled component targets. Designated 3D representations and image cues feed jointly learned routes for identity, skin, hair, light, background, expression, and pose. A constrained fit then combines five static and two signed dynamic scores into the overall rating, exposing each component's numerical contribution and supporting component-specific comparisons across images. On SCUT-FBP5500, DisFace3DNet achieves a Pearson correlation of $0.8904\\pm0.0063$ (mean $\\pm$ standard deviation across five folds) with average human ratings; its component terms reconstruct every held-out prediction to numerical precision. Skin, hair, and facial shape account for the largest component-wise prediction variation. Human evaluation supports the score directions for facial shape, skin, and hair; expression agreement is weaker. DisFace3DNet thus connects overall prediction to quantitative analysis of the facial and contextual cues entering each estimate.","authors":["Fenggui Rao","Yan Luximon","Jie Zhang"],"published":"2026-10-08T10:33:54Z","updated":"2026-10-08T10:33:54Z","abstract_url":"https://arxiv.org/abs/2610.11656v1","html_url":"https://arxiv.org/html/2610.11656v1","pdf_url":"https://arxiv.org/pdf/2610.11656v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11617v1","title":"TAM: Task-Aware Memory Distillation for Efficient Spatiotemporal Prediction","abstract":"Knowledge distillation enables efficient spatiotemporal prediction by transferring knowledge from an accurate teacher to a compact student. However, matching outputs or features independently for each sample leaves cross-sample predictive structure underused. Exploiting this structure requires representations and historical references that reflect the dynamics of each task. We propose TAM, a Task-Aware Memory Distillation framework that organizes a frozen teacher's knowledge into a bounded, retrievable history. Memory entries encode latent features, forecast changes, or flow residuals, while task-specific selection rules identify relevant historical references. The student either matches the teacher's similarity distribution over shared references or regresses observation-conditioned residual prototypes. These objectives complement supervised prediction and conventional distillation. The teacher, memory, and auxiliary adapters are used only during training, leaving student inference unchanged. We evaluate TAM on video prediction, weather forecasting, and traffic flow prediction across multiple teacher-student configurations. Averaged over four paired runs, adding TAM improves SSIM on all six video datasets and reduces MSE on five relative to the corresponding KD baselines. Mean paired MSE reductions reach 1.86% on KittiCaltech, 1.93% on WeatherBench with a gSTA teacher, and 1.01% on TaxiBJ. These results demonstrate the utility of historical teacher supervision across distinct forecasting tasks without additional student inference cost.","authors":["Yuqi Li","Xiaoqin Feng","Fan Xu","Weilun Feng","Chuanguang Yang","Yingli Tian","Hao Wu"],"published":"2026-10-08T09:58:23Z","updated":"2026-10-08T09:58:23Z","abstract_url":"https://arxiv.org/abs/2610.11617v1","html_url":"https://arxiv.org/html/2610.11617v1","pdf_url":"https://arxiv.org/pdf/2610.11617v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11612v1","title":"PointVGGT: Zero-Shot Multiview RGB-D Point Cloud Registration with Visual Geometry Foundation Priors","abstract":"This paper addresses multiview RGB-D point cloud registration, aiming to estimate global rigid poses for unordered RGB-D scans and align them in a metrically consistent coordinate frame. The conventional pairwise-then-global paradigm suffers from locally optimized pairwise registration, severe error propagation and high computational burden. In particular, existing methods typically treat RGB data as a mere auxiliary matching cue and overlook the holistic geometric priors (e.g., camera poses and 3D models) encoded across image sequences. This paper introduces PointVGGT, a zero-shot framework built upon a novel \\emph{foundation-then-refinement} paradigm that systematically leverages visual geometry foundation models (e.g., VGGT) as the computational backbone for robust, training-free multiview RGB-D registration. In the foundation stage, we directly recover metrically consistent global poses (without any pairwise estimation) by grounding the scale-ambiguous pose predictions of the foundation model against metric depth observations. In the refinement stage, we introduce an efficient voxelized spatial hashing mechanism that exploits the globally coherent 3D reconstruction (induced by the foundation model) as a shared spatial anchor, enabling dense multiview correspondences in near-linear time. On top of this, an IRLS-based robust motion-only bundle adjustment is performed using a conjugate gradient solver to jointly minimize the correspondence and reprojection residuals for multiview pose refinement. Extensive experiments on indoor/object-centric/outdoor datasets verify the outstanding zero-shot registration accuracy and computational efficiency of our proposed method.","authors":["Haobo Jiang","Liang Yu","Jianmin Zheng"],"published":"2026-10-08T09:54:56Z","updated":"2026-10-08T09:54:56Z","abstract_url":"https://arxiv.org/abs/2610.11612v1","html_url":"https://arxiv.org/html/2610.11612v1","pdf_url":"https://arxiv.org/pdf/2610.11612v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11610v1","title":"Beyond Report Imitation: Clinically Aware Multi-Image Ultrasound Report Generation from Visible Evidence","abstract":"Generating ultrasound reports from multiple images requires aggregating clinical evidence across views, yet archived key frames capture only part of the dynamic examination. Raw-report imitation is therefore misaligned with visual supervision: content that is clinically valid for the full examination may be unverifiable from the images available to a model. This gap creates a clinical behavior alignment problem. A model must preserve visible findings, avoid diagnostic reversals and unsupported completion, and not collapse into conservative templates. We propose CAMEO, a Clinically Aware Multi-image Evidence-grounded Orchestration framework for ultrasound report generation. Stage I learns ultrasound visual-language primitives; Stage II performs Cross-View Evidence Grounding by distilling trusted visible report points into multi-image QA and report-style supervision; and Stage III performs Clinically Aware Preference Alignment using clinical-error-oriented preference pairs. From USReport, we construct USReport-Distilled with 17,670 evidence-grounded paired-image training instances and USReport-Pref with 21,869 preference pairs; we additionally use 25,631 PubMedVision-US ultrasound instruction samples for domain adaptation and multi-image instruction tuning. On the primary USReport-Distilled benchmark, CAMEO improves over EchoVLM from 0.25 to 0.40 BLEU-1, 0.28 to 0.45 ROUGE-1, and 0.27 to 0.43 METEOR, while raising ClinicalScore from 55.02 to 74.20. These results underscore the value of evidence-grounded supervision, clinically aware alignment, and clinically structured evaluation for reliable ultrasound report generation.","authors":["Yuchen Yang","Xin Wang","Lufan Wang","Yinghong Pan","Yujuan Feng","Yuqing Yang"],"published":"2026-10-08T09:53:46Z","updated":"2026-10-08T09:53:46Z","abstract_url":"https://arxiv.org/abs/2610.11610v1","html_url":"https://arxiv.org/html/2610.11610v1","pdf_url":"https://arxiv.org/pdf/2610.11610v1.pdf","matched_keywords":["instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11608v1","title":"S$^3$Geo: Structure-Semantic Synergistic Learning for Cross-View Geo-Localization","abstract":"Cross-view geo-localization (CVGL) aims to estimate geographic locations by matching images captured from different viewpoints, such as drone and satellite views. Existing methods mainly rely on visual representations, but often fail to jointly model fine-grained structural correspondences and semantic priors, making them prone to confusion between visually similar but semantically different regions, and thus limiting robustness under large viewpoint variations. To address these challenges, we propose \\textbf{S$^3$Geo}, a structure-semantic synergistic learning framework for cross-view matching. Specifically, we first introduce a Decoupled Query Pooling (DQP) module to extract a compact set of region-aware features from dense tokens, enabling explicit modeling of local structural patterns. We then design a query-level contrastive learning scheme with an optimal transport (OT)-based formulation to establish soft correspondences under cross-view spatial misalignment. Furthermore, we incorporate a Semantic Knowledge Distillation (SKD) strategy from a frozen CLIP teacher to transfer semantic priors and relational structures, thereby improving discrimination on hard negatives. By operating synergistically, the semantic priors provide robust contextual filtering, which guides the structural module to establish precise spatial alignments. Experiments on the University-1652 and SUES-200 datasets demonstrate that \\textbf{S$^3$Geo} consistently outperforms state-of-the-art approaches without increasing inference complexity, validating the effectiveness of jointly modeling structural and semantic information for CVGL.","authors":["Ziqian Mo","Hill Zhang","Haosheng Tan","Ling Li","Jiaheng Wei"],"published":"2026-10-08T09:51:31Z","updated":"2026-10-08T09:51:31Z","abstract_url":"https://arxiv.org/abs/2610.11608v1","html_url":"https://arxiv.org/html/2610.11608v1","pdf_url":"https://arxiv.org/pdf/2610.11608v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11579v1","title":"SV-TAD: Native Sparse Convs for Efficient Temporal Action Detection","abstract":"To adapt billion-parameter Vision Transformers for long-video understanding, recent methods freeze the backbone and train lightweight convolutional modules. While effective for parameter-efficient training, existing adapters do not reduce inference-time computation, leaving scalability with respect to video length largely unaddressed. Token selection can reduce attention cost by pruning redundant tokens, but it breaks the spatial grid structure required by convolutional adapters. This forces an expensive dense reconstruction, nullifying much of the potential speedup. We address this by introducing native sparse 2D convolutions, a primitive that allows these adapters, for the first time, to operate directly and efficiently on dynamically pruned token sets. We integrate this primitive into SV-TAD, an adapter framework for temporal action detection, reducing VideoMAEv2-L computation by up to 64% and achieving 2.2x faster inference, while maintaining state-of-the-art accuracy on THUMOS-14 and ActivityNet-1.3. When scaled to InternVideoNext-L, our approach surpasses the previous state of the art at roughly half its computational cost. Moreover, the sparse formulation naturally supports auxiliary task tokens, which improves fine-grained assembly detection on ATTACH.","authors":["Ricardo Pizarro","Roberto Valle","José M. Buenaposada","Luis M. Bergasa","Luis Baumela"],"published":"2026-10-08T09:31:38Z","updated":"2026-10-08T09:31:38Z","abstract_url":"https://arxiv.org/abs/2610.11579v1","html_url":"https://arxiv.org/html/2610.11579v1","pdf_url":"https://arxiv.org/pdf/2610.11579v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11577v1","title":"CoCam4D: Geometry-Aware Cooperative 4D Perception for Camera-Only Autonomous Driving","abstract":"Autonomous vehicles often suffer from limited perception due to occlusions, blind spots, limited sensor range, and the complex nature of surrounding environments. Multi-agent collaborative perception (CP) addresses these challenges by allowing vehicles to share sensory information and reconstruct the scene cooperatively. However, camera-only perception remains fundamentally limited by the uncertainty of distance-dependent monocular depth estimation. We propose CoCam4D, a Bayesian framework for collaborative perception that explicitly models geometric uncertainty. It uses a VGGT-based feedforward network to generate 3D Gaussian scene representations with associated uncertainty estimates, enabling multiple vehicles or agents to efficiently combine their observations. By sharing compact Gaussian primitives, reliable observations from one agent can reduce the depth uncertainty of another without requiring LiDAR sensors. To support real-world deployment, we introduce Dynamic Object Primitives (DOPs), a compact 35-byte representation designed for efficient C-V2X communication. Extensive experiments show that our proposed method consistently outperforms recent vision-only methods, achieving improvements of 11.48% on OPV2V+ and 10.62% on DAIR-V2X-C, demonstrating the potential of geometrically grounded collaborative perception for LiDAR-free autonomous driving.","authors":["Soham Pahari","Sudip Das","Arindam Das","Ujjwal Bhattacharya"],"published":"2026-10-08T09:31:28Z","updated":"2026-10-08T09:31:28Z","abstract_url":"https://arxiv.org/abs/2610.11577v1","html_url":"https://arxiv.org/html/2610.11577v1","pdf_url":"https://arxiv.org/pdf/2610.11577v1.pdf","matched_keywords":["3d","agent","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11572v1","title":"PAM-ToD: Plug-and-Play Appearance Modeling for Cross-Time-of-Day 3D Gaussian Splatting","abstract":"Adapting a pre-trained 3D Gaussian Splatting (3DGS) road scene to a new time of day requires learning appearance changes from a few anchor images while preserving consistent, real-time rendering. We propose PAM-ToD, a lightweight plug-in that learns color corrections while keeping the pre-trained 3DGS parameters fixed. PAM-ToD scales each Gaussian's existing color to model illumination changes and uses an additive term for additional brightness, such as when street lamps turn on at night. Under a simplified image formation model, unchanged surface albedo can be eliminated from the relation between source and target appearances, allowing us to learn these corrections without separately estimating albedo and illumination. The model corrects colors across the scene while allowing the corrections to vary by location and by Gaussian. To guide learning from a few anchor images, it discourages abrupt spatial changes in these corrections. We also introduce CARLA-ToD, a benchmark with matching geometry, camera poses, and moving-object trajectories across three times of day. A few target-time anchor images are used to train each plug-in, while separate views are used for evaluation. Across the static and dynamic settings, PAM-ToD achieves higher PSNR and lower LPIPS than the baselines, even when the anchor images come from a single synchronized capture across multiple cameras.","authors":["Kota Shimomura","Sungho Moon","Tsubasa Hirakawa","Takayoshi Yamashita","Sunghoon Im","Hironobu Fujiyoshi"],"published":"2026-10-08T09:27:17Z","updated":"2026-10-08T09:27:17Z","abstract_url":"https://arxiv.org/abs/2610.11572v1","html_url":"https://arxiv.org/html/2610.11572v1","pdf_url":"https://arxiv.org/pdf/2610.11572v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"}],"favorites":[],"latest":{"generated_at_utc":"2026-10-09T07:04:58+00:00","category":"cs.CV","keywords":["video","retrieval","3d","agent","representation","instance","multimodal","diffusion"],"fetch_window_hours":72,"daily_window_hours":30,"match_count":80,"new_or_recent_papers":[{"id":"2610.12470v1","title":"Dex-One2Many: Learning Dexterous Manipulation from a Single Human Demonstration","abstract":"While learning dexterous manipulation from a single human video offers a promising alternative to costly robot demonstrations, many recent methods predominantly imitate demonstrated motions. Such strict motion matching often limits generalization to initial object poses, goal poses, and grasps not shown in the video. Alternatively, discovering a policy via reinforcement learning (RL) allows for broad generalization, but without prior guidance, it struggles with high-dimensional exploration in complex, multi-stage tasks. To address these coupled generalization and exploration challenges, we present Dex-One2Many, a real-to-sim-to-real framework that learns a generalizable dexterous manipulation policy from a single human video. Our key insight is to abstract the video into sequential scene graphs that guide RL, enabling efficient exploration while preserving broad generalizability. The graphs serve as generative constraints for sampling diverse reset states and provide dense rewards for each stage. Because the graphs constrain relations rather than exact poses, these reset states cover object poses and grasps beyond the video, while initializing each stage from them with dense rewards keeps exploration short and guided. Trained entirely in simulation, Dex-One2Many transfers zero-shot to a real multi-fingered hand. Across five tool-use and manipulation tasks, Dex-One2Many exceeds baselines by 6.5% in seen configurations, while its robust generalization widens this gap to 71% in unseen scenarios.","authors":["Jusuk Lee","Sungha Kim","Yeonsoo Park","Jonguk Cheon","Yoonkyo Jung","Yongjun You","H. Jin Kim","Jia-Bin Huang","Furong Huang","Youngseok Jang","Seungjae Lee"],"published":"2026-10-08T17:59:58Z","updated":"2026-10-08T17:59:58Z","abstract_url":"https://arxiv.org/abs/2610.12470v1","html_url":"https://arxiv.org/html/2610.12470v1","pdf_url":"https://arxiv.org/pdf/2610.12470v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":117436,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：While learning dexterous manipulation from a single human video offers a promising alternative to costly robot demonstrations, many recent methods predominantly imitate demonstrated motions. Such strict motion matching often limits generalization to initial o...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:13+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12469v1","title":"Rubric-CEPR: Self-Evolving Image Editing via Reward-Verified Self-Distillation","abstract":"Instruction-guided image editors have become highly capable, yet improving them further still depends on human-edited training pairs or external reward models. Such supervision is costly to obtain and can reward plausible failures: a realistic output may leave the requested change undone or alter content that should be preserved. In this work, we strive to improve a pretrained image editor using only its own generations, without human-edited targets or an external training-time reward model. To this end, we propose a self-evolving framework, named Rubric-CEPR, that verifies the editor's own samples with its internal representations through a rubric-augmented Contrastive Edit-Preservation Reward (CEPR). A Planner proposes structured edit instructions from unlabeled images, the Editor samples multiple candidate edits, and a frozen Critic scores each candidate with decomposed rubric checks for edit realization, removal of the old state, and content preservation, using features already exposed by the editor. Non-compensatory gates reject infeasible candidates, and the best verified candidate is distilled into the editor through lightweight adapter training. On Qwen-Image-Edit, Rubric-CEPR improves ImgEdit from 4.36 to 4.60 (+5.5%), with a +24.9% gain on object isolation, and transfers to GEdit-Bench and Complex-Edit. The same procedure also improves Step1X-Edit by +7.8% on ImgEdit. We hope our approach will serve as a solid baseline for image editors that improve themselves from their own verified samples. Our code is publicly available at $\\href{https://riteshthawkar.github.io/Rubric-CEPR/}{\\text{this URL}}$","authors":["Ritesh Thawkar","Shubham Patle","Shravan Venkatraman","Rao Muhammad Anwer"],"published":"2026-10-08T17:59:58Z","updated":"2026-10-08T17:59:58Z","abstract_url":"https://arxiv.org/abs/2610.12469v1","html_url":"https://arxiv.org/html/2610.12469v1","pdf_url":"https://arxiv.org/pdf/2610.12469v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":88183,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Instruction-guided image editors have become highly capable, yet improving them further still depends on human-edited training pairs or external reward models. Such supervision is costly to obtain and can reward plausible failures: a realistic output may leav...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:13+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12468v1","title":"DreamTrue: Action-Faithful Robot World Model with Counterfactual Post-Training","abstract":"We present DreamTrue, a multi-view, cross-embodiment robot world model for action-faithful and physically plausible video prediction. Training such a model on existing robot datasets faces two obstacles: imprecise calibration can impair action following, while limited coverage of unsuccessful interactions can bias predictions toward successful outcomes. To improve action following across embodiments, we render action trajectories into image-space conditions and introduce offline geometric calibration to align these conditions with the target videos. To broaden interaction coverage, we introduce counterfactual post-training, modifying recorded action trajectories and generating future videos under a wider range of actions and contact configurations. To provide feedback on these predictions without paired ground-truth futures, we construct a human-annotated video dataset covering robot, object, and interaction defects and use it to train an embodied video reward model. Its scores guide reinforcement-learning post-training toward more physically plausible interaction outcomes. On AgiBot, DreamTrue attains state-of-the-art action following, while reducing the human-assessed interaction defect rate from from 48.12% to 6.25%. Notably, our model ranks first in the world model track of the AgiBot World Challenge 2026. The project page can be found at https://brave-eai.github.io/DreamTrue.","authors":["Junyan Li","Ruizhi Li","Yu Liu","Xiangshuo Liu","Mingchao Sun","Hongyu Pan","Mu Xu","Lue Fan","Zhaoxiang Zhang"],"published":"2026-10-08T17:59:51Z","updated":"2026-10-08T17:59:51Z","abstract_url":"https://arxiv.org/abs/2610.12468v1","html_url":"https://arxiv.org/html/2610.12468v1","pdf_url":"https://arxiv.org/pdf/2610.12468v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":77791,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：We present DreamTrue, a multi-view, cross-embodiment robot world model for action-faithful and physically plausible video prediction. Training such a model on existing robot datasets faces two obstacles: imprecise calibration can impair action following, whil...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:13+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12464v1","title":"What 30,000 Hours of Ego-centric Video Does Not Teach","abstract":"World models offer a promising alternative to physics-based simulators, yet remain far from practical deployment. We ask how far scaling ego-centric human video takes them, using a dataset of 30,000 hours spanning over 1,000 scene types and 14,000 contributors. Rather than relying on opaque downstream metrics, we directly evaluate agent and object-interaction fidelity on a challenging out-of-distribution benchmark. Increasing training data by 100x improves both, but unevenly: the agent is modeled well, while object fidelity remains far lower and improves slowly. We show that the agent gains need not come from data, and a careful visual conditioning design saturates fidelity with a fraction of it, which lets us measure object fidelity on its own and discover its saturation point. We then introduce a supervision scheme that shifts capacity from scene appearance toward object dynamics, improving object fidelity though a substantial gap remains. Finally, our conclusions transfer to downstream humanoid modeling. Overall, our results suggest that scaling ego-centric data brings agent modeling close to its limit while leaving its effects on the world far behind, and that closing this gap will depend on how models are trained, not only on how much data they see.","authors":["Jiahua Dong","Anurag Bagchi","Yash Jangir","Muhammad Zubair Irshad","Sergey Zakharov","Martial Hebert","Homanga Bharadhwaj","Yu-Xiong Wang","Vitor Campagnolo Guizilini","Pavel Tokmakov"],"published":"2026-10-08T17:59:49Z","updated":"2026-10-08T17:59:49Z","abstract_url":"https://arxiv.org/abs/2610.12464v1","html_url":"https://arxiv.org/html/2610.12464v1","pdf_url":"https://arxiv.org/pdf/2610.12464v1.pdf","matched_keywords":["video","agent"],"source_used":"html","source_text_chars":85483,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, agent 相关；摘要显示其主要贡献为：World models offer a promising alternative to physics-based simulators, yet remain far from practical deployment. We ask how far scaling ego-centric human video takes them, using a dataset of 30,000 hours spanning over 1,000 scene types and 14,000 contributor...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:13+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12461v1","title":"OuroWorld: Bringing Any 3D World Alive as Diverse, Endlessly Looping 3D Cinemagraphs","abstract":"Recent 3D world models generate photorealistic, explorable scenes that remain frozen in time. OuroWorld is a mask-free framework that turns any static 3D Gaussian Splatting scene into a 3D cinemagraph: a dynamic scene with vivid, diverse motion looping seamlessly from any viewpoint. A vision-language model infers plausible dynamics and guides a video model to synthesize a reference video, which we lift and complete into multi-view videos. To learn from this imperfect supervision, we propose Inconsistency-Robust Periodic 4DGS: a Fourier-series deformation field guarantees looping by construction, while a Grounded Drift Field anchored at the reference view absorbs cross-view inconsistency. Unlike prior Eulerian methods limited to fluid-like motion, we capture general deformation, object motion, and illumination change. We introduce a ground-truth-free evaluation covering vividness, naturalness, loop seam coherence, and scene quality. On 39 reconstructed and generated scenes, OuroWorld outperforms all baselines and wins 70.8%-99.0% of user-study comparisons. Project page: https://ouroworld.userwei.com","authors":["You-Zhe Xie","Ting-Wei Chou","Yu-Hsuan Li","Kaipeng Zhang","Zhixiang Wang","Yu-Lun Liu"],"published":"2026-10-08T17:59:46Z","updated":"2026-10-08T17:59:46Z","abstract_url":"https://arxiv.org/abs/2610.12461v1","html_url":"https://arxiv.org/html/2610.12461v1","pdf_url":"https://arxiv.org/pdf/2610.12461v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":96188,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：Recent 3D world models generate photorealistic, explorable scenes that remain frozen in time. OuroWorld is a mask-free framework that turns any static 3D Gaussian Splatting scene into a 3D cinemagraph: a dynamic scene with vivid, diverse motion looping seamle...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:13+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12459v1","title":"WorldGuide: Goal-Directed Video World Model for Procedural Task Execution","abstract":"Video generators and video-based world models can synthesize plausible visual trajectories, but long-horizon procedural tasks require generation to adapt to what has actually been produced. A model must determine the next action from its generated state, execute that action, and recognize when the task is complete. Open-loop generation cannot adapt to execution outcomes, while existing closed-loop systems often rely on pretrained executors or indirect verification. This leaves a gap between deciding an action and successfully realizing it. We formulate procedural video generation as \\emph{closed-loop task execution in visual world space} and introduce \\textbf{WorldGuide}. Given only an initial image and a task goal, WorldGuide predicts an atomic action, generates its corresponding video clip, and uses the generated result to select the next action or terminate. The Planner and Executor are trained on the same step-level procedural demonstrations: the Planner learns to predict the next atomic action or task completion from visual progress, while the Executor is directly trained to realize the predicted actions. Hierarchical visual memory maintains state across long-horizon execution with bounded history token cost. Due to the lack of step-level action-video supervision for joint planner-executor training, we introduce \\textbf{WorldGuide Bench}: approximately 59K step-annotated videos across 245 tasks and 27 procedural categories. WorldGuide achieves a 33.33\\% Task Success on \\textbf{WorldGuide-Bench}, compared with 29.90\\% for the strong recent video model MiniMax-H3, even though MiniMax-H3 receives reference action plans, and achieves 47.69\\% on \\textbf{VideoCraft-Bench} compared with 32.73\\% for MiniMax-H3 under goal-only conditioning. These results demonstrate the importance of coupling planning with learned execution for goal-directed procedural video generation.","authors":["Ankan Deria","Komal Kumar","Hisham Cholakkal","Fahad Shahbaz Khan","Salman Khan"],"published":"2026-10-08T17:59:31Z","updated":"2026-10-08T17:59:31Z","abstract_url":"https://arxiv.org/abs/2610.12459v1","html_url":"https://arxiv.org/html/2610.12459v1","pdf_url":"https://arxiv.org/pdf/2610.12459v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":104055,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Video generators and video-based world models can synthesize plausible visual trajectories, but long-horizon procedural tasks require generation to adapt to what has actually been produced. A model must determine the next action from its generated state, exec...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:13+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12458v1","title":"OmniCapBench: A Deep-Structured Evaluation Framework for Fine-Grained Audio-Visual Captioning","abstract":"Multimodal large language models (MLLMs) are rapidly evolving toward continuous audio--visual reasoning, creating an urgent need for evaluations that expose their capability limits. Audio--visual captioning is an ideal diagnostic task, yet current benchmarks face a coupled trade-off: whole-caption scores provide coverage without localization, local probes provide localization without coverage, and unconstrained LLM judges introduce instability. We introduce OmniCapBench (Omni-Video Caption Benchmark), a benchmark that reframes audio--visual caption evaluation as a deep-structured diagnostic framework. OmniCapBench shifts the prediction target from free-form text to sets of atomic, verifiable evaluation units across three tracks: entity references, visual shots, and audio events, enabling reliable scoring with deterministic constraint checks and localized LLM-based semantic comparisons. With 786 densely annotated videos, OmniCapBench effectively distinguishes MLLM perception errors, including temporal grounding failures, identity drift, cross-modal misalignment, and hallucinated descriptions. Evaluating frontier MLLMs reveals strong local perception but weak long-horizon audio--visual reasoning, particularly in identity drift and cross-modal misalignment, providing a fine-grained roadmap for omnimodal development.","authors":["Zhongyu Yang","Jiale Tao","Ruitao Chen","Zuhao Yang","Yingfang Yuan","Xueliang Zhao","Auden","Kai Wang","Shuai Shao","Biao Wang","Steve Yves","Qinglin Lu"],"published":"2026-10-08T17:59:21Z","updated":"2026-10-08T17:59:21Z","abstract_url":"https://arxiv.org/abs/2610.12458v1","html_url":"https://arxiv.org/html/2610.12458v1","pdf_url":"https://arxiv.org/pdf/2610.12458v1.pdf","matched_keywords":["video","multimodal"],"source_used":"html","source_text_chars":162422,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, multimodal 相关；摘要显示其主要贡献为：Multimodal large language models (MLLMs) are rapidly evolving toward continuous audio--visual reasoning, creating an urgent need for evaluations that expose their capability limits. Audio--visual captioning is an ideal diagnostic task, yet current benchmarks...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:13+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12455v1","title":"Hybrid Cinematography: Previsualizing and Managing Hallucination Risk in Generative Video Reshooting","abstract":"On a film set, the camera move is committed during a take. Generative video reshooting lets filmmakers change it afterward, but may require hallucinating unrecorded content, a gap sometimes discovered only after leaving the set. We present Hybrid Cinematography, a workflow that bridges physical capture and generative reshooting to manage hallucination risk while filmmakers can still act on it. Using an editable 3D shot plan and a proxy of the take, our previsualization evaluates hallucination risk in real time. Seeing where the take lacks support, filmmakers can iteratively adjust the plan, explore moves that balance capture and generation, shoot guided pickups, or knowingly accept hallucination. We demonstrate the workflow through a mobile augmented reality application for on-set planning, capture, and review, and an offline pipeline for existing video. A study with experienced filmmakers reveals how previsualizing risk informs camera decisions and exposes tensions between creative intent and generative hallucination.","authors":["Nhan","Tran","Neal Wadhwa","Abe Davis","Stefan Stojanov"],"published":"2026-10-08T17:59:11Z","updated":"2026-10-08T17:59:11Z","abstract_url":"https://arxiv.org/abs/2610.12455v1","html_url":"https://arxiv.org/html/2610.12455v1","pdf_url":"https://arxiv.org/pdf/2610.12455v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":93360,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：On a film set, the camera move is committed during a take. Generative video reshooting lets filmmakers change it afterward, but may require hallucinating unrecorded content, a gap sometimes discovered only after leaving the set. We present Hybrid Cinematograp...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12452v1","title":"BrickBench: Evaluating Agentic Brick Design","abstract":"We propose BrickBench, a benchmark for agentic text-conditioned LEGO-set design. Given a prompt, an agent is tasked with producing an assembly that not only satisfies semantic and design criteria, but that can also be physically built. To do so, it must select parts from a discrete library and reason jointly about local and global constraints. We score validity, alignment, and design across three settings that vary in scale and part availability. We provide BrickAgent, an environment for coding agents to construct, inspect, and validate their designs. We find that leading agents largely satisfy verifiable physical and semantic requirements, but fall short of human designs. We release our benchmark and environment at http://www.brickben.ch","authors":["Peter Kulits","Yiqing Xu","R. Kenny Jones","Cordelia Schmid","Jiajun Wu"],"published":"2026-10-08T17:58:56Z","updated":"2026-10-08T17:58:56Z","abstract_url":"https://arxiv.org/abs/2610.12452v1","html_url":"https://arxiv.org/html/2610.12452v1","pdf_url":"https://arxiv.org/pdf/2610.12452v1.pdf","matched_keywords":["agent"],"source_used":"html","source_text_chars":58401,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent 相关；摘要显示其主要贡献为：We propose BrickBench, a benchmark for agentic text-conditioned LEGO-set design. Given a prompt, an agent is tasked with producing an assembly that not only satisfies semantic and design criteria, but that can also be physically built. To do so, it must selec...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12451v1","title":"VersaCamVLA: Camera-Configurable VLA Policies for Robotic Manipulation","abstract":"Vision-Language-Action (VLA) models have emerged as powerful foundations for robotic manipulation, but their reliance on fixed camera configurations during training makes them brittle to changes in camera count or pose during deployment. To overcome these limitations, we propose VersaCamVLA, a camera-configurable framework that decouples camera-set representation from action learning. VersaCamVLA learns a unified scene-token interface that maps an arbitrary, variable set of posed RGB views into fixed-size latent scene tokens. This is achieved via multi-signal target-view prediction and Wrist-Augmented Pose Sampling (WAPS), which leverages natural wrist-camera motion for free pose diversity. At deployment, a lightweight spatial encoder injects these compact scene tokens into a pretrained base VLA as a supplementary visual condition, requiring no explicit 3D sensing or novel-view rendering. Experiments on RoboTwin, LIBERO, and a real-robot platform demonstrate that VersaCamVLA consistently outperforms prior VLA methods and direct multi-view baselines, maintaining robust performance across varying camera counts and unseen camera poses.","authors":["Boyao Han","Chen Shi","Jingjing Qian","ZhuoTan Tian","Li Jiang"],"published":"2026-10-08T17:58:47Z","updated":"2026-10-08T17:58:47Z","abstract_url":"https://arxiv.org/abs/2610.12451v1","html_url":"https://arxiv.org/html/2610.12451v1","pdf_url":"https://arxiv.org/pdf/2610.12451v1.pdf","matched_keywords":["3d","representation"],"source_used":"html","source_text_chars":79426,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation 相关；摘要显示其主要贡献为：Vision-Language-Action (VLA) models have emerged as powerful foundations for robotic manipulation, but their reliance on fixed camera configurations during training makes them brittle to changes in camera count or pose during deployment. To overcome these lim...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12442v1","title":"LEGO: A Lifting-Free Approach for Exocentric-to-Egocentric Video Generation","abstract":"Generating an egocentric video from a single exocentric recording is a challenging case of novel view synthesis, as the two cameras share little overlap and much of the target view is unobserved. Current state-of-the-art methods reconstruct the scene explicitly by estimating depth, lifting the video into a point cloud, and re-rendering it from the egocentric camera to condition a video diffusion model. This deterministic mapping assigns each pixel to a single reprojected location, which preserves texture but translates depth errors into misplaced content. We ask what a video diffusion model should receive as its condition and propose a lifting-free answer: a learned view synthesizer, an LVSM-style transformer fine-tuned to render the egocentric view directly without depth, point clouds, or reprojection, resolving cross-view correspondence internally. In contrast, its probabilistic mapping averages each region over candidate source locations according to a learned correspondence distribution, preserving structure while fine texture is averaged away. We argue that this trade-off suits a diffusion generator, whose denoising training excels at restoring detail, so an effective condition should prioritize structural alignment over sharpness. This distribution's concentration also yields a per-region confidence, used both to mask low-confidence regions and to guide the generator toward high-confidence areas during early layout-forming denoising steps. Our approach consistently outperforms the state-of-the-art explicit pipeline and generalizes to other datasets without retraining. The synthesizer thus supplies view structure, and the diffusion model its detail.","authors":["Suhwan Cho","Yonwoo Choi","Soongjin Kim","Jicheol Park","Taegyu Lim"],"published":"2026-10-08T17:58:03Z","updated":"2026-10-08T17:58:03Z","abstract_url":"https://arxiv.org/abs/2610.12442v1","html_url":"https://arxiv.org/html/2610.12442v1","pdf_url":"https://arxiv.org/pdf/2610.12442v1.pdf","matched_keywords":["video","diffusion"],"source_used":"html","source_text_chars":74874,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, diffusion 相关；摘要显示其主要贡献为：Generating an egocentric video from a single exocentric recording is a challenging case of novel view synthesis, as the two cameras share little overlap and much of the target view is unobserved. Current state-of-the-art methods reconstruct the scene explicit...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12427v1","title":"FastBench: Can Streaming VLMs Perceive High-Dynamic Real-World Streams?","abstract":"Streaming Video Large Language Models (VLMs) enable continuous video understanding, yet existing benchmarks focus on low-dynamic scenarios. Under bounded context budgets, models must balance temporal history, spatial resolution, and temporal granularity; sparse sampling at 1--2 FPS misses fast events. We introduce FastBench to evaluate high-dynamic perception in real-world video streams. Its trajectory-grounded pipeline combines QA generation from high-FPS clips, filtering of questions answerable at 2 FPS, answer verification using SAM3 and CoTracker3 trajectories, and three rounds of human inspection. FastBench contains 306 QA pairs across eight domains, six capabilities, and forward, instant, and backward temporal scopes, with human-annotated evidence intervals. We also present ProactiveFrame, a training-free baseline that adjusts incoming frame rates through text tokens. A dual-tier sliding window retains recent high-FPS observations while downsampling older ones into sparse history. Experiments reveal substantial limitations: the strongest model, Gemini-3.5-Flash, scores only 50.7%. Denser sampling improves Qwen3-VL-8B from 32.9% at 2 FPS to 44.6% at 24 FPS, but gains saturate as history is compressed. ProactiveFrame outperforms sparse uniform sampling by 5.4 and 1.5 percentage points, yet remains well below oracle-guided focusing, showing that current VLMs struggle to determine from the stream alone when finer temporal perception is needed. FastBench provides a testbed for high-dynamic streaming video understanding. Code and data: https://github.com/Ashone3/FastBench.","authors":["Yuxuan Hu","Weikang Shi","Yang Bo","Xudong Lu","Xintong Guo","Shuhan Li","Yuyang He","Huankang Guan","Peiwen Sun","Yunqiao Yang","Wenbo Li","Rui Liu","Hongsheng Li"],"published":"2026-10-08T17:55:20Z","updated":"2026-10-08T17:55:20Z","abstract_url":"https://arxiv.org/abs/2610.12427v1","html_url":"https://arxiv.org/html/2610.12427v1","pdf_url":"https://arxiv.org/pdf/2610.12427v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":58579,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Streaming Video Large Language Models (VLMs) enable continuous video understanding, yet existing benchmarks focus on low-dynamic scenarios. Under bounded context budgets, models must balance temporal history, spatial resolution, and temporal granularity; spar...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12423v1","title":"Pumpire: Unified Benchmark for Metric Distance Estimation","abstract":"We present Pumpire, a unified benchmark for evaluating metric point-pair distance estimation capability of both image- and video-level 3D foundation models, with or without depth priors. In contrast to previous approaches that normally evaluate depth and camera intrinsics separately or evaluate point-clouds with geometric similarity metrics, which cannot directly reflect models' point-to-point distance estimation capability, Pumpire directly assesses point-to-point distances from the reconstructed geometry. To this end, we collect a large-scale and diverse dataset (pumpire-6k) comprising 100 real-world scenes, each annotated with physically measured point-pair distances and containing 64 frames, for a total of 6,400 frames. Building on this dataset, we establish a holistic evaluation protocol that covers both image- and video-level 3D foundation models and enables direct assessment of point-pair distance errors and cross-setting comparison. We conduct extensive experiments across 29 baseline configurations of representative 3D foundation models and provide a comprehensive analysis of the results. By offering this benchmark, we target the more fundamental ability to perceive and estimate physical scale in the reconstructed 3D space, which prior evaluation protocols have largely overlooked. The project page can be found at https://pumpire.github.io/","authors":["Siyu Chen","Zehan Wang","Jiayang Xu","Yihan Wu","Jialei Wang","Junming Chen","Ziang Zhang","Yutong Ying","Zhou Zhao"],"published":"2026-10-08T17:55:11Z","updated":"2026-10-08T17:55:11Z","abstract_url":"https://arxiv.org/abs/2610.12423v1","html_url":"https://arxiv.org/html/2610.12423v1","pdf_url":"https://arxiv.org/pdf/2610.12423v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":67052,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：We present Pumpire, a unified benchmark for evaluating metric point-pair distance estimation capability of both image- and video-level 3D foundation models, with or without depth priors. In contrast to previous approaches that normally evaluate depth and came...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12421v1","title":"Beyond Spatio-Temporal Priors: A Generalizable Approach for Dense Correspondence Matching","abstract":"Dense correspondence matching has historically been bounded by simplifying spatio-temporal priors, such as smooth motion and rigid geometry. While effective for classical tasks, these assumptions break down in image editing and reference-guided generation (IEG), where transformations can preserve visual identity while breaking physical continuity. To establish identity-preserving correspondence across such transformations, we introduce FreeMatching, a generalizable framework combining generative and semantic foundation representations with heterogeneous supervision from classical datasets, tracked videos, and synthetic scenes. Teacher-guided iterative refinement further improves correspondence in IEG without dense correspondence annotations. Experimentally, a single FreeMatching model substantially improves correspondence quality on challenging IEG image pairs while retaining competitive performance on classical benchmarks. Furthermore, we demonstrate its utility as a quantitative metric for evaluating identity preservation, with scores that correlate with human judgment. The code is available at https://github.com/luping-liu/FreeMatching.","authors":["Luping Liu","Bingyi Kang","Yifan Wang","Dong Xu"],"published":"2026-10-08T17:53:04Z","updated":"2026-10-08T17:53:04Z","abstract_url":"https://arxiv.org/abs/2610.12421v1","html_url":"https://arxiv.org/html/2610.12421v1","pdf_url":"https://arxiv.org/pdf/2610.12421v1.pdf","matched_keywords":["video","representation"],"source_used":"html","source_text_chars":80464,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, representation 相关；摘要显示其主要贡献为：Dense correspondence matching has historically been bounded by simplifying spatio-temporal priors, such as smooth motion and rigid geometry. While effective for classical tasks, these assumptions break down in image editing and reference-guided generation (IE...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12419v1","title":"OneSearch-VL: Unified Multimodal Deep Research Agent for Image and Video","abstract":"Single-image, multi-image, and video deep research require different visual operations but share a workflow of visual grounding, external retrieval, and fact composition. A key challenge is to preserve the dependencies linking localized visual anchors, entity relations, source-supported facts, and answer-producing operations. We introduce OneSearch-VL, a unified agent centered on the Visually Grounded Evidence Graph (VGEG), which encodes these dependencies as a shared task-level reference for data construction, process supervision, and operation-level evaluation. Our VGEG-based data engine constructs and verifies multi-image and video questions and filters expert trajectories. Using these data, we assemble OneSearch-VL-SFT-110K and OneSearch-VL-RL-10K for SFT and RL, respectively. We further derive the Evidence-aware Visual-Grounded Rubric reward (EVGR) from VGEG annotations to supervise evidence traceability and visual grounding during RL. For fine-grained evaluation, we construct OneSearch-MI-Bench and OneSearch-Video-Bench, organizing questions by the research operations encoded in their VGEGs. Experiments show that OneSearch-VL-8B improves over Qwen3-VL-8B with tool access by 20.2 and 17.6 percentage points on the two new benchmarks, respectively, while also achieving substantial gains across 7 image benchmarks and VideoDR. Project repository: https://github.com/appletea233/OneSearch-VL","authors":["Hongyu Li","Manyuan Zhang","Kaituo Feng","Shu Chen","Dian Zheng","Hao Li","Hao Yu","Zhangquan Chen","Zoey Guo","Ray Zhang","Shaofei Huang","Tianrui Hui","Linjiang Huang","Si Liu"],"published":"2026-10-08T17:52:46Z","updated":"2026-10-08T17:52:46Z","abstract_url":"https://arxiv.org/abs/2610.12419v1","html_url":"https://arxiv.org/html/2610.12419v1","pdf_url":"https://arxiv.org/pdf/2610.12419v1.pdf","matched_keywords":["video","retrieval","agent","multimodal"],"source_used":"html","source_text_chars":94953,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, retrieval, agent, multimodal 相关；摘要显示其主要贡献为：Single-image, multi-image, and video deep research require different visual operations but share a workflow of visual grounding, external retrieval, and fact composition. A key challenge is to preserve the dependencies linking localized visual anchors, entity...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12417v1","title":"WOVEN: Weaving Visual World Modeling into Multimodal LLMs","abstract":"Multimodal large language models (MLLMs) struggle with spatial, embodied, physical, and temporal reasoning. We hypothesize that these failures reflect a shared deficit in visual transition reasoning, and test whether this capability can serve as a shared training primitive, one that different models can learn from different supervision sources and reuse across different tasks, with a systematic training recipe. Existing benchmarks document these deficits separately but do not support controlled comparisons across scenes, actions, and reasoning operations. We therefore introduce WOVEN, a training source and benchmark for visual transition reasoning that organizes transition supervision by scene, action, and reasoning type, using diverse, realistic rollouts from video-pretrained generative models: 36,076 examples across 20 scene types, 5 action types, and 8 reasoning types. We first evaluate 38 frontier MLLMs (e.g., GPT-5.4 and Qwen3-VL-235B-A22B) and find a substantial and systematic deficit: even the strongest models fall far below humans, and the failures recur across model families and persist with scale. We then train MLLMs at multiple scales on WOVEN and find that they learn a shared capability that transfers broadly: training subsets of only about 2,000 items each collectively improve 22 of 26 external benchmarks by up to 27.3 percentage points, and WOVEN data can replace 30-50% of a task's own training data with comparable accuracy. Controlled comparisons further yield a training recipe for visual world modeling, validated prospectively on held-out benchmarks: select supervision by the reasoning operation it teaches rather than by the actions, scenes, or domains it shows, and prefer larger changes to the visual state for robustness. Our work establishes visual transition reasoning as a reusable foundation for systematic visual world-model training in MLLMs.","authors":["Zheyu Fan","Yue Zhang","Mingkai Deng","Kangrui Wang","Qineng Wang","Canyu Chen","Jie Hao","Xing Fan","Chenlei Guo","Eric P. Xing","Mohit Bansal","Manling Li"],"published":"2026-10-08T17:52:03Z","updated":"2026-10-08T17:52:03Z","abstract_url":"https://arxiv.org/abs/2610.12417v1","html_url":"https://arxiv.org/html/2610.12417v1","pdf_url":"https://arxiv.org/pdf/2610.12417v1.pdf","matched_keywords":["video","multimodal"],"source_used":"html","source_text_chars":322988,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, multimodal 相关；摘要显示其主要贡献为：Multimodal large language models (MLLMs) struggle with spatial, embodied, physical, and temporal reasoning. We hypothesize that these failures reflect a shared deficit in visual transition reasoning, and test whether this capability can serve as a shared trai...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12416v1","title":"MAMHOI: Factorizing Scene-Aware Human-Object Interaction through Affordances","abstract":"Generating realistic human-object interactions (HOI) in complex 3D scenes requires two complementary capabilities: reasoning about interaction feasibility in the environment and synthesizing realistic human-object motion. However, supervision for these capabilities is rarely available jointly at scale. Human-scene datasets provide rich information about environment-aware motion, while human-object datasets capture detailed interaction dynamics, yet paired human-object-scene data remain scarce. We present MAMHOI, an affordance-mediated factorization for scene-aware human-object interaction generation. MAMHOI factorizes scene-aware HOI generation through an explicit motion-affordance interface between scene understanding and motion synthesis: a scene-conditioned model first predicts where and how an interaction can be feasibly executed, and an affordance-conditioned HOI model then generates the corresponding human-object motion. This factorization allows scene understanding and interaction dynamics to be learned from complementary sources of supervision without requiring paired human-object-scene data. Experiments in complex indoor environments show that MAMHOI reduces object--scene penetration while better preserving human--object interaction quality, yielding more realistic and physically feasible scene-aware interactions. Project page: https://leimingyuan.github.io/MAMHOI-project-page/","authors":["Mingyuan Lei","Yoonchang Sung","Tat-Jen Cham"],"published":"2026-10-08T17:52:02Z","updated":"2026-10-08T17:52:02Z","abstract_url":"https://arxiv.org/abs/2610.12416v1","html_url":"https://arxiv.org/html/2610.12416v1","pdf_url":"https://arxiv.org/pdf/2610.12416v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":85427,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Generating realistic human-object interactions (HOI) in complex 3D scenes requires two complementary capabilities: reasoning about interaction feasibility in the environment and synthesizing realistic human-object motion. However, supervision for these capabi...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12412v1","title":"WorldCast: Distributed Multiplayer World Models","abstract":"Multiplayer world models must generate independently controlled views with consistent representations of both players and their shared environment. Most existing approaches coordinate multiple players through joint multi-view generation, whose cost grows with each additional player. We present WorldCast, a distributed multiplayer world model in which each player runs a local client comprising a video generator and a state model. Using recorded player positions and map geometry during training, the state model estimates the player's position from generated video and control inputs. Clients exchange player states and project them into camera-aligned player state fields that guide where and how other players are rendered. Shared scene state enables clients to reuse one another's generated observations to maintain consistent scene appearance across views. Experiments on Counter-Strike 2 demonstrate WorldCast's consistency, real-time performance, and distributed scalability. The camera-aligned player state field improves player rendering rates by over an order of magnitude over joint-generation methods, while shared scene state improves visual consistency over whole rounds. Each client runs in real time and exchanges only player and scene states, enabling scalable multiplayer generation without a centralized computational bottleneck. Image quality remains stable over hour-long rollouts.","authors":["Ziyang Ye","Junchao Huang","Evelyn Zhang","Zhihao Xie","Ruicheng Zhang","Boyao Han","Litao Ban","Ziye Wang","Xinting Hu","Shaoshuai Shi","Zhuotao Tian","Li Jiang"],"published":"2026-10-08T17:49:44Z","updated":"2026-10-08T17:49:44Z","abstract_url":"https://arxiv.org/abs/2610.12412v1","html_url":"https://arxiv.org/html/2610.12412v1","pdf_url":"https://arxiv.org/pdf/2610.12412v1.pdf","matched_keywords":["video","representation"],"source_used":"html","source_text_chars":110593,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, representation 相关；摘要显示其主要贡献为：Multiplayer world models must generate independently controlled views with consistent representations of both players and their shared environment. Most existing approaches coordinate multiple players through joint multi-view generation, whose cost grows with...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:14+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12407v1","title":"LeWAM: A JEPA World Action Model with Diffusion-Steering-Based MPC","abstract":"World action models (WAMs) predict actions and future observations, typically from a reconstruction-based representation that carries noisy, redundant information which can complicate downstream predictions. We introduce LeWAM, a bidirectional transformer for forward, backward, inverse dynamics and policy prediction, on a decoder-free JEPA latent trained end-to-end through all four modes. We see the following benefits: 1) Alignment: linear probes read robot and object state from LeWAM's latent better than from a regular Le World Model (a forward-only JEPA world model), while the latent ignores visual distractors as well as LeWM does and far better than a reconstruction-based WAM. 2) Acting: Closed-loop evaluations of LeWAM match a regular flow-matching policy trained on the same encoder at matched size, while also providing a world model. 3) Planning: Sampling raw actions when planning with WAMs lets MPC exploit dynamics-model inaccuracies; planning in the noise space of the policy head instead improves the closed-loop performance of these WAMs.","authors":["Shashank Hegde","Alexander Popov","Elie Aljalbout","Nikolai Smolyanskiy"],"published":"2026-10-08T17:46:03Z","updated":"2026-10-08T17:46:03Z","abstract_url":"https://arxiv.org/abs/2610.12407v1","html_url":"https://arxiv.org/html/2610.12407v1","pdf_url":"https://arxiv.org/pdf/2610.12407v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"html","source_text_chars":46700,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, diffusion 相关；摘要显示其主要贡献为：World action models (WAMs) predict actions and future observations, typically from a reconstruction-based representation that carries noisy, redundant information which can complicate downstream predictions. We introduce LeWAM, a bidirectional transformer for...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:15+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12403v1","title":"ViSkill: Reinforcing VLM Agents with Evolving Visual-Native Skills","abstract":"Skill-augmented agents improve sample efficiency by distilling successful trajectories into reusable strategies. Yet most existing approaches remain text-centric, linearizing spatial layouts and action-state correspondences into language that loses critical geometric structure. Recent efforts have begun incorporating visual evidence, but construct and update skills separately from policy optimization, leaving their mutual improvement underexplored. We propose ViSkill, a visual-native skill learning framework that encodes successful interactions as composite visual skill cards directly accessible to VLM agents. Retrieved skills guide both inference and reward shaping, while successful trajectories are distilled back into the library, forming a closed feedback loop in which skill accumulation and policy improvement reinforce each other. An optional cold-start mechanism further accelerates early-stage learning. Evaluated on Sokoban, FrozenLake, and PrimitiveSkill, ViSkill achieves an overall success rate of 0.89, rising to 0.91 with cold-start initialization, outperforming all evaluated proprietary and open-source baselines while converging faster than standard PPO. Our code is available at https://github.com/ZJU-REAL/ViSkill.","authors":["Hongxing Li","Dingming Li","Yixin Li","Yong Du","Wenqi Zhang","Weiming Lu","Jun Xiao","Yueting Zhuang","Yongliang Shen"],"published":"2026-10-08T17:44:19Z","updated":"2026-10-08T17:44:19Z","abstract_url":"https://arxiv.org/abs/2610.12403v1","html_url":"https://arxiv.org/html/2610.12403v1","pdf_url":"https://arxiv.org/pdf/2610.12403v1.pdf","matched_keywords":["agent"],"source_used":"html","source_text_chars":75081,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent 相关；摘要显示其主要贡献为：Skill-augmented agents improve sample efficiency by distilling successful trajectories into reusable strategies. Yet most existing approaches remain text-centric, linearizing spatial layouts and action-state correspondences into language that loses critical g...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-09T07:05:15+00:00","status":"fallback"},"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12402v1","title":"SpaceCast-Bench: Evaluating Predictive Spatial Reasoning in Vision-Language Models","abstract":"Existing spatial reasoning benchmarks mainly test spatial perception: reading off relations already visible in the input. Yet real-world spatial intelligence demands predictive spatial reasoning: constructing a scene from observations, anticipating how an intervention changes it, and reasoning about the unseen outcome. We introduce SpaceCast-Bench, the first benchmark to directly and diagnostically evaluate this capability. Built around an observe-transform-infer framework, its 3,862 questions from 182 real-world scenes span 16 task types at three levels: static perception, local prediction, and global prediction, progressively requiring scene understanding, spatial state updating, and relational inference over unobserved outcomes. Evaluating 21 models exposes a stark gap: the strongest model reaches only 58.0% against 87.2% human performance, while spatially specialized models remain near random chance. Controlled analyses further reveal that bridge views are critical for integrating distributed observations, and that explicit 3D evidence benefits models more reliably than generated outcome images or videos. Fine-tuning on our programmatically generated data lifts Qwen3-VL-4B from 34.0% to 65.7% with macro-average gains across six out-of-domain benchmarks.","authors":["Hongxing Li","Jinyue Su","Dingming Li","Wenqi Zhang","Weiming Lu","Jun Xiao","Yueting Zhuang","Yongliang Shen"],"published":"2026-10-08T17:44:17Z","updated":"2026-10-08T17:44:17Z","abstract_url":"https://arxiv.org/abs/2610.12402v1","html_url":"https://arxiv.org/html/2610.12402v1","pdf_url":"https://arxiv.org/pdf/2610.12402v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12399v1","title":"SpaceFlow: Locally Controllable 3D Generation","abstract":"Current 3D generation methods lack explicit local control: geometric adherence is often defined by a global control strength, and appearance cannot be specified locally. We present SpaceFlow, a training-free pipeline for locally controllable 3D generation from text descriptions and a collection of geometric primitives. Each primitive serves as a proxy for an object part and is assigned a local control level, enabling users to specify whether regions should strictly follow the input shape or allow generative completion. During structure generation, we enforce these spatial constraints within the generative flow process. For appearance synthesis, the generated structure is segmented and matched to the primitives. Each generated part is conditioned only on its assigned text or image cue, thereby limiting cross-part leakage. Regional geometry metrics demonstrate that SpaceFlow preserves the specified geometry in high-control regions and enables plausible shape variation in low-control areas. A user study further indicates that the resulting balance between geometric fidelity and generative freedom remains competitive in overall quality. When evaluating appearance on fixed geometry, text-conditioned routing achieves state-of-the-art prompt faithfulness and color/material accuracy. Qualitative results additionally show localized routing of image cues. The project page is available at SpaceFlow3D.github.io.","authors":["Neil De La Fuente","Joan Lafuente","Mukhammadali Sayfiddinov","Felicia Scharitzer","Marc Pollefeys","Ata Celen","Sayan Deb Sarkar","Elisabetta Fedele"],"published":"2026-10-08T17:42:39Z","updated":"2026-10-08T17:42:39Z","abstract_url":"https://arxiv.org/abs/2610.12399v1","html_url":"https://arxiv.org/html/2610.12399v1","pdf_url":"https://arxiv.org/pdf/2610.12399v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12388v1","title":"GenIA: Generative Reconstruction with Test-Time Input Alignment","abstract":"Reconstructing complete 3D object assets from monocular or sparse multi-view observations remains challenging. Generative 3D foundation models can complete object geometry beyond the observed views, but their predictions may not faithfully reproduce the observed geometry, appearance, or pose. We introduce GenIA, a framework for test-time input-aligned generation that grounds SAM3D's generative prior in geometric and photometric observations without retraining the foundation model. We improve object pose by deriving translation and scale from geometry while retaining the learned rotation prior, and align appearance through visibility-biased attention, cross-observation fusion, and differentiable rendering guidance during denoising. An optional post-denoising refinement further adapts the appearance latent, lightweight decoder adapters, and object placement to the observations. Our framework also supports externally supplied geometry; when given temporal shapes of dynamic objects, it recovers a shared, input-aligned canonical appearance and stable world-space placement. Across synthetic and real benchmarks, GenIA improves pose prediction and object reconstruction from monocular, multi-view, and dynamic inputs, outperforming recent optimization-based, per-frame image-to-3D, and video-to-4D methods. Our project page is available at https://facebookresearch.github.io/GenIA.","authors":["Stefano Esposito","Naama Pearl","Polina Karpikova","Samuel Rota Bulò","Lorenzo Porzi","Peter Kontschieder","Andreas Geiger","Jonathon Luiten"],"published":"2026-10-08T17:38:56Z","updated":"2026-10-08T17:38:56Z","abstract_url":"https://arxiv.org/abs/2610.12388v1","html_url":"https://arxiv.org/html/2610.12388v1","pdf_url":"https://arxiv.org/pdf/2610.12388v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12382v1","title":"WorldAlign: Decoupled 4D Reward for World-Consistent Video Generation","abstract":"Faithful visual world simulation requires generated videos to maintain 4D world consistency, encompassing both static and dynamic consistency. Static consistency requires coherent 3D structure in static environments across viewpoints, while dynamic consistency requires plausible subject motion and consistent appearance over time. Geometry-aware post-training offers a promising way to improve world consistency. However, existing methods often rely on a static-scene assumption. Even those that accommodate dynamic scenes struggle to provide reliable static-consistency feedback, while dynamic consistency is often overlooked or inadequately assessed. To address these limitations, we introduce WorldAlign, a decoupled 4D reward framework that semantically separates static regions and dynamic subjects and provides feedback by aligning each with a world prior suited to its assumptions. For static regions, WorldAlign aligns static geometry with a geometric world prior through semantically guided masked reprojection, enabling more reliable static-consistency evaluation; an auxiliary camera-motion reward discourages nearly static solutions. For dynamic subjects, WorldAlign uses a strong vision-language model (VLM) as a dynamic world prior and constructs a VLM-as-a-judge reward based on sample-specific checklists that assess dynamicity, physical plausibility, shape, and texture consistency. This decoupled design enables more effective online post-training without requiring human preference annotations. Across two pretrained image-to-video generators, Wan2.1 and Wan2.2, WorldAlign jointly improves static and dynamic consistency over existing methods without suppressing overall or subject motion. These results support decoupled world-prior alignment for more faithful visual world simulation. Project page: https://worldalign.github.io/.","authors":["Jing He","Kaixin Ding","Xingye Tian","Guibao Shen","Wenhang Ge","Xin Tao","Pengfei Wan","Ying-Cong Chen"],"published":"2026-10-08T17:35:19Z","updated":"2026-10-08T17:35:19Z","abstract_url":"https://arxiv.org/abs/2610.12382v1","html_url":"https://arxiv.org/html/2610.12382v1","pdf_url":"https://arxiv.org/pdf/2610.12382v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12374v1","title":"AgentGarten: Code Worlds for Evolving Agents","abstract":"Interactive virtual worlds allow agents to learn through exploration and interaction. What agents can learn is bounded by the environments they practice in, which must be faithful, with consistent state, rules, and dynamics, and realistic, with observations that follow the real-world visual distributions. Achieving both across diverse worlds remains a bottleneck. We introduce AgentGarten, a framework that couples simulators and game engines with a shared neural renderer to build real-time interactive environments. Its simulation backends maintain persistent world state and execute program-defined interaction rules, while the renderer generates visual observations from structured conditions exported through a common interface. To build the neural renderer, we adapt a pretrained video model to geometry conditions, distill it with our proposed Adversarial Forcing, and optimize inference for real-time interaction. Adversarial Forcing makes history prefilling differentiable through exact replay, so that losses on later predictions update how the renderer encodes prior observations, and adds real-data adversarial supervision to improve its visual quality. In AgentGarten, agents perceive the world through visual observations, interact with it in real time, and improve by distilling each round of experience into playbooks that subsequent agents inherit and refine. Our empirical study demonstrates a substantial gain in learning efficiency, with agents learning from just 4 rounds compared with millions for a conventional reinforcement learning counterpart. As new worlds can be written as code and rendered through the same interface, environments can scale in both number and difficulty alongside their agents, a step toward agents that keep evolving through interactive experience.","authors":["Jiawei Chi","Shangchen Miao","Zhiyuan Shi","Kailu Wu","Hanyang Wang","Weiliang Chen","Qiyu Dai","Jinshan Ren","Jun Gao","Mingsheng Long","Yueqi Duan","Jiangran Lyu","Jialong Wu","Fangfu Liu"],"published":"2026-10-08T17:32:00Z","updated":"2026-10-08T17:32:00Z","abstract_url":"https://arxiv.org/abs/2610.12374v1","html_url":"https://arxiv.org/html/2610.12374v1","pdf_url":"https://arxiv.org/pdf/2610.12374v1.pdf","matched_keywords":["video","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12369v1","title":"Embodied Turing Machines: Stateful Code for Robot Recursive Self-Improvement","abstract":"Most robot policies keep a model in the control loop: a VLA maps observations to actions, and an Agent Harness, such as Agent-as-Policy or Harness VLA queries a VLM for decision making at run time. We propose a different view: the embodied world is an Embodied Turing Machine, whose tape is the robot and environment state and rules are the policy. If this state can be represented accurately, the decision making can be written entirely in code. We therefore propose Code-Only-as-Policy (COAP): code measures and tracks the robot, environment, and task state from camera images and proprioception, and makes every decision from it. The same code applies across episodes, and different tasks share one library without a VLM or VLA in the loop. Compared with VLAs and Agent Harnesses, we analyze three advantages of COAP: (i) Explicit State: the state can be stored in code; (ii) Execution: code makes decision making controllable, recovers from failures flexibly, and runs fast and cheaply online; (iii) Extensibility: new tasks reuse, inherit, or extend the shared library, so capabilities can accumulate over tasks. These advantages make COAP a suitable medium for recursive self-improvement (RSI): coding agents develop the library in a closed loop, and each change is explicit and controllable. On RoboDojo's 42 bimanual tasks, the resulting library reaches a success rate of 70.24% without a model at test time. The upper bound of COAP lies in how accurately the state is represented for decision making and how robust the code logic is. We thus propose COAP as a new paradigm for embodied tasks; since it applies across episodes, it can also serve as an efficient data engine for VLAs and Agent Harnesses.","authors":["Kairui Hu","Siyuan Hu","Fangzhou Hong","Zhaoxi Chen","Ziwei Liu"],"published":"2026-10-08T17:29:08Z","updated":"2026-10-08T17:29:08Z","abstract_url":"https://arxiv.org/abs/2610.12369v1","html_url":"https://arxiv.org/html/2610.12369v1","pdf_url":"https://arxiv.org/pdf/2610.12369v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12355v1","title":"Distilling Routed 3D Privilege for Spatial Reasoning in Vision-Language Models","abstract":"Spatial reasoning remains a persistent weakness of vision-language models (VLMs), because RGB inputs do not directly provide geometric evidence. Existing remedies either inject 3D into the model at inference, paying architecture and latency costs, or train with outcome rewards that supervise only the final answer. Spatial errors originate in perception: a misjudged depth or direction can be corrected only by the scene's true geometry, which the 3D-scanned sources of spatial training corpora already provide. We propose GPD (Geometry-Privileged Distillation), which makes geometric evidence the privilege in on-policy self-distillation (OPSD). For each question, depth, semantic, and bird's-eye-view (BEV) cues are rendered as compact text and routed to the teacher alongside the reference answer; a privileged KL, applied only to incorrect trajectories, augments GRPO, and the deployed model remains RGB-only. On the 4B backbone, GPD achieves 57.1 on VSI-Bench and 37.6 average across MindCube, SPARBench, MMSI-Bench, and ViewSpatial, outperforming both GRPO and answer-privileged OPSD across spatial reasoning benchmarks. Ablations confirm the complementarity of 3D and answer privilege, the advantage of question-conditioned routing over full-context injection, and the benefit of restricting distillation to incorrect trajectories.","authors":["Hongxing Li","Yixin Li","Dingming Li","Zixuan Wang","Yuchen Yan","Wenqi Zhang","Weiming Lu","Yongliang Shen"],"published":"2026-10-08T17:22:24Z","updated":"2026-10-08T17:22:24Z","abstract_url":"https://arxiv.org/abs/2610.12355v1","html_url":"https://arxiv.org/html/2610.12355v1","pdf_url":"https://arxiv.org/pdf/2610.12355v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12343v1","title":"Reasoning-Informed Visual Editing","abstract":"Large Multi-modality Models (LMMs) have made significant progress in visual understanding and generation, but still face challenges in visual editing, particularly in following complex instructions, preserving appearance consistency, and supporting flexible input formats. To study this gap, we introduce RISEBench, the first benchmark for evaluating Reasoning-Informed viSual Editing (RISE), and extend it to RISEBench++, a more comprehensive and fine-grained benchmark for this emerging task. RISEBench++ extends the taxonomy into a hierarchical scheme spanning six reasoning dimensions: Temporal, Causal, Spatial, Logical, and Counterfactual Reasoning, together with Hybrid Reasoning integrating multiple reasoning types across multi-turn edits. These dimensions are further decomposed into 12 subcategories and 65 fine-grained task types. We expand input formats to include multi-image conditioning and scale the benchmark to 1000 human-annotated test cases, released in English and Chinese. We also improve our evaluation framework, assessing Instruction Reasoning, Appearance Consistency, and Visual Plausibility with human judges and an LMM-as-a-judge approach for more reliable and calibrated judgements. Beyond benchmarking, we introduce RISE-Agent, a training-free agentic framework integrating reasoning-driven planning, tool-augmented execution, and verifier-guided refinement, outperforming most strong existing approaches across diverse RISE tasks. We evaluate 58 visual editing approaches, including 34 open-source models, 19 closed-source models, and 5 agentic methods. The results reveal substantial challenges in reasoning-based visual editing, with even the strongest evaluated approach, GPT-Image-2.5 Sunburst, achieving only 56.6% accuracy. RISEBench++ highlights the limitations of contemporary editing models, provides insights, and indicates future directions for reasoning-aware visual editing.","authors":["Xue Yang","Peiyuan Zhang","Yilun Zhu","Qihao Yang","Mingxin Liu","Xiangyu Zhao","Ziqian Fan","Zhaokai Wang","Yan Li","Yifan Yang","Xu Yang","Xiaosong Jia","Yue Zhou","Zhihang Zhong","Junchi Yan"],"published":"2026-10-08T17:15:58Z","updated":"2026-10-08T17:15:58Z","abstract_url":"https://arxiv.org/abs/2610.12343v1","html_url":"https://arxiv.org/html/2610.12343v1","pdf_url":"https://arxiv.org/pdf/2610.12343v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12316v1","title":"Controllable Exaggeration for Generative Motion Models via Training-Time Adaptation and Inference-Time Guidance","abstract":"Recent motion generative models have demonstrated strong capabilities in synthesizing physically plausible character motion, but often overlook established animation principles used by professional animators to ground and design their animation work. Understanding and incorporating these principles into motion generative pipelines is essential for producing motions that serve not only physically grounded applications but also the needs of the character animation community. This enables the creation of characters that not only move in physically plausible ways but also feel alive, expressive, and engaging. To close this gap, we focus on the Exaggeration principle of animation and investigate how it can be incorporated into modern motion generative pipelines to produce more expressive character motions. To this end, we introduce a framework that operates at two stages of existing motion generative pipelines. The first stage introduces exaggeration during training, where we perform supervised fine-tuning of pre-trained text-to-motion models on our curated exaggeration dataset. The second stage operates at inference time, where we: (i) introduce a mathematical formulation of exaggeration based on dynamic movement primitives (DMPs); and (ii) leverage this formulation as an exaggeration guidance signal to guide existing diffusion and flow-matching text-to-motion generation models toward exaggerated motion without additional training. Through qualitative and quantitative evaluations against three strong motion generation models, we show that our methods generate more exaggerated and expressive motions while preserving neutral reference motion intent and physical plausibility.","authors":["Amirhossein Zamani","Arianna Rampini","Bruno Roy"],"published":"2026-10-08T17:00:57Z","updated":"2026-10-08T17:00:57Z","abstract_url":"https://arxiv.org/abs/2610.12316v1","html_url":"https://arxiv.org/html/2610.12316v1","pdf_url":"https://arxiv.org/pdf/2610.12316v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12310v1","title":"Is In-Domain Training Enough for Fine-Grained Industrial Anomaly Understanding?","abstract":"A single multimodal large language model (MLLM) struggles to excel simultaneously at detection, localization, description, and reasoning in multimodal industrial anomaly understanding (MM-IAU). We show that in-domain training does not close this gap. On MMAD, a widely adopted MM-IAU benchmark, trained specialists reach at most 75.5% accuracy in defect localization, against 92.3% for human experts, and even detect anomalies less accurately than their untrained base model. Meanwhile, different MLLMs offer complementary strengths but share this weakness in fine-grained perception, so combining them alone cannot remove it. We therefore propose SiGMA, a spatially grounded multi-agent framework that divides labor between heterogeneous MLLM agents and a dedicated visual defect expert. A multimodal searcher supplies industrial knowledge and normal references, the defect expert turns query-reference comparison into calibrated anomaly evidence, and a label-free reliability controller weighs each source by task-wise competence and query-level evidence quality. SiGMA reaches 85.2% average accuracy on MMAD, 4.0% above the strongest trained specialist and Gemini-2.5-Pro and within 1.5% of human experts. Even with three agents of at most 9B parameters, it reaches 84.4%, and new MLLMs join without retraining.","authors":["Xingwu Zhang","Duanyang Du","Huiling Zhu","Jiayue Dai","Yixiao Liu","Guozhi Liu","Zhihan Zhang","Zijun Long"],"published":"2026-10-08T16:59:29Z","updated":"2026-10-08T16:59:29Z","abstract_url":"https://arxiv.org/abs/2610.12310v1","html_url":"https://arxiv.org/html/2610.12310v1","pdf_url":"https://arxiv.org/pdf/2610.12310v1.pdf","matched_keywords":["agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12307v1","title":"BudgetPix: Compute-Adaptive Tokenization for Pixel-Space Image Diffusion","abstract":"Most image generation models rely on uniform tokenization, allocating the exact same computational budget to equally-sized image patches. This static paradigm cannot adapt to different resource constraints at inference time, and yields suboptimal quality-cost tradeoff by devoting the same effort to both plain backgrounds and intricate details. We propose BudgetPix, an adaptive tokenization framework that dynamically allocates compute based on visual complexity and spatial layout, enabling flexible computational budgeting at inference time. BudgetPix comprises three key components: (1) an adaptive encoder that maps a fixed-size image to a variable-length token sequence using an entropy-guided quadtree alongside a multi-scale patch embedder; (2) a scale-aware decoder reconstructs fixed-resolution images from multi-scale token sets; and (3) a flexible training and sampling schedule that enables pixel-space denoisers to operate across variable token counts. BudgetPix seamlessly integrates with existing pixel-space diffusion architectures, enabling a single checkpoint to be operated at a wide range of compute budgets. Evaluated on text-to-image generation, BudgetPix matches the fidelity of MiniT2I-L at $512^2$ and PixelDiT at $1024^2$ using just 25% of the original compute budget. In class-conditional generation using a MeanFlow backbone, BudgetPix requires merely 60% of the full compute budget to produce images with near-zero quality degradation, observing a marginal 0.8-point increase in FID. Comprehensive assessments by human and VLM judges confirm that BudgetPix establishes a significantly improved quality-efficiency tradeoff over prior budget-adaptive baselines. More details are available at our project page: https://karaozgur.com/BudgetPix","authors":["Ozgur Kara","Yujia Chen","Daniel Watson","David Forsyth","James Matthew Rehg","Wen-Sheng Chu","Du Tran"],"published":"2026-10-08T16:54:40Z","updated":"2026-10-08T16:54:40Z","abstract_url":"https://arxiv.org/abs/2610.12307v1","html_url":"https://arxiv.org/html/2610.12307v1","pdf_url":"https://arxiv.org/pdf/2610.12307v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12305v1","title":"From What to Which: Decoding Modifier Grounding in Frozen MLLMs","abstract":"As Multimodal Large Language Models (MLLMs) can describe increasingly complex visual scenes, token-level grounding becomes crucial. Yet, when an MLLM generates \"the yellow banana on the left\", established grounding approaches focus on what is in the image (\"banana\"), overlooking tokens that help describe which instance is meant (\"yellow\", \"left\"). In this work, we ask whether frozen MLLM representations contain decodable grounding information about the referred instance across generated tokens, extending to modifiers such as attributes, spatial expressions, and relational/action terms. To address this question, we introduce OTTER, a lightweight supervised probe over frozen MLLM representations that uses Optimal Transport (OT) to align generated tokens with visual regions and produce compact grounding maps. Our results show that (i) instance-discriminative visual information can be decoded from modifier tokens, with the clearest evidence for spatial terms, but (ii) is not confined to them, as contextualized object nouns also carry referential information; (iii) the recovered grounding remains informative under context perturbations, while selected regions remain relevant to generation; and (iv) the learned OT-based grounding extends beyond the controlled setting to free generation and cross-dataset transfer.","authors":["Barbara Toniella Corradini","Caterina Gallegati","Ludovica Genovese","Vittorio Murino"],"published":"2026-10-08T16:53:59Z","updated":"2026-10-08T16:53:59Z","abstract_url":"https://arxiv.org/abs/2610.12305v1","html_url":"https://arxiv.org/html/2610.12305v1","pdf_url":"https://arxiv.org/pdf/2610.12305v1.pdf","matched_keywords":["representation","instance","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12299v1","title":"Multi-Agent Egocentric World Model with Fine-Grained Embodied Interaction","abstract":"Egocentric world models predict first-person observations conditioned on an agent's actions, but most focus on a single agent. Real embodied settings often involve multiple agents that act and interact within a shared environment. Existing multi-agent world models rely on coarse actions like locomotion, camera control, or discrete commands, leaving fine-grained embodied interactions underexplored. We formulate multi-agent egocentric world modeling as synchronized ego-stream generation for multiple agents interacting through fine-grained actions in a shared world. This requires cross-view action consistency, shared-environment consistency, and consistent propagation of interaction-induced state updates. We propose Multi-agent Egocentric World Model (ME-World), which jointly denoises multiple ego streams in a shared token sequence, conditions each stream on all agents' target-view poses, and grounds generation with shared environment memory. We train and evaluate on real and synthetic multi-agent data and introduce shared-world consistency metrics for environment, update, and identity consistency. Experiments show ME-World improves shared-world consistency, action control, identity preservation, and video quality over existing methods.","authors":["Dahyun Chung","Siyoon Jin","Hyunwook Choi","Honggyu An","Junyoung Seo","Hyunsung Kim","Seung Wook Kim","Seungryong Kim"],"published":"2026-10-08T16:50:04Z","updated":"2026-10-08T16:50:04Z","abstract_url":"https://arxiv.org/abs/2610.12299v1","html_url":"https://arxiv.org/html/2610.12299v1","pdf_url":"https://arxiv.org/pdf/2610.12299v1.pdf","matched_keywords":["video","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12282v1","title":"Slot3R: Set-Associative Spatial Memory for Streaming 3D Reconstruction","abstract":"Streaming 3D reconstruction must preserve evidence from each frame while processing an expanding scene online. Spatial memory is a natural fit because it organizes history by reconstructed 3D location. Yet Point3R uses spatial proximity both to associate a new observation with an existing memory entry and to decide whether to fuse it, conflating co-location with state identity. Because pointers summarize image patches, nearby pointers may encode distinct surfaces, viewpoints, or visibility conditions; averaging them can destroy complementary evidence before later frames disambiguate it. We argue that location should determine address, not whether observations must merge. Slot3R realizes this principle as a training-free, set-associative retrofit that lets multiple states coexist at a shared address while keeping the pretrained Point3R backbone frozen. A bounded sparse readout further decouples persistent storage from per-frame decoder access. At 300-500 sampled frames, Slot3R reduces Point3R's point-cloud accuracy error (Acc) by 57.1%-63.1% on 7Scenes and 64.0%-72.0% on NeuralRGBD, lowers Sim(3)-aligned absolute trajectory error (ATE) on all three pose benchmarks, and remains competitive on video-depth estimation. It completes all evaluated settings from 600 to 1000 sampled frames at about 19 FPS under the same protocol, whereas Point3R and InfiniteVGGT run out of memory at 800 frames and beyond.","authors":["Xiyuan Zhang","Yanming Yang","Kaiyuan Xu","Ruibo Li","Chi Zhang"],"published":"2026-10-08T16:39:39Z","updated":"2026-10-08T16:39:39Z","abstract_url":"https://arxiv.org/abs/2610.12282v1","html_url":"https://arxiv.org/html/2610.12282v1","pdf_url":"https://arxiv.org/pdf/2610.12282v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12266v1","title":"DVD: Dynamic Vector Decoding for Efficient MLLM-based Perception","abstract":"Multimodal large language models have made remarkable progress in bridging vision and language, facilitating various perception tasks essential for human-machine interaction, robotics, and autonomous driving. However, existing MLLM-based perception methods predominantly rely on text-based coordinate representation, which suffers from excessive token overhead, or fixed-range quantization, which suffers from range and precision constraints, especially for 3D domains with unbounded spatial range and high localization accuracy requirements. To address these challenges, we propose a dynamic vector decoding method named DVD, which unifies the representation of 2D and 3D perception tasks. Specifically, we first transform diverse perceptual representation (i.e., 2D bounding boxes, 2D masks, and 3D bounding boxes) into 1D vector sequences, which are then mapped to compact discrete tokens in the high-dimensional space. Then, a lightweight de-tokenizer enables seamless integration with MLLMs by decoding output tokens back to original 2D and 3D perceptual representations. Extensive experiments on 2D and 3D perception benchmarks including RefCOCO series, SUN-RGBD, KITTI, Hypersim, nuScenes demonstrate that DVD achieves superior performance in 2D and 3D tasks and reduces significantly the token overhead and inference latency. DVD provides an efficient and general framework for integrating perception capabilities into MLLMs, overcoming the inherent limitations of existing methods.","authors":["Jinghua Hou","Zhe Liu","Hengshuang Zhao"],"published":"2026-10-08T16:32:28Z","updated":"2026-10-08T16:32:28Z","abstract_url":"https://arxiv.org/abs/2610.12266v1","html_url":"https://arxiv.org/html/2610.12266v1","pdf_url":"https://arxiv.org/pdf/2610.12266v1.pdf","matched_keywords":["3d","representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12256v1","title":"Syn-Omni: Structured Specialization and Progressive Collaboration for Omnimodal Embeddings","abstract":"Omnimodal embeddings naturally involve both shared representations and modality-specific features across heterogeneous inputs. However, existing omnimodal embedding methods often rely on a single shared parameter space over mixed-modality data, limiting structural separation between universal and modality-specific representations. To address this, we propose Syn-Omni, a unified framework for structured omnimodal adaptation with modality specialization and controlled cross-modal collaboration. Specifically, we introduce Orthogonal Modality-Expert LoRA (OME-LoRA), which decomposes adaptation into a shared LoRA path for universal semantics and modality-expert LoRA paths for modality-aware specialization. Furthermore, Progressive Synergy Routing (PSR) enables experts to first establish modality-specific priors, then gradually interact with other modality-experts for cross-modal synergy. Evaluated across 81 diverse tasks spanning image, video, audio, and audiovisual modalities, Syn-Omni consistently outperforms omnimodal baselines, demonstrating the effectiveness of structured specialization and cross-modal progressive collaboration.","authors":["Youngtaek Oh","Qiyu Wu","Hiromi Wakaki","Junmo Kim","Yuki Mitsufuji"],"published":"2026-10-08T16:26:03Z","updated":"2026-10-08T16:26:03Z","abstract_url":"https://arxiv.org/abs/2610.12256v1","html_url":"https://arxiv.org/html/2610.12256v1","pdf_url":"https://arxiv.org/pdf/2610.12256v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12248v1","title":"EgoVoice: Proactive Spoken Assistance from Egocentric Multimodal Streams","abstract":"Wearable augmented reality (AR) assistants are moving toward continuous real-world interaction, where they perceive the user's activity through first-person video and audio and provide timely spoken guidance without being explicitly asked. While proactive video assistants, spoken dialog systems, and egocentric task understanding have each advanced rapidly, existing systems do not address the joint problem of deciding when to speak and what to say from continuous first-person streams. We introduce EgoVoice, a framework for training and evaluating proactive egocentric spoken assistants. From HoloAssist video recordings of real human instructors, we construct clean audio streams through source separation and speech resynthesis, and convert each video session into a format where the model must decide at each moment whether to remain silent or provide spoken guidance. We fine-tune an omni-modal LLM with our data, and further improve its proactive intervention behavior with direct preference optimization. Experiments across closed and open-source models show that existing systems rarely produce well-timed, meaningful proactive interventions, while EgoVoice yields clear improvements in intervention timing, content relevance, and human preference over the zero-shot backbone.","authors":["Heeseung Kim"],"published":"2026-10-08T16:24:12Z","updated":"2026-10-08T16:24:12Z","abstract_url":"https://arxiv.org/abs/2610.12248v1","html_url":"https://arxiv.org/html/2610.12248v1","pdf_url":"https://arxiv.org/pdf/2610.12248v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12230v1","title":"From Prompting to Composing: A Spatial Canvas Interface for Poster Generation","abstract":"Text prompting is an indirect interface for poster generation, requiring users to encode inherently two-dimensional composition intent into a one-dimensional sequence of words. We introduce a Spatial Canvas Interface that enables users to directly compose generation intent in space through four complementary binding types: semantic, identity, text, and pixel, together with Text Specifications for individual elements and global appearance. Based on this interface, we develop Compo, a poster generation model adapted from a pretrained image editing model to understand Spatial Canvas inputs and Text Specifications. Compo supports both direct inference, where users explicitly construct the canvas, and agentic mode, where a high-level request is automatically translated into a planned Spatial Canvas. To train Compo, we develop a scalable pipeline that automatically constructs supervision data for different binding types and their combinations, enabling efficient adaptation without training a specialized poster generator from scratch. We further introduce a benchmark that evaluates adherence to individual binding types and their joint composition. Experiments show that Compo achieves stronger compositional controllability than both general-purpose image generation models and dedicated poster generation systems while maintaining high visual quality. By decoupling intent specification from visual generation, our work shifts poster generation from prompting toward composing.","authors":["Yitong Wang","Fangyun Wei","Jinjing Zhao","Sirui Zhang","Hongyang Zhang","Dong Chen","Bo Dai","Yan Lu"],"published":"2026-10-08T16:16:06Z","updated":"2026-10-08T16:16:06Z","abstract_url":"https://arxiv.org/abs/2610.12230v1","html_url":"https://arxiv.org/html/2610.12230v1","pdf_url":"https://arxiv.org/pdf/2610.12230v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12189v1","title":"Just Weather Scoring: Efficient End-to-end Nowcasting with Distributional Diffusion","abstract":"Generative diffusion models are well-suited for probabilistic precipitation nowcasting, but existing approaches often rely on separately trained compression or deterministic forecasting components and remain costly at inference due to iterative denoising. We introduce Just Weather Scoring (JWS), a single-stage, end-to-end diffusion model which addresses both issues by forecasting directly in radar space and enabling few-step generation. Radar-space modeling greatly simplifies training and inference and eliminates uncertainty arising from lossy compression. JWS combines Masked Asynchronous Diffusion, a timestep-sampling scheme that preserves clean context while adapting diffusion training to high-dimensional spatio-temporal data, with a simple scoring-rule objective that aligns training with probabilistic forecasting and unlocks few-step generation. On the SEVIR and MeteoNet benchmarks, JWS achieves state-of-the-art probabilistic forecasting performance at reduced training and inference cost. Even our smallest model remains competitive using substantially fewer parameters and more than 17x faster inference.","authors":["Jannik Wiese","Johannes Schusterbauer","Tommaso Martorella","Björn Ommer"],"published":"2026-10-08T15:50:43Z","updated":"2026-10-08T15:50:43Z","abstract_url":"https://arxiv.org/abs/2610.12189v1","html_url":"https://arxiv.org/html/2610.12189v1","pdf_url":"https://arxiv.org/pdf/2610.12189v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12156v1","title":"Connected Self Forcing: Beyond Local Learning in Video Autoregression","abstract":"To stream long videos while maintaining visual quality and temporal consistency, Self Forcing mitigates exposure bias through self-rollout training on self-generated histories with key-value (KV) caching. To keep memory manageable, it detaches historical caches, preserving forward dependencies between chunks but severing the backward gradient paths. We introduce Connected Self Forcing, a training framework that reconnects gradient paths across autoregressive chunks, allowing feedback from later predictions to guide how earlier context is generated. These connections go beyond historical KV-writing: gradients pass through generated latents into the computations that produced them, linking the generation of earlier context to its use in later predictions. To make this connected training memory-efficient, we develop shortcut gradient replay, which recovers cross-chunk gradients without retaining the full rollout computation graph. Integrated with distribution matching distillation, Connected Self Forcing trains historical chunks according to both their direct supervision and their contribution to subsequent generation. Experiments on autoregressive video generation show improvements in long-horizon visual quality and temporal consistency, without changing the inference procedure.","authors":["Dongbin Zhang","Chaoda Zheng","Kangjie Chen","Xiangyu Li","Shijia Chen","Jinhao Deng","Yuqi Zhang","Guangfeng Jiang","Hongbin Lin","Choo Sin Wai","Minqi Wang","Puyi Wang","Jingye Zhang","Yu Zhang","Xianming Liu","Boyang Wang"],"published":"2026-10-08T15:36:56Z","updated":"2026-10-08T15:36:56Z","abstract_url":"https://arxiv.org/abs/2610.12156v1","html_url":"https://arxiv.org/html/2610.12156v1","pdf_url":"https://arxiv.org/pdf/2610.12156v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12147v1","title":"Healthy Counterfactual Generation via Diffusion Inpainting for Mammography Classification","abstract":"False negatives remain a critical limitation of computer-aided diagnosis (CAD) systems for breast cancer screening due to delayed detection and treatment. To address this issue, we propose a counterfactual data augmentation strategy that generates healthy mammograms by \"erasing\" lesions from anomalous images, thereby enriching the training distribution. We train a Denoising Diffusion Probabilistic Model on BI-RADS 1 (healthy) mammograms and use a RePaint-based sampling strategy to inpaint realistic normal tissue within annotated lesion bounding boxes. The resulting healthy counterfactuals replace annotated lesion regions with realistic healthy tissue while preserving patient-specific anatomical structure, as supported by similarity metrics between real and generated images. Image realism was further assessed by radiologists and found to be consistent with the original dataset quality. We evaluate counterfactual augmentation across four representative classifier architectures: a convolutional neural network (ConvNeXt), a vision transformer (ViT), a vision-language model pre-trained on mammogram-report pairs (Mammo-CLIP) and a multi-scale attention-based multiple-instance learning framework (FPN-MIL). Experiments conducted on the VinDr-Mammo dataset show improvements in sensitivity across all architectures, particularly at 80\\% fixed specificity, contributing towards more reliable CAD systems for breast cancer. Code is available at: https://github.com/ines03garcia/diffusion-based-counterfactual-generation.","authors":["Inês Cruchinho Garcia","Mariana Mourão","Francisco Maria Calisto","Carlos Santiago","Jacinto Nascimento"],"published":"2026-10-08T15:31:56Z","updated":"2026-10-08T15:31:56Z","abstract_url":"https://arxiv.org/abs/2610.12147v1","html_url":"https://arxiv.org/html/2610.12147v1","pdf_url":"https://arxiv.org/pdf/2610.12147v1.pdf","matched_keywords":["instance","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12127v1","title":"LVS: Local View Synthesis from Relative Camera Pose by Reusing Previous Views","abstract":"Interactive scene exploration requires frequent view updates, although small camera motions preserve much of the visible content. Conventional 3D Gaussian Splatting nevertheless renders each target view, leaving this image overlap unexploited. Reusing rendered images offers an alternative. Geometric warping alone cannot recover newly exposed content and remains sensitive to depth errors. We propose a per-scene framework that replaces repeated scene rendering for nearby views with relative-pose-guided RGB-D image reuse. Geometric warping uses depth and relative pose to transport source content, while a lightweight multiscale network predicts RGB residuals to correct artifacts and infer missing appearance. Cached source features further reduce repeated computation. On GS-render, residual refinement improves PSNR by 0.72~dB over pure warping; evaluations on captured and rendered scenes demonstrate low query latency. This separation of scene rendering from local view updates supports responsive scene exploration, with potential applications in augmented and virtual reality.","authors":["Qizhou Huo","Xuan Sun","Yongfei Guo","Zhipeng Wang","Yuanhao Gong"],"published":"2026-10-08T15:19:58Z","updated":"2026-10-08T15:19:58Z","abstract_url":"https://arxiv.org/abs/2610.12127v1","html_url":"https://arxiv.org/html/2610.12127v1","pdf_url":"https://arxiv.org/pdf/2610.12127v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12126v1","title":"SuperNav: An Agentic Navigation System for Any Task in Any Scene","abstract":"General-purpose service robots need navigation systems that can handle diverse human requests in unfamiliar environments, combining task generality with scene generality. Some existing methods fine-tune multimodal large language models (MLLMs) to predict navigation actions, making their behavior dependent on the coverage of navigation training data and potentially limiting generalization to new requests and environments. Our key insight is to let the MLLM focus on interpreting requests, understanding scenes, and making decisions while preserving its general-purpose capabilities and delegating motion execution to navigation tools. To realize this idea, we introduce SuperNav, which equips a pretrained MLLM with a specialized agent harness without navigation-specific fine-tuning of the MLLM. Our harness supports these decisions with Navigation Skills, agent-oriented Tools for physical interaction, and task-progress and context management. A unified visual-point interface connects decision-making to motion by allowing the model to specify destinations directly in images and revise its decisions from execution feedback. Together, these components support sustained navigation across different task requirements and environments. SuperNav outperforms four evaluated baselines on instance-level, multi-object, and demand-driven tasks. Category-level evaluation on HM3D and deployment on a real quadruped robot further demonstrate its applicability across environments. Project Page: https://zju3dv.github.io/SuperNav/","authors":["Jinkai Zhang","Jingyi Xu","Yuanhong Yu","Jiarui Guo","Ruizhen Hu","Hujun Bao","Xiaowei Zhou","Sida Peng"],"published":"2026-10-08T15:19:40Z","updated":"2026-10-08T15:19:40Z","abstract_url":"https://arxiv.org/abs/2610.12126v1","html_url":"https://arxiv.org/html/2610.12126v1","pdf_url":"https://arxiv.org/pdf/2610.12126v1.pdf","matched_keywords":["3d","agent","instance","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12107v1","title":"ContourVLA: A Closed-Loop Perception-Action Contour Policy for Generalized Referring Expression Segmentation","abstract":"Generalized referring expression segmentation (GRES) requires dynamically balancing high-level semantics for identifying a variable number of language-specified referents with fine-grained visual evidence for precise boundary delineation. This requirement challenges existing cascaded vision-language architectures, which typically rely on static feature interfaces and single-pass mask prediction, limiting adaptive perception and geometric correction. We introduce ContourVLA, a vision-language-action policy that recasts GRES as a closed-loop visuomotor process, in which editable contours serve as explicit policy states that condition multimodal perception and are updated by geometric action chunks. Evolution-Aware Semantic Scheduling (EASS) couples contour-guided bidirectional boundary sampling with state-conditioned routing of multilevel multimodal features, adapting perception to each contour state. Following supervised initialization, Dustbin-Augmented Entropic Credit Transport GRPO (DECT-GRPO) jointly optimizes discrete grounding and continuous contour actions with instance-level credits. Its rollout rewards and credits are derived from soft prediction-target correspondences that account for false positives and missed targets. ContourVLA improves gIoU over the strongest evaluated baselines by 8.7, 2.8, and 2.7 points on gRefCOCO val, testA, and testB, respectively, and achieves the highest mIoU across all eight RefCOCO, RefCOCO+, and RefCOCOg splits.","authors":["Ruicheng Zhang","Kaiwen Shen","Jiaqi Hou","Shuhan Yang","Junchao Huang","Kewei Zhang","Jun Zhou","Li Jiang","Shen Zhao"],"published":"2026-10-08T15:06:00Z","updated":"2026-10-08T15:06:00Z","abstract_url":"https://arxiv.org/abs/2610.12107v1","html_url":"https://arxiv.org/html/2610.12107v1","pdf_url":"https://arxiv.org/pdf/2610.12107v1.pdf","matched_keywords":["instance","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12104v1","title":"VINCIE-NExT: Unlocking Video Editing from Images via In-Context Modeling","abstract":"Building a capable video editor remains significantly harder than a video generator: editing requires (source, instruction, edited) triplets that are prohibitively expensive to annotate and difficult to synthesize at scale, whereas image editing has already reached maturity with millions of such pairs readily available. In this work, we introduce VINCIE-NExT, a unified framework that transfers editing capability from images to videos through in-context visual demonstrations, alleviating the need for large-scale paired video editing data. VINCIE-NExT decomposes video editing into a structured chain of composable sub-tasks (Video -> Image -> Image -> Video), routing editing intent through the image domain and enabling scalable joint training from heterogeneous image and video corpora under a unified diffusion objective. An image editing pair, synthesized by the model or supplied by the user, is prepended as an in-context visual demonstration that serves as a spatial appearance blueprint for every output frame. To ground appearance edits across the interleaved context, we introduce a novel position encoding that links image demonstrations and video frames in a shared spatial coordinate system, enabling pixel-faithful propagation of appearance changes to every output frame. Chain-of-Editing further provides principled test-time scaling: by executing the sub-task chain as progressive diffusion stages, editing quality can be improved by investing additional compute without retraining. Comprehensive experiments on OpenVE-Bench demonstrate the state-of-the-art performance across diverse editing categories, with ablations confirming the effectiveness of each component.","authors":["Leigang Qu","Feng Cheng","Ziyan Yang","Bangbang Yang","Zhaoyang Huang","Wei Chow","Yicong Li","Wenjie Wang","Tat-Seng Chua","Yan Zeng"],"published":"2026-10-08T15:03:48Z","updated":"2026-10-08T15:03:48Z","abstract_url":"https://arxiv.org/abs/2610.12104v1","html_url":"https://arxiv.org/html/2610.12104v1","pdf_url":"https://arxiv.org/pdf/2610.12104v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12095v1","title":"DVLA-RL++: Dual-Level Vision-Language Alignment with Reinforcement Learning Gating for Few-Shot Learning","abstract":"Few-shot learning aims to recognize novel categories from limited labeled examples. Recent studies incorporate textual semantics to compensate for limited visual observations and improve class representations. However, high image-text agreement may reflect both intrinsic object properties and incidental context, making support prototypes susceptible to contextual contamination. To address this problem, we propose DVLA-RL++, which extends DVLA-RL with complementary semantic purification (CSP) and counterfactual reinforcement-learning gating (CRG). Specifically, CSP generates intrinsic and nuisance descriptions from labeled supports and compares their agreement with each support token. An ambiguity-dependent rejection margin guides sparse evidence allocation, while an intrinsic semantic anchor fills the unassigned mass to provide a fallback when visual evidence is unreliable. CRG learns layer-wise semantic fusion strengths using a reward that balances recognition performance and nuisance exposure. An independently executed reference trajectory on the same episode provides a paired learning signal. Theoretical analysis relates retained evidence and anchor quality to prototype stability and establishes conditions for unbiased on-policy gradient estimation. Experiments on standard, fine-grained, and cross-domain benchmarks show state-of-the-art accuracy, with an average gain of 1.4% over DVLA-RL. The project page is available at https://peacelwh.github.io/TPAMI27-DVLA-RLpp/.","authors":["Wenhao Li","Xianjing Meng","Qiangchang Wang","Zhongyi Han","Yilong Yin","Liqiang Nie"],"published":"2026-10-08T15:01:47Z","updated":"2026-10-08T15:01:47Z","abstract_url":"https://arxiv.org/abs/2610.12095v1","html_url":"https://arxiv.org/html/2610.12095v1","pdf_url":"https://arxiv.org/pdf/2610.12095v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12081v1","title":"Perception Test 2026: Challenge Summary and Extension to City-scale Audio-Visual Reasoning","abstract":"Continuing the Perception Test challenge series, we organised the fourth edition as a workshop at the European Conference on Computer Vision (ECCV) 2026 in Malmö, Sweden. This edition focused on spatial intelligence and featured four different tracks: unified multiple-choice videoQA and grounded videoQA from the original Perception Test benchmark, alongside two new tracks based on city-scale walking-tour videos (KilometerAudio and KilometerVision). In this report, we describe the new benchmarks used for the city-scale tracks and summarise the winning solutions across all tracks, including a generalist model that competed across all tracks with satisfactory performance. The winning solutions in the newly added city-scale tracks demonstrated that complex spatial and multimodal reasoning can be solved by expensive agentic pipelines, but remains difficult for multimodal models used standalone.","authors":["Fedor Kitashov","João Carreira","Shiry Ginosar","Dima Damen","Andrew Zisserman","Viorica Pătrăucean"],"published":"2026-10-08T14:54:26Z","updated":"2026-10-08T14:54:26Z","abstract_url":"https://arxiv.org/abs/2610.12081v1","html_url":"https://arxiv.org/html/2610.12081v1","pdf_url":"https://arxiv.org/pdf/2610.12081v1.pdf","matched_keywords":["video","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12073v1","title":"A Minimal Optical-Flow Representation for Vision-Based Tactile Rotation Classification in Robotic Manipulation Across Gravity Domains","abstract":"Vision-based tactile sensors provide rich contact information, but processing high-resolution images can be costly for resource-constrained platforms such as space robots. This work investigates whether a compact representation of tactile motion can classify object rotation across different gravity conditions. Dense optical flow from a simulated GelSight Mini is aggregated over a 7x9 grid into 126 features and used to classify the direction of load-induced rotation under Earth, Mars, Moon, and orbital gravity. Gravity causes a small but significant shift in these features, accounting for 1.6% of their variance (R2 = 0.016). Despite its small magnitude, this shift affects models trained only on Earth data: XGBoost accuracy decreases from 94.4% on Earth to 75.9% in orbit. In contrast, a single model trained across all four gravity domains achieves 96.3% overall accuracy and 95.1%-97.0% across individual domains, without using gravity as an input. The representation can also be reduced to 40 features while retaining 95.7% accuracy, with XGBoost requiring only 0.14 ms per inference. These findings show that Earth-gravity performance alone is insufficient to establish the transferability of tactile perception for space robotic manipulation, highlighting the need to account for gravity-induced domain shifts during training and validation.","authors":["Oscar Martinez-Bernal","Mario Cavero-Vidal","Francesco Grella","Carol Martinez"],"published":"2026-10-08T14:50:08Z","updated":"2026-10-08T14:50:08Z","abstract_url":"https://arxiv.org/abs/2610.12073v1","html_url":"https://arxiv.org/html/2610.12073v1","pdf_url":"https://arxiv.org/pdf/2610.12073v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12069v1","title":"LIVIN: Benchmarking Spatial and Embodied Intelligence in Digital Twins of Lived-In Homes","abstract":"Realistic household simulation must capture not only diverse environments but also the lived-in object arrangements and spatial constraints that shape robot motion and interaction. Existing resources often trade off scale, real-world correspondence, and interaction readiness, leaving a gap in faithful, interactive replicas of how real homes are actually arranged. To this end, we introduce LIVIN, a benchmark for spatial and embodied intelligence built on digital twins of 30 diverse lived-in homes. These replicas preserve observed room layouts, furniture configurations, and everyday belongings. To construct them, we design a human-in-the-loop workflow comprising instance recognition, architectural reconstruction, and object generation and placement, with intermediate results reviewed and corrected by humans against the source observations at each stage. We evaluate four tasks in LIVIN: 3D detection, 3D reconstruction, navigation, and loco-manipulation. Our evaluations show that current methods remain challenged by the dense object arrangements, occlusions, limited free space, and constrained interaction regions found in realistic lived-in homes. We hope LIVIN will help advance embodied AI in real-world homes, from spatial understanding to robotic interaction, and ultimately bring embodied intelligence into everyday home environments.","authors":["Peijun Xu","Chuansen Nie","Yiyang He","Yinuo Bai","Jingyang Liu","Kuixiang Shao","Yuyang Jiao","Kuanhao Xia","Jiayi Zhu","Zitian Yang","Yanqi Zhang","Tianye Tan","Shuwei Di","Junyi Xu","Jingyi Yu","Jiayuan Gu"],"published":"2026-10-08T14:47:30Z","updated":"2026-10-08T14:47:30Z","abstract_url":"https://arxiv.org/abs/2610.12069v1","html_url":"https://arxiv.org/html/2610.12069v1","pdf_url":"https://arxiv.org/pdf/2610.12069v1.pdf","matched_keywords":["3d","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.12060v1","title":"Look Back, Think Ahead: Visual Memory on Demand for Efficient Multimodal Reasoning","abstract":"Processing long visual token sequences from high-resolution images makes multi-step reasoning computationally expensive for multimodal Large Language Models (MLLMs). Existing one-shot pruning and aggregation methods compress visual tokens into a fixed context before decoding. However, visual evidence needs can shift as reasoning unfolds, making it difficult for a fixed compressed context to retain all the details needed across stages. To address this challenge, we propose ViMoD, a lightweight framework that maintains a compact visual context while preserving access to original fine-grained evidence as reasoning needs evolve. Deformable Aggregation of Region-wise Tokens (DART) learns content-adaptive groups and aggregation capacities, constructing compact Coarse representations linked to recoverable original Fine tokens. Temporal Routing for Adaptive Contextual Evidence (TRACE) integrates decoding history to anticipate upcoming evidence needs and select, retain, or replace active Fine-token groups. Selected Fine tokens augment the persistent Coarse context in the frozen backbone, enabling stage-specific evidence access without continuously attending to all visual tokens. On Qwen3-VL-4B, ViMoD outperforms all evaluated baselines on all eight reasoning benchmarks at a 20% target visual token budget, improving the mean normalized score by 39.0% over the strongest evaluated one-shot baseline. These gains are achieved with only 0.0546% additional trainable parameters relative to the frozen backbone.","authors":["Yicheng Xue","Han Wu","Jufeng Yang","Minjing Dong","Xinghao Chen","Hanting Chen","Jianyuan Guo"],"published":"2026-10-08T14:42:57Z","updated":"2026-10-08T14:42:57Z","abstract_url":"https://arxiv.org/abs/2610.12060v1","html_url":"https://arxiv.org/html/2610.12060v1","pdf_url":"https://arxiv.org/pdf/2610.12060v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11993v1","title":"DataVista: Diagnosing Multimodal LLMs on Data Video Understanding","abstract":"Data video is a media form that integrates data visualization with video narrative, widely adopted in news reporting and business analysis. Compared with general video understanding, data video understanding places greater emphasis on accurately reading data from animated charts, integrating evidence across charts and time, and understanding how narrative organization and visual design communicate information. Yet existing benchmarks target either general videos or static charts, and data video understanding has not been systematically evaluated. We present DataVista, the first benchmark for data video understanding, containing 961 real-world data videos and 6,775 evaluation questions organized under a three-level progressive capability framework (data perception, temporal reasoning, narrative understanding) with 10 fine-grained question types across five topic domains. Systematic evaluation of 19 mainstream MLLMs shows that the best-performing model, Gemini-3.1-Pro, achieves 70.0% overall accuracy, still far below human expert performance, with models performing worst on Causal Reasoning and Narrative Structure. Increasing frame counts and adding subtitles mainly benefit data perception and temporal reasoning, with limited gains in narrative understanding. Further analysis of model responses identifies typical failure modes in chart reading, evidence judgment, and instruction understanding. The benchmark is available at https://github.com/HKUSTDial/DataVista.","authors":["Yupeng Xie","Zhenyang Wang","Jiayi Zhu","Yinghao Tang","Zhouan Shen","Yiyu Chen","Yuyu Luo"],"published":"2026-10-08T14:02:35Z","updated":"2026-10-08T14:02:35Z","abstract_url":"https://arxiv.org/abs/2610.11993v1","html_url":"https://arxiv.org/html/2610.11993v1","pdf_url":"https://arxiv.org/pdf/2610.11993v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11986v1","title":"FearCaut-Qwen: Affective Steering in a Vision-Language Model Shifts the Decision Criterion for Hazard Assessment","abstract":"Vision-language models (VLMs) show great potential for damage assessment after a disaster, but a recurring deficiency is that they are reluctant to declare a hazard; that is, recall is low even when overall accuracy appears adequate. This study examines that deficiency by using signal detection theory to decompose the decision behavior into perceptual capability and decision-criterion placement. We then propose a novel method for correcting the over-conservative decision policy, inspired by the finding that fear makes humans risk-averse, and ask whether an affective representation associated with fear can be causally manipulated to similarly alter a VLM's decision tendency. Using mechanistic interpretability, we localize a causally implicated affective circuit in the model and use activation steering to manipulate it while observing the effect on downstream prediction. The method is tested on a two-stage SeisMLLM pipeline built on Qwen2.5-VL-7B-Instruct, which flags only 27.0% of genuinely unsafe buildings on the SeisMLLM-1K test split and never issues a false Red, an SDT criterion of c = +1.354, despite adequate evidence quality (d' = 1.521). An affective direction is localized on emotion-rich natural scenes, causally validated by sparse-neuron knockout and distributed steering on held-out emotion data, and then injected into the building task. Fear-direction injection raises Red recall to 75.7% (p<0.001), and subtracting the same direction suppresses Red predictions entirely, whereas norm-matched random and matched happiness directions show no significant effect. The mechanism is a shift in criterion (c=-1.515) while discrimination is not improved (d'=-0.493). These results show that VLM decisions can be adjusted at inference time without retraining and demonstrate how mechanistic interpretability can be used to diagnose and control VLM decision behaviors in engineering applications.","authors":["Xiaoshan Zhou"],"published":"2026-10-08T13:57:46Z","updated":"2026-10-08T13:57:46Z","abstract_url":"https://arxiv.org/abs/2610.11986v1","html_url":"https://arxiv.org/html/2610.11986v1","pdf_url":"https://arxiv.org/pdf/2610.11986v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11967v1","title":"Learning Which Correspondences to Trust: Confidence-Weighted Event-Camera Localization in LiDAR Maps","abstract":"Localizing an event camera against a pre-built LiDAR map can be cast as dense optical-flow estimation between a rendered depth view and an event image, followed by a Perspective-n-Point (PnP) solver over the induced 3D-2D correspondences. Existing pipelines rely on geometric consensus during pose estimation, but do not explicitly model the reliability or pose informativeness, i.e., how strongly a correspondence constrains the camera pose, of individual correspondences. We show that the natural way to learn it -- using the per-correspondence error to constrain the learning of confidence -- suffers from a depth-dependent bias: small pixel errors reside predominantly at large depths and do not lead to high pose informativeness. Instead, in our method (CELL), we learn a per-correspondence confidence end-to-end through the pose, using a differentiable probabilistic PnP whose log-partition term encourages weight configurations that yield a better-constrained pose distribution. The learned confidence is used in three ways: (i) it reweights the flow supervision in a decoupled training scheme that keeps pose gradients out of the flow/edge backbone; (ii) it drives a probabilistic correspondence selection at test time; and (iii) together with the network's edge-probability it weights a final edge-matching refinement. We further design a partial-completion depth representation that adds signal without hallucinating across large gaps. On M3ED and DSEC our full system improves over the LEAR baseline on the majority of the evaluated sequences: it reduces the median translation error by up to 26.9% and the median rotation error by up to 15.8%.","authors":["Panagiotis Kiousis","Kuangyi Chen","Jun Zhang","Friedrich Fraundorfer"],"published":"2026-10-08T13:45:54Z","updated":"2026-10-08T13:45:54Z","abstract_url":"https://arxiv.org/abs/2610.11967v1","html_url":"https://arxiv.org/html/2610.11967v1","pdf_url":"https://arxiv.org/pdf/2610.11967v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11942v1","title":"Right Screen, Wrong Transition: World Models as Verifiers for GUI Agents","abstract":"A login screen that appears after a tap on Sign in is expected; the same screen after a tap on View order is an attack. For GUI agents, safety is therefore a property of the transition rather than of the screen, and a monitor that inspects only screens can be defeated by reusing a legitimate one. Judging a transition requires an expectation of what should have followed the action. Existing GUI world models provide one, but they output it as text, code, or images, so checking it against the observed screen requires a second model to judge the two. We argue that a world model meant for verification should instead predict in the space in which observations are encoded, and present LGWM, a decoder-free, action-conditioned world model that predicts the representation of the next screen directly, trained without semantic annotation on 1.85M real GUI transitions. Verification reduces to a vector comparison, and the same signal reveals whether a mismatch is harmful. We evaluate on RSWT-BENCH, a diagnostic where each credential screen appears under both a legitimate and a hijacked transition, so detectors that see only the screen are at chance by construction. The training-free score reaches 0.987 AUC at 17 ms per decision, on par with the strongest closed-source VLMs and about ten AUC points above generative GUI world models at over three orders of magnitude lower latency. The residual direction reaches 0.953 AUC at separating harmful from benign violations, where prompted VLMs are near chance. Further analyses show that the prediction is a usable future state rather than an anomaly score. World models have mostly served as simulators or planners; our results point to a third role, verification, for which predicting in representation space is the natural design.","authors":["Jiaming Zhang","Xuan Wang","Fuyao Zhang","Yang Cao","Lingjuan Lyu","Wei Yang Bryan Lim"],"published":"2026-10-08T13:33:23Z","updated":"2026-10-08T13:33:23Z","abstract_url":"https://arxiv.org/abs/2610.11942v1","html_url":"https://arxiv.org/html/2610.11942v1","pdf_url":"https://arxiv.org/pdf/2610.11942v1.pdf","matched_keywords":["agent","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11924v1","title":"Revisiting Identity and Spectra Dispersion in Media-Bridged Time Series Forecasting: Linking Multivariate Signals and Narrative Flows","abstract":"Media-bridged time series forecasting is expanding to encompass traditional \"multivariate\" and emerging \"multimodal\" (e.g., through textual assistance). Existing Time Series Forecasting (TSF) models still rely on paradigm-specific relation, fusion, and temporal modules, hindering a common forecasting backbone across numerical and pre-aligned narrative-flow settings. To explore this, we propose the Multimedia Identity-Aware Prism Network (MIDAPN), a unified spatiotemporal forecasting backbone based on media-general graph adaptation and automatic temporal learning: (1) Following media pre-alignment, our Multimedia Identity-Aware Graph (MIDAG) revisits identity through static essence, dynamic behavior, and latent commonality, inducing affinities that extend variable-specific dependencies across media. Contextual Identity Modulation (CIM) further refines discriminative aggregation. (2) We develop Spectral Prism Convolution (SPConv) to automatically perform hierarchical temporal analysis, balancing coarse trends and fine-grained details. Meanwhile, its Adaptive Search Guidance configures a scale-efficient architecture for temporal-dimension reconstruction. These decoupled yet synergistic components jointly address media identity disentanglement and temporal-scale mismatch. Comprehensive evaluations involving 16 SOTA TSF models across 13 \"multivariate\" and 12 \"multimodal\" datasets, alongside targeted long-context comparisons against 14 time series foundation models and fused pretrained language models, demonstrate MIDAPN's consistent superiority and broad shared backbone compatibility. The code is available at \\href{https://github.com/leijieruilq/MIDAPN/tree/main}{https://github.com/MIDAPN}.","authors":["Jierui Lei","Wenjian Zhang","Qingyi Yang","Yuyang Hong","Fangzheng Chen","Zhengbo Zhang","Haina Tang","Shiming Xiang"],"published":"2026-10-08T13:20:49Z","updated":"2026-10-08T13:20:49Z","abstract_url":"https://arxiv.org/abs/2610.11924v1","html_url":"https://arxiv.org/html/2610.11924v1","pdf_url":"https://arxiv.org/pdf/2610.11924v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11907v1","title":"Beyond Visual Enhancement: Adaptive Multi-Context Steering to Mitigate LVLM Hallucinations","abstract":"Hallucination remains a significant challenge in Large Vision-Language Models (LVLMs). Existing training-free methods generally mitigate hallucinations through contrastive decoding or visual enhancement, often increasing the relative influence of visual evidence during generation. This raises a fundamental question: Can LVLMs dynamically regulate the contributions of different context sources to suppress hallucinations? In this work, we investigate and quantify how LVLMs coordinate multiple context sources during decoding and examine how this intrinsic behavior can guide hallucination mitigation. We find that LVLMs exhibit an intrinsic vision-attending tendency that can guide adaptive visual steering, while textual contexts can also contribute to hallucination mitigation. Motivated by these findings, we propose AIMS (Adaptive Information Multi-source Steering), a lightweight training-free framework that adaptively coordinates visual, prefilled textual, and generated contexts during decoding. Specifically, AIMS constructs compact prototypes for the three context domains and estimates their affinities with the current query to determine head-wise steering weights. The resulting multi-source steering direction is applied to the query representation, enabling adaptive context integration without additional model training or auxiliary forward passes. Extensive experiments across multiple LVLMs and decoding strategies demonstrate that AIMS effectively mitigates object hallucination while maintaining competitive general-purpose multimodal capabilities.","authors":["Shuran Ma","JiaLe Li","Yuxin Dong","Shan Zheng","Qingyun Jiang","Xiang Chen","Qi Zhu","Deyi Ji","Yifan Yang","Jianfeng Pan","Yu Tian","Xue Yang"],"published":"2026-10-08T13:08:44Z","updated":"2026-10-08T13:08:44Z","abstract_url":"https://arxiv.org/abs/2610.11907v1","html_url":"https://arxiv.org/html/2610.11907v1","pdf_url":"https://arxiv.org/pdf/2610.11907v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11857v1","title":"Pose-Free Feed-Forward 3D Inpainting via Learnable Mask Attention and Support Token Refinement","abstract":"3D scene inpainting aims to recover missing or occluded regions in edited 3D scenes, while ensuring geometric and textural consistency. Existing approaches, however, typically require accurately calibrated camera poses, which restricts their applicability in casual, in-the-wild scenarios and introduces additional preprocessing overhead. To overcome this limitation, we present FreeInpaint, a novel feed-forward framework that generates complete and 3D-consistent scenes directly from unposed multi-view images with masked regions. At its core, FreeInpaint extends a 3D foundation model to propagate masked regions from a reference view to other unposed views, bridging 3D reconstruction and scene inpainting while preserving the model's native ability to recover camera poses and scene geometry. Our method addresses two key challenges in adapting feed-forward 3D foundation models to masked inputs. First, masked regions can corrupt cross-view correspondence reasoning, degrading pose estimation and geometry recovery. To address this, we introduce a Learnable Mask Attention mechanism that preserves the spatial anchoring of reliable observations while allowing masked regions to progressively absorb useful context in deeper layers. Second, under severe occlusions, a single forward pass often lacks sufficient appearance evidence for high-fidelity completion. Therefore, we propose a Support Token Refinement strategy, which injects diffusion-generated support evidence as confidence-weighted auxiliary tokens to refine under-observed regions while preserving the original spatial anchor. Extensive experiments across diverse datasets demonstrate that FreeInpaint achieves superior inpainting quality, eliminating the reliance on pre-computed camera poses while keeping a fast inference speed. The project page is https://rorisis.github.io/FreeInpaint/.","authors":["Jingyi Pan","Dan Xu","Qiong Luo"],"published":"2026-10-08T12:38:48Z","updated":"2026-10-08T12:38:48Z","abstract_url":"https://arxiv.org/abs/2610.11857v1","html_url":"https://arxiv.org/html/2610.11857v1","pdf_url":"https://arxiv.org/pdf/2610.11857v1.pdf","matched_keywords":["3d","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11850v1","title":"VEDJE: Video-Efficient Discriminative Joint Encoder for Scalable Video-Text Retrieval","abstract":"Finding the right video often requires distinguishing similar scenes in which different events occur. Joint matching improves retrieval, but processing rich video representations for each query is costly. VEDJE compresses features within sampled frames while keeping their representations separate in a reusable cache. Feature-change prediction supplies an auxiliary training signal that improves retrieval from the compressed cache without adding work at query time. On MSR-VTT, MSVD, DiDeMo, and ActivityNet, VEDJE improves R@1 over matched first-stage retrievers in both retrieval directions. On MSR-VTT, it reaches 59.8 text-to-video R@1 with a fine-tuned VideoCLIP-XL first stage. In the VideoPrism configuration, shrinking the per-video cache fourfold to 12 KiB preserves text-to-video recall within 0.2 points. These results show that accurate video search can operate on compact evidence, encoded once and reused as new queries arrive.","authors":["Shahaf Wagner","Gabriele Serussi","Dan Ben Ami","Tomer Galanti","Chaim Baskin"],"published":"2026-10-08T12:37:12Z","updated":"2026-10-08T12:37:12Z","abstract_url":"https://arxiv.org/abs/2610.11850v1","html_url":"https://arxiv.org/html/2610.11850v1","pdf_url":"https://arxiv.org/pdf/2610.11850v1.pdf","matched_keywords":["video","retrieval","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11846v1","title":"Open-Vocabulary Audio-Visual Event Localization via Complex-Valued Fusion","abstract":"Open-Vocabulary Audio-Visual Event Localization (OV-AVEL) labels each video segment with an event class, including classes that were never seen during training. The dominant pipeline uses a frozen multimodal foundation model (e.g. ImageBind) to embed the visual frame, the audio mel-spectrogram, and each candidate class name into a shared space, then computes two cosine similarities for each segment against each class: visual-text and audio-text. Existing methods then collapse this pair into a single scalar score with a fixed rule (geometric mean, weighted average) before taking the argmax. Instead, we compute complex-valued similarities and learn their fusion using a complex-valued neural network (CVNN). Each modality's standard representation becomes the real part of our pipeline, and a paired companion stream supplies the imaginary part. We use imaginary part of iHSV for visual modality and CycleGAN-translated phase spectrogram for audio modality as these companion streams. This results in two complex similarities, which are then fused. While the vision and audio encoders remain frozen, only the temporal-attention blocks and the fusion CVNN are trained. The four-stream complex architecture sets a new state of the art on both OV-AVEL benchmarks. On the open (unseen-class) split of OV-AVEBench we reach 66.5/59.1/54.1% Acc/Seg-F1/Event-F1 (+1.6/+4.1/+6.6 over the previously reported fine-tuned baseline), with consistent gains for seen classes as well. We also modify AVE dataset for this task and observe that our architecture reaches 60.7/51.9/50.4% Acc/Seg-F1/Event-F1, achieving state-of-the-art OV-AVEL results on it as well. We also propose a two-stream alternative, which also sees great improvements over the baseline.","authors":["Anirudh Praveen","Koteswar Rao Jerripothula","Pratik Joshi","Aveen Dayal","Neela Sawant"],"published":"2026-10-08T12:34:24Z","updated":"2026-10-08T12:34:24Z","abstract_url":"https://arxiv.org/abs/2610.11846v1","html_url":"https://arxiv.org/html/2610.11846v1","pdf_url":"https://arxiv.org/pdf/2610.11846v1.pdf","matched_keywords":["video","representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11826v1","title":"From Suppression to Repair: Mitigating Object Hallucination in Large Vision-Language Models via Localized Distribution Alignment","abstract":"Object hallucination remains a major obstacle for large vision-language models (LVLMs) to generate reliable content. An intuitive mitigation strategy is to suppress hallucination-related components in hidden representations. However, these components may also contain useful information, and suppressing them can weaken the model's multimodal capabilities. In this paper, we propose ResOT, a training-free method that repairs representations at inference time through localized distribution alignment. Specifically, ResOT projects dominant hallucinated directions away from the faithful subspace, forming a low-dimensional residual subspace for intervention. Within this subspace, ResOT uses Gaussian optimal transport (OT) to align the hallucinated distribution with the faithful one. The resulting map defines repair targets with minimal changes to the original representations. At inference, ResOT adaptively controls how far each token state moves toward its OT target. Experiments on three representative LVLMs show that ResOT substantially reduces object hallucination while improving image caption quality and multimodal performance across multiple benchmarks. Code will be released.","authors":["Chen Zhao","Xingping Dong","Jiachun Shi","Liang Peng","Chong Wang","Zhen Lei","Ran He","Bo Du"],"published":"2026-10-08T12:25:50Z","updated":"2026-10-08T12:25:50Z","abstract_url":"https://arxiv.org/abs/2610.11826v1","html_url":"https://arxiv.org/html/2610.11826v1","pdf_url":"https://arxiv.org/pdf/2610.11826v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11810v1","title":"Seek-and-View Reasoning for Multi-View Spatial Understanding","abstract":"Existing approaches to multi-view spatial reasoning operate largely on sparse input views. Vision-language models (VLMs) are thus restricted to understand a scene and infer spatial relations within these fixed views, leading to fragile cross-view alignment and geometry-to-language bottleneck. To address these issues, we formulate a novel Seek-and-View reasoning approach to find implicit cross-view spatial evidence by locating a question-relevant view to support the spatial reasoning. To realize this approach, we propose Vantage, a training-free model-agnostic reasoning framework that pairs a VLM with a 3D foundation model: a viewpoint-grounded reasoning stage for question analysis and view planning, followed by a geometry-grounded evidence augmentation stage to effectively synthesize and incorporate visual evidence into the final reasoning. Comprehensive experiments on six VLMs demonstrate consistent improvements on five benchmarks without fine-tuning. Overall, by revealing spatial evidence through view-grounded reasoning, Vantage can largely reduce reliance on language-based cross-view alignment and improve multi-view spatial understanding. Our code is available at https://github.com/q1xiangchen/Vantage.","authors":["Qixiang Chen","Cheng Zhang","Fucai Ke","Chi-Wing Fu","Jianfei Cai","Jingwen Ye"],"published":"2026-10-08T12:18:01Z","updated":"2026-10-08T12:18:01Z","abstract_url":"https://arxiv.org/abs/2610.11810v1","html_url":"https://arxiv.org/html/2610.11810v1","pdf_url":"https://arxiv.org/pdf/2610.11810v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11794v1","title":"Memento 3: Model-Based Recursive Self-Improvement through Reflective Rulebooks","abstract":"Learning to act in unfamiliar environments requires agents to infer how the world works and revise that understanding as new evidence arrives. Yet limited observations can support multiple world models that explain past interactions but predict different outcomes in unseen states. We introduce Memento 3, building on the Memento series to enable frozen LLM agents to continually learn explicit world models through external memory. The agent maintains a natural-language rulebook as persistent semantic memory, recording revisable hypotheses about environment dynamics while leaving unknown aspects underspecified. It compiles this rulebook into executable code for prediction and planning. Through a continual loop of observation, reflection, rule revision, compilation, and verification, the agent uses prediction errors to refine both the rulebook and its code. Updated code is accepted only when the LLM judges it faithful to the rulebook and cell-exact replay reproduces the observed transitions. We investigate this process as a model-based route to recursive self-improvement (RSI): the agent autonomously explores the environment, revises its world model, and uses verified updates to guide subsequent interaction and learning, while the underlying LLM remains fixed. A population extension maintains multiple world models in parallel, sharing interaction evidence and using their predictions to guide exploration. On ARC-AGI-3, the single-model agent clears every level of all 25 public games, achieves a mean Relative Human Action Efficiency (RHAE) of 100.0, and uses 44% of the human action count. In an Atari Pong case study, a learned feedback controller wins 21:0 in each of three evaluated episodes with different openings, without further LLM calls.","authors":["Haoyu Zhao","Zhengxu Yu","Zhiyuan He","Meng Fang","Rasul Tutunov","Haitham Bou-Ammar","Weilin Luo","Jun Wang"],"published":"2026-10-08T12:06:54Z","updated":"2026-10-08T12:06:54Z","abstract_url":"https://arxiv.org/abs/2610.11794v1","html_url":"https://arxiv.org/html/2610.11794v1","pdf_url":"https://arxiv.org/pdf/2610.11794v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11791v1","title":"Phase-aware video generation for physics-grounded dynamics and interactions","abstract":"Generating physically plausible videos for solid-gas dynamics is challenging as different phases exhibit distinct dynamics yet remain coupled through physical interactions. We present PAVG, a Phase-Aware Video Generator for solid-gas dynamics and interactions. It employs a dual-branch architecture to explicitly model the distinct dynamics of solids and gases, while spatiotemporal cross-attention captures their physical interactions. This design enables PAVG to preserve phasespecific motion characteristics while producing physically consistent responses across phases. To facilitate this task, we further construct a simulation corpus comprising over 700K physical trajectories across diverse solid, gas, and solid-gas interaction scenarios. Extensive evaluations demonstrate that our PAVG produces videos with improved motion adherence, physical plausibility, and visual quality compared with existing approaches.","authors":["Jingfeng Ou","Kun Wang","Rui Zhao","Jingwei Guan","Limin Wang","Chao Dong","Xingyu Zeng"],"published":"2026-10-08T12:04:46Z","updated":"2026-10-08T12:04:46Z","abstract_url":"https://arxiv.org/abs/2610.11791v1","html_url":"https://arxiv.org/html/2610.11791v1","pdf_url":"https://arxiv.org/pdf/2610.11791v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11781v1","title":"Skill-V: Verifiable Self-Evolving Skill Library for Interactive Agents","abstract":"Interactive agents can turn experience into reusable skills, yet existing self-evolving skill libraries primarily improve by accumulating new knowledge. Failures may lead to new skills, while previously stored skills are less often revisited as new evidence arrives. However, growth alone does not ensure reliability, as a retrieved skill may be inapplicable under the current task conditions, and an existing skill may encode a mis-specified operational boundary. Reliable skill evolution therefore requires not only adding knowledge, but also testing and revising what is already stored. We introduce Skill-V, a verifiable self-evolving skill library. To make stored knowledge testable, we propose representing skills as versioned, falsifiable contracts that link semantic intent to observable behavioral criteria. We use environment outcomes to drive library evolution. Specifically, task failures motivate skill addition, while disagreements between contract evaluations and task outcomes guide revisions to existing skill boundaries. To validate these revisions, we require them to preserve protected semantic constraints and satisfy non-regression criteria for rubric-outcome metrics on historical replay evidence. Finally, we employ an applicability-aware filter to exclude candidates judged confidently inapplicable to the current task. Across ALFWorld and WebShop, Skill-V achieves success rates of 95.3% and 85.9%, respectively, while maintaining a more compact skill library than growth-oriented baselines. Applicability-aware filtering reduces incorrect skill invocations, and outcome-grounded revisions correct mis-specified skill boundaries without degrading performance on previously observed evidence. These results show that reliable skill evolution requires more than accumulating experience: the library must learn which knowledge to retain, when to revise it, and when it should be applied.","authors":["Jie Ma","Zhipeng Qian","Yufei Ma","Zihan Liang","Jiayi Ji","Qingpeng Cai","Ben Chen","Peng Jiang","Xiaoshuai Sun"],"published":"2026-10-08T11:59:42Z","updated":"2026-10-08T11:59:42Z","abstract_url":"https://arxiv.org/abs/2610.11781v1","html_url":"https://arxiv.org/html/2610.11781v1","pdf_url":"https://arxiv.org/pdf/2610.11781v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11770v1","title":"From Video Clips to Creation Trajectory: Sora100K for AI-Native Video Creation","abstract":"AI-Native video creation is shifting from isolated video clips toward iterative video creation workflows. However, existing datasets remain largely video clips, representing video generation and editing as separate tasks rather than connected stages of a video creation workflow. In this paper, we introduce Sora100K, a dataset that represents the AI-Native video creation workflow as a structured video creation trajectory. Specifically, we first identify video creation trajectories and decompose them into three subsets according to their structural roles: text-to-video generation records as roots, single-turn video editing records as editing edges, and multi-turn video editing records as complete trajectories. Then, we use a VLM to assign semantic annotations for generation roots and editing-operation annotations for editing edges. A strict construction pipeline further reconstructs source-to-edit lineage, editing order, and intermediate video states while ensuring data quality. Finally, we perform lightweight adaptation on LTX-2 models to assess the supervision value of Sora100K. The results show improvements in visual quality, multi-shot generation, and cross-shot consistency, while successive-turn evaluation reveals that following multi-turn editing instructions remains challenging. Sora100K establishes a new data foundation for AI-Native video creation beyond isolated video clips and toward structured video creation trajectory. The dataset and supplementary materials are publicly available at https://huggingface.co/datasets/ysicong/Sora100K.","authors":["Sicong Yang","Ruihuan Yang","Jian Lu","Jianfei Yuan","Xiaodong Cun","Xiuli Bi"],"published":"2026-10-08T11:52:10Z","updated":"2026-10-08T11:52:10Z","abstract_url":"https://arxiv.org/abs/2610.11770v1","html_url":"https://arxiv.org/html/2610.11770v1","pdf_url":"https://arxiv.org/pdf/2610.11770v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11756v1","title":"Memory Forcing: Attendable Mid-Horizon History for Streaming Video Generation","abstract":"Autoregressive video diffusion enables causal video streaming without a bidirectional pass over the full clip, but existing few-step systems usually retain only the opening and most recent frames in a fixed-size KV cache. Once an event leaves this window, later frames can no longer attend to it, a failure we term mid-horizon forgetting. We present Memory Forcing, a few-step streaming method that preserves this missing history without increasing the cache size. Its Archive \\& Working Banks partition the cache into sink, archive, and working regions, retaining diverse intermediate events alongside recent motion under fixed memory. Because absolute temporal indices drift outside the training range, Bank-aware RoPE reassigns indices at attention time so each bank remains distinguishable. At 1.3B, Memory Forcing leads on longer clips, shows the smallest drop from 5s to 60s among methods reporting all four lengths, and preserves subjects and scenes through leave-and-return. The same design scales to Wan2.2 5B, producing more physically plausible, realistic, and dynamic videos and, to our knowledge, the first public 5B model on this forcing line.","authors":["Jiaming Zhang","Xinyu Wang","Huafeng Shi","Gangshan Wu","Limin Wang"],"published":"2026-10-08T11:42:57Z","updated":"2026-10-08T11:42:57Z","abstract_url":"https://arxiv.org/abs/2610.11756v1","html_url":"https://arxiv.org/html/2610.11756v1","pdf_url":"https://arxiv.org/pdf/2610.11756v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11751v1","title":"Dino Forcing Flow Models: Do not denoise what you can predict","abstract":"Co-denoising pretrained representations such as DINO can substantially improve the training speed and quality of flow matching models, but it introduces a second denoising trajectory and requires carefully designed schedules. We propose a simpler alternative: predict the pretrained representation directly, then condition the model on its own prediction. This removes the need for a second ODE and any representation-specific denoising schedules, while retaining the benefits of representation guidance. Our approach converges substantially faster and achieves better generation quality as measured by FID score. On ImageNet, it outperforms the state of the art in latent space at 2x fewer epochs than prior methods; in pixel space, it improves FID over comparable prior methods by more than 20%. These results support a simple principle: do not denoise what you can predict. Our code is openly available at https://github.com/arijit-hub/dino_forcing.","authors":["Arijit Ghosh","Lucas Degeorge","Paul Couairon","Alexei A Efros","Vicky Kalogeiton","David Picard"],"published":"2026-10-08T11:41:13Z","updated":"2026-10-08T11:41:13Z","abstract_url":"https://arxiv.org/abs/2610.11751v1","html_url":"https://arxiv.org/html/2610.11751v1","pdf_url":"https://arxiv.org/pdf/2610.11751v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11746v1","title":"Streaming-Aware Diffusion for Real-Time Video Super-Resolution via Cross-Step Attention","abstract":"Real-time video super-resolution requires high spatio-temporal fidelity under strict latency constraints, challenging diffusion models due to their iterative sampling cost and limited temporal coordination. We propose a streaming-aware framework that adapts pretrained single-image latent diffusion models for efficient video super-resolution (VSR) by exploiting the sequential structure of video streams. Our Cross-Step Attention mechanism reuses intermediate denoising features across adjacent frames and diffusion steps, enabling temporal information exchange without explicit temporal modeling. We further introduce Trajectory-Coupled Diffusion Scheduling, which aligns adjacent diffusion states and provides cleaner intermediate representations for cross-step conditioning, improving temporal coherence. These components are integrated into a streaming inference pipeline that incrementally propagates latent states across frames, reducing the effective computational complexity from $O(N \\cdot S)$ to $O(N + S)$ for $N$ frames and $S$ diffusion steps. Experiments on REDS4 and YouHQ40-Test demonstrate improved perceptual quality and temporal realism while maintaining frame-wise stability. Our method achieves over 40 FPS at $512 \\times 512$ resolution after cold start, enabling real-time VSR without explicit temporal modeling.","authors":["Harris Partaourides","Sotirios Chatzis"],"published":"2026-10-08T11:35:09Z","updated":"2026-10-08T11:35:09Z","abstract_url":"https://arxiv.org/abs/2610.11746v1","html_url":"https://arxiv.org/html/2610.11746v1","pdf_url":"https://arxiv.org/pdf/2610.11746v1.pdf","matched_keywords":["video","representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11736v1","title":"Towards Unified Evaluation of Prompt Enhancers for Video Generation","abstract":"Modern video generators can realize increasingly complex visual narratives, positioning the prompt enhancer (PE) as a critical bridge from concise user instructions and multimodal references to structured cinematic plans. However, existing PE evaluation relies on rendered videos, imposing substantial computational and human costs, slowing PE training and iteration, and conflating PE quality with downstream generator behavior. To address this gap, we introduce PEBench, the first unified benchmark for direct PE evaluation across text-to-video, image-to-video, and reference-to-video prompt enhancement. It comprises 1,100 expert-verified cases and 1,005 visual assets, spanning 35 fine-grained tasks with diverse temporal, cinematic, audiovisual, and multi-reference requirements. In addition, we develop PEBench evaluation, an evidence-grounded framework that combines modality-aware fact extraction with rubric-based assessment across 24 criteria. Our systematic evaluation of representative open- and closed-source PE methods reveals an emerging shift from fine-grained descriptive expansion toward intent-preserving cinematic planning, while the caption-reconstruction and forward-refinement methods show complementary strengths in cinematic coverage and semantic fidelity or internal coherence, respectively. Human validation shows that PEBench scores align closely with expert judgments of enhanced prompts and downstream videos from Wan3.0 and MiniMax-H3, indicating that prompt-level evaluation reliably reflects downstream utility.","authors":["Yawen Shao","Yubo Zhu","Ziyun Dai","Zixun Fang","Kai Zhu","Zeyinzi Jiang","Yufeng Ai","Siyang Sun","Haolan Xue","Yu Shang","Yuxiang Bao","Zoubin Bi","Jingming Luo","Jie Xiao","Chaojie Mao","Zhehan Kan","Hongchen Luo","Yu Liu","Sheng Zhong","Wei Tong","Xueyang Fu","Yang Cao","Wei Zhai","Zheng-Jun Zha"],"published":"2026-10-08T11:31:13Z","updated":"2026-10-08T11:31:13Z","abstract_url":"https://arxiv.org/abs/2610.11736v1","html_url":"https://arxiv.org/html/2610.11736v1","pdf_url":"https://arxiv.org/pdf/2610.11736v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11685v1","title":"HI3D 3.0 (Twinkle3D): Object-specific 3D Asset Generation with High Resolution","abstract":"Image-to-3D generation has become increasingly capable of producing objects that closely resemble the input image, and an outstanding challenge is to reproduce the depicted object itself, including the specific geometry that defines it. Inscriptions, brand marks, and repeated structures are frequently distorted or lost, despite being critical to object identity. We present Hi3D 3.0, an image-to-3D generation system targeting object-specific fidelity, with Twinkle3D as its geometry model for generating watertight triangle meshes at $2048^{3}$ resolution. Twinkle3D advances high-fidelity geometry generation along four dimensions. First, while O-Voxel/FaithC offers high representational precision, it often suffers from poor surface quality and non-watertight geometry. We address both issues while retaining its $2048^{3}$-level precision. Second, we scale diffusion generation to sequences of up to 300K geometric tokens through a redesigned DiT architecture and large-scale distributed training optimizations, reducing training time per step from approximately ten minutes to ten seconds. Third, subsequent refinement cannot fully compensate for errors introduced during initial generation; we therefore strengthen both global shape and local detail in the initial generation stage, and the resulting single-stage model surpasses prior two-stage pipelines with $512^{3}$ refinement. Finally, we introduce a fine-grained image-3D cross-modal interaction mechanism that strengthens correspondence between visual evidence and geometric tokens, improving the recovery of object-specific structures. We evaluate geometric fidelity using alignment metrics derived from silhouettes and normal fields. Hi3D 3.0 outperforms four commercial systems across all reported metrics, recovering 82.1% of inscribed characters at 98.2% precision, compared with 21.7% recall for the strongest competitor.","authors":["Ziying Li","Shengchu Zhao","Huiang He","Yiyang Chen","Jianwen Huang","Bailin Li","Changhao Li","Jianhui Li","Jie Li","Ruiyang Liu","Yibo Luo","Tengjiao Sun","Pei Tang","Shiwen Wang","Jiaqi Wu","Kang Wu","Kaiqiao Yang","Zherui Yang","Hu Zhang","Xuezhi Zhao","Xinhe Zheng","Yukun Li","Heliang Zheng","Rongfei Jia"],"published":"2026-10-08T10:57:06Z","updated":"2026-10-08T10:57:06Z","abstract_url":"https://arxiv.org/abs/2610.11685v1","html_url":"https://arxiv.org/html/2610.11685v1","pdf_url":"https://arxiv.org/pdf/2610.11685v1.pdf","matched_keywords":["3d","representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11674v1","title":"VESSI - VLM-Enhanced Support for Surveillance and Investigations","abstract":"Automated video surveillance analysis has become a critical component of intelligence infrastructures and Law Enforcement agencies. Traditional systems lack the semantic module for comprehensive situational awareness and forensic tasks, limiting their ability to interpret events meaningfully or support post-incident investigations. This slows operational insight and increases the burden on human analysts. Recent advances in Vision-Language Models (VLMs) offer promising pathways to bridge this gap. To address this, we propose VLM-Enhanced Support for Surveillance and Investigations (VESSI), a VLM-based framework designed to enhance automated video surveillance analysis through prompt-driven interrogation of video sequences where salient visual features are converted into textual descriptions. We test our framework with four state-of-the-art models. Since most datasets for this task are unlabeled, we also propose the Composite Model Utility Score (CMUS) to assess VLM performance. Experimental results show that our solution substantially improves the analysis capabilities of human operators and enhances the flexibility of automated surveillance systems. In our evaluation, the most reliable model flagged potentially relevant activity in more than 66% of the videos while reducing review time by more than 85%, offering a practical balance between selectivity and efficiency. The model ordering produced by the reference-free CMUS evaluation was reproduced by the normal-video CMUS evaluation and matched the false-positive-rate ordering obtained from 5,909 manually referenced frames. This agreement supports the operational use of the score within the evaluated setting.","authors":["Saverio Cavasin","Pietro Tedeschi","Mattia Tamiazzo","Alessandro Brighente","Simone Milani","Mauro Conti"],"published":"2026-10-08T10:50:17Z","updated":"2026-10-08T10:50:17Z","abstract_url":"https://arxiv.org/abs/2610.11674v1","html_url":"https://arxiv.org/html/2610.11674v1","pdf_url":"https://arxiv.org/pdf/2610.11674v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11666v1","title":"Autoregressive Retriever: Improving Query Understanding from Item Feedback for Universal Multimodal Retrieval","abstract":"Universal multimodal retrieval typically encodes a query once and ranks independently indexed items by embedding similarity. This design supports efficient search, but leaves the query representation unchanged even when retrieved items could help clarify the information need. We introduce the AutoRegressive Retriever (ARR), a multimodal retrieval model that learns both to select informative items and to use their content to refine subsequent retrieval. ARR alternates between retrieving an item and updating the query embedding, then uses the final embedding to rank the collection. Supervised fine-tuning teaches the encoder to use feedback through stepwise contrastive supervision. Reinforcement learning treats feedback items as actions and optimizes their selection using the final reciprocal rank of a relevant item. A query-side adapter enables this optimization against a fixed item index. ARR demonstrates strong retrieval performance on both in-domain and zero-shot benchmarks, outperforming the compared baselines on average. Further analyses show that feedback improves retrieval at inference time and that training with feedback also improves the initial query embedding, before any item is observed.","authors":["Jianfei Zhao","Yifan Wang","Feng Zhang","Xin Sun","Chong Feng","Zhixing Tan","Yang Luo","Boyuan Pan","Xu Kai","Yao Hu"],"published":"2026-10-08T10:39:17Z","updated":"2026-10-08T10:39:17Z","abstract_url":"https://arxiv.org/abs/2610.11666v1","html_url":"https://arxiv.org/html/2610.11666v1","pdf_url":"https://arxiv.org/pdf/2610.11666v1.pdf","matched_keywords":["retrieval","representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11656v1","title":"DisFace3DNet: Explainable Facial Attractiveness Prediction via 3D Component Disentanglement","abstract":"Facial attractiveness prediction usually assigns one overall rating, leaving the roles of shape, appearance, and viewing conditions implicit. We propose DisFace3DNet, which uses 3D component disentanglement to learn seven component reference scores from overall ratings with auxiliary weak semantic supervision, without human-labeled component targets. Designated 3D representations and image cues feed jointly learned routes for identity, skin, hair, light, background, expression, and pose. A constrained fit then combines five static and two signed dynamic scores into the overall rating, exposing each component's numerical contribution and supporting component-specific comparisons across images. On SCUT-FBP5500, DisFace3DNet achieves a Pearson correlation of $0.8904\\pm0.0063$ (mean $\\pm$ standard deviation across five folds) with average human ratings; its component terms reconstruct every held-out prediction to numerical precision. Skin, hair, and facial shape account for the largest component-wise prediction variation. Human evaluation supports the score directions for facial shape, skin, and hair; expression agreement is weaker. DisFace3DNet thus connects overall prediction to quantitative analysis of the facial and contextual cues entering each estimate.","authors":["Fenggui Rao","Yan Luximon","Jie Zhang"],"published":"2026-10-08T10:33:54Z","updated":"2026-10-08T10:33:54Z","abstract_url":"https://arxiv.org/abs/2610.11656v1","html_url":"https://arxiv.org/html/2610.11656v1","pdf_url":"https://arxiv.org/pdf/2610.11656v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11617v1","title":"TAM: Task-Aware Memory Distillation for Efficient Spatiotemporal Prediction","abstract":"Knowledge distillation enables efficient spatiotemporal prediction by transferring knowledge from an accurate teacher to a compact student. However, matching outputs or features independently for each sample leaves cross-sample predictive structure underused. Exploiting this structure requires representations and historical references that reflect the dynamics of each task. We propose TAM, a Task-Aware Memory Distillation framework that organizes a frozen teacher's knowledge into a bounded, retrievable history. Memory entries encode latent features, forecast changes, or flow residuals, while task-specific selection rules identify relevant historical references. The student either matches the teacher's similarity distribution over shared references or regresses observation-conditioned residual prototypes. These objectives complement supervised prediction and conventional distillation. The teacher, memory, and auxiliary adapters are used only during training, leaving student inference unchanged. We evaluate TAM on video prediction, weather forecasting, and traffic flow prediction across multiple teacher-student configurations. Averaged over four paired runs, adding TAM improves SSIM on all six video datasets and reduces MSE on five relative to the corresponding KD baselines. Mean paired MSE reductions reach 1.86% on KittiCaltech, 1.93% on WeatherBench with a gSTA teacher, and 1.01% on TaxiBJ. These results demonstrate the utility of historical teacher supervision across distinct forecasting tasks without additional student inference cost.","authors":["Yuqi Li","Xiaoqin Feng","Fan Xu","Weilun Feng","Chuanguang Yang","Yingli Tian","Hao Wu"],"published":"2026-10-08T09:58:23Z","updated":"2026-10-08T09:58:23Z","abstract_url":"https://arxiv.org/abs/2610.11617v1","html_url":"https://arxiv.org/html/2610.11617v1","pdf_url":"https://arxiv.org/pdf/2610.11617v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11612v1","title":"PointVGGT: Zero-Shot Multiview RGB-D Point Cloud Registration with Visual Geometry Foundation Priors","abstract":"This paper addresses multiview RGB-D point cloud registration, aiming to estimate global rigid poses for unordered RGB-D scans and align them in a metrically consistent coordinate frame. The conventional pairwise-then-global paradigm suffers from locally optimized pairwise registration, severe error propagation and high computational burden. In particular, existing methods typically treat RGB data as a mere auxiliary matching cue and overlook the holistic geometric priors (e.g., camera poses and 3D models) encoded across image sequences. This paper introduces PointVGGT, a zero-shot framework built upon a novel \\emph{foundation-then-refinement} paradigm that systematically leverages visual geometry foundation models (e.g., VGGT) as the computational backbone for robust, training-free multiview RGB-D registration. In the foundation stage, we directly recover metrically consistent global poses (without any pairwise estimation) by grounding the scale-ambiguous pose predictions of the foundation model against metric depth observations. In the refinement stage, we introduce an efficient voxelized spatial hashing mechanism that exploits the globally coherent 3D reconstruction (induced by the foundation model) as a shared spatial anchor, enabling dense multiview correspondences in near-linear time. On top of this, an IRLS-based robust motion-only bundle adjustment is performed using a conjugate gradient solver to jointly minimize the correspondence and reprojection residuals for multiview pose refinement. Extensive experiments on indoor/object-centric/outdoor datasets verify the outstanding zero-shot registration accuracy and computational efficiency of our proposed method.","authors":["Haobo Jiang","Liang Yu","Jianmin Zheng"],"published":"2026-10-08T09:54:56Z","updated":"2026-10-08T09:54:56Z","abstract_url":"https://arxiv.org/abs/2610.11612v1","html_url":"https://arxiv.org/html/2610.11612v1","pdf_url":"https://arxiv.org/pdf/2610.11612v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11610v1","title":"Beyond Report Imitation: Clinically Aware Multi-Image Ultrasound Report Generation from Visible Evidence","abstract":"Generating ultrasound reports from multiple images requires aggregating clinical evidence across views, yet archived key frames capture only part of the dynamic examination. Raw-report imitation is therefore misaligned with visual supervision: content that is clinically valid for the full examination may be unverifiable from the images available to a model. This gap creates a clinical behavior alignment problem. A model must preserve visible findings, avoid diagnostic reversals and unsupported completion, and not collapse into conservative templates. We propose CAMEO, a Clinically Aware Multi-image Evidence-grounded Orchestration framework for ultrasound report generation. Stage I learns ultrasound visual-language primitives; Stage II performs Cross-View Evidence Grounding by distilling trusted visible report points into multi-image QA and report-style supervision; and Stage III performs Clinically Aware Preference Alignment using clinical-error-oriented preference pairs. From USReport, we construct USReport-Distilled with 17,670 evidence-grounded paired-image training instances and USReport-Pref with 21,869 preference pairs; we additionally use 25,631 PubMedVision-US ultrasound instruction samples for domain adaptation and multi-image instruction tuning. On the primary USReport-Distilled benchmark, CAMEO improves over EchoVLM from 0.25 to 0.40 BLEU-1, 0.28 to 0.45 ROUGE-1, and 0.27 to 0.43 METEOR, while raising ClinicalScore from 55.02 to 74.20. These results underscore the value of evidence-grounded supervision, clinically aware alignment, and clinically structured evaluation for reliable ultrasound report generation.","authors":["Yuchen Yang","Xin Wang","Lufan Wang","Yinghong Pan","Yujuan Feng","Yuqing Yang"],"published":"2026-10-08T09:53:46Z","updated":"2026-10-08T09:53:46Z","abstract_url":"https://arxiv.org/abs/2610.11610v1","html_url":"https://arxiv.org/html/2610.11610v1","pdf_url":"https://arxiv.org/pdf/2610.11610v1.pdf","matched_keywords":["instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11608v1","title":"S$^3$Geo: Structure-Semantic Synergistic Learning for Cross-View Geo-Localization","abstract":"Cross-view geo-localization (CVGL) aims to estimate geographic locations by matching images captured from different viewpoints, such as drone and satellite views. Existing methods mainly rely on visual representations, but often fail to jointly model fine-grained structural correspondences and semantic priors, making them prone to confusion between visually similar but semantically different regions, and thus limiting robustness under large viewpoint variations. To address these challenges, we propose \\textbf{S$^3$Geo}, a structure-semantic synergistic learning framework for cross-view matching. Specifically, we first introduce a Decoupled Query Pooling (DQP) module to extract a compact set of region-aware features from dense tokens, enabling explicit modeling of local structural patterns. We then design a query-level contrastive learning scheme with an optimal transport (OT)-based formulation to establish soft correspondences under cross-view spatial misalignment. Furthermore, we incorporate a Semantic Knowledge Distillation (SKD) strategy from a frozen CLIP teacher to transfer semantic priors and relational structures, thereby improving discrimination on hard negatives. By operating synergistically, the semantic priors provide robust contextual filtering, which guides the structural module to establish precise spatial alignments. Experiments on the University-1652 and SUES-200 datasets demonstrate that \\textbf{S$^3$Geo} consistently outperforms state-of-the-art approaches without increasing inference complexity, validating the effectiveness of jointly modeling structural and semantic information for CVGL.","authors":["Ziqian Mo","Hill Zhang","Haosheng Tan","Ling Li","Jiaheng Wei"],"published":"2026-10-08T09:51:31Z","updated":"2026-10-08T09:51:31Z","abstract_url":"https://arxiv.org/abs/2610.11608v1","html_url":"https://arxiv.org/html/2610.11608v1","pdf_url":"https://arxiv.org/pdf/2610.11608v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11579v1","title":"SV-TAD: Native Sparse Convs for Efficient Temporal Action Detection","abstract":"To adapt billion-parameter Vision Transformers for long-video understanding, recent methods freeze the backbone and train lightweight convolutional modules. While effective for parameter-efficient training, existing adapters do not reduce inference-time computation, leaving scalability with respect to video length largely unaddressed. Token selection can reduce attention cost by pruning redundant tokens, but it breaks the spatial grid structure required by convolutional adapters. This forces an expensive dense reconstruction, nullifying much of the potential speedup. We address this by introducing native sparse 2D convolutions, a primitive that allows these adapters, for the first time, to operate directly and efficiently on dynamically pruned token sets. We integrate this primitive into SV-TAD, an adapter framework for temporal action detection, reducing VideoMAEv2-L computation by up to 64% and achieving 2.2x faster inference, while maintaining state-of-the-art accuracy on THUMOS-14 and ActivityNet-1.3. When scaled to InternVideoNext-L, our approach surpasses the previous state of the art at roughly half its computational cost. Moreover, the sparse formulation naturally supports auxiliary task tokens, which improves fine-grained assembly detection on ATTACH.","authors":["Ricardo Pizarro","Roberto Valle","José M. Buenaposada","Luis M. Bergasa","Luis Baumela"],"published":"2026-10-08T09:31:38Z","updated":"2026-10-08T09:31:38Z","abstract_url":"https://arxiv.org/abs/2610.11579v1","html_url":"https://arxiv.org/html/2610.11579v1","pdf_url":"https://arxiv.org/pdf/2610.11579v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11577v1","title":"CoCam4D: Geometry-Aware Cooperative 4D Perception for Camera-Only Autonomous Driving","abstract":"Autonomous vehicles often suffer from limited perception due to occlusions, blind spots, limited sensor range, and the complex nature of surrounding environments. Multi-agent collaborative perception (CP) addresses these challenges by allowing vehicles to share sensory information and reconstruct the scene cooperatively. However, camera-only perception remains fundamentally limited by the uncertainty of distance-dependent monocular depth estimation. We propose CoCam4D, a Bayesian framework for collaborative perception that explicitly models geometric uncertainty. It uses a VGGT-based feedforward network to generate 3D Gaussian scene representations with associated uncertainty estimates, enabling multiple vehicles or agents to efficiently combine their observations. By sharing compact Gaussian primitives, reliable observations from one agent can reduce the depth uncertainty of another without requiring LiDAR sensors. To support real-world deployment, we introduce Dynamic Object Primitives (DOPs), a compact 35-byte representation designed for efficient C-V2X communication. Extensive experiments show that our proposed method consistently outperforms recent vision-only methods, achieving improvements of 11.48% on OPV2V+ and 10.62% on DAIR-V2X-C, demonstrating the potential of geometrically grounded collaborative perception for LiDAR-free autonomous driving.","authors":["Soham Pahari","Sudip Das","Arindam Das","Ujjwal Bhattacharya"],"published":"2026-10-08T09:31:28Z","updated":"2026-10-08T09:31:28Z","abstract_url":"https://arxiv.org/abs/2610.11577v1","html_url":"https://arxiv.org/html/2610.11577v1","pdf_url":"https://arxiv.org/pdf/2610.11577v1.pdf","matched_keywords":["3d","agent","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"},{"id":"2610.11572v1","title":"PAM-ToD: Plug-and-Play Appearance Modeling for Cross-Time-of-Day 3D Gaussian Splatting","abstract":"Adapting a pre-trained 3D Gaussian Splatting (3DGS) road scene to a new time of day requires learning appearance changes from a few anchor images while preserving consistent, real-time rendering. We propose PAM-ToD, a lightweight plug-in that learns color corrections while keeping the pre-trained 3DGS parameters fixed. PAM-ToD scales each Gaussian's existing color to model illumination changes and uses an additive term for additional brightness, such as when street lamps turn on at night. Under a simplified image formation model, unchanged surface albedo can be eliminated from the relation between source and target appearances, allowing us to learn these corrections without separately estimating albedo and illumination. The model corrects colors across the scene while allowing the corrections to vary by location and by Gaussian. To guide learning from a few anchor images, it discourages abrupt spatial changes in these corrections. We also introduce CARLA-ToD, a benchmark with matching geometry, camera poses, and moving-object trajectories across three times of day. A few target-time anchor images are used to train each plug-in, while separate views are used for evaluation. Across the static and dynamic settings, PAM-ToD achieves higher PSNR and lower LPIPS than the baselines, even when the anchor images come from a single synchronized capture across multiple cameras.","authors":["Kota Shimomura","Sungho Moon","Tsubasa Hirakawa","Takayoshi Yamashita","Sunghoon Im","Hironobu Fujiyoshi"],"published":"2026-10-08T09:27:17Z","updated":"2026-10-08T09:27:17Z","abstract_url":"https://arxiv.org/abs/2610.11572v1","html_url":"https://arxiv.org/html/2610.11572v1","pdf_url":"https://arxiv.org/pdf/2610.11572v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-09T07:04:58+00:00","last_seen_at":"2026-10-09T07:04:58+00:00"}],"tracked_paper_count":80,"storage_mode":"latest_overwrite"}};
